#!/usr/bin/env bash
# research-sdd-init.test.sh — RED-FIRST regression harness for research-sdd-init.sh.
#
# These fixtures back the scaffolder's SAFETY CLAIMS (never clobber, never duplicate,
# fail loud, don't corrupt the user's .gitignore) — not just the happy path. An earlier
# version of this suite was theater: it passed while three real data-loss/duplication/
# silent-failure defects were present (two fresh-context reviews caught them). Each BAD
# fixture below reproduces one of those and asserts the scaffolder REFUSES or ABORTS.
# --prove-teeth mutates the corpus-present guard and asserts a data-loss fixture then
# clobbers — proving the refuse tests depend on the guard.
#
# Usage: research-sdd-init.test.sh [--prove-teeth]      Exit: 0 = all held · 1 = regression.

set -uo pipefail
HERE="$(cd "$(dirname "$0")" && pwd)"
SUT="$HERE/../research-sdd-init.sh"
[ -f "$SUT" ] || { echo "FATAL: SUT not found: $SUT" >&2; exit 2; }
TMP="$(mktemp -d)"; trap 'chmod -R u+w "$TMP" 2>/dev/null; rm -rf "$TMP"' EXIT
pass=0; fail=0
# #1691 TMPDIR hygiene: when the caller gave a private TMPDIR (run-all does), snapshot it so the
# end-of-suite check can prove nothing but $TMP itself was added to it (a mutant's stray mktemp file
# used to survive there). Skipped when TMPDIR is unset or the shared /tmp (other processes write there).
_tmpd_snap() { find "$TMPDIR" -mindepth 1 -maxdepth 1 ! -path "$TMP" 2>/dev/null | sort; }
_TMPD_CHECK=0; [ -n "${TMPDIR:-}" ] && [ "$TMPDIR" != /tmp ] && [ -d "$TMPDIR" ] && _TMPD_CHECK=1
[ "$_TMPD_CHECK" -eq 1 ] && _TMPD_PRE="$(_tmpd_snap)"
ok() { printf '  PASS  %s\n' "$1"; pass=$((pass+1)); }
no() { printf '  FAIL  %s\n' "$1"; fail=$((fail+1)); }
# shared helpers (hoisted from the U7 block so every earlier test can use them)
# octal mode of a file, portable: GNU `stat -c %a`, else BSD/macOS `stat -f %Lp`
_u7_mode() { stat -c %a "$1" 2>/dev/null || stat -f %Lp "$1" 2>/dev/null; }
# a PATH holding ONLY the tools the SUT needs (symlinked into a private bin dir) and never jq, wherever jq is installed
_u7_nojq_path() {
  local b="$TMP/u7-nojq-bin" t p
  if [ ! -d "$b" ]; then
    mkdir -p "$b"
    for t in bash sh env cp mv rm mkdir mktemp chmod cat grep sed awk dirname basename readlink git tr head tail cmp diff find sort uniq date stat sleep wc printf ls ln touch id uname cut tee xargs timeout; do
      p="$(command -v "$t" 2>/dev/null)" && [ -x "$p" ] && ln -sf "$p" "$b/$t"
    done
  fi
  printf '%s' "$b"
}
assert_exit()   { local w="$1" l="$2"; shift 2; local g; bash "$SUT" "$@" >/dev/null 2>&1; g=$?; [ "$g" = "$w" ] && ok "$l (exit $g)" || no "$l — expected $w, got $g"; }
assert_file()   { [ -f "$2" ] && ok "$1" || no "$1 (missing: $2)"; }
assert_absent() { [ ! -e "$2" ] && ok "$1" || no "$1 (should NOT exist: $2)"; }
assert_grep()   { grep -qF "$2" "$3" 2>/dev/null && ok "$1" || no "$1 (pattern '$2' not in $3)"; }

echo "== research-sdd-init.test.sh (SUT: $(basename "$SUT")) =="

# GOOD 1 — flat scaffold on an empty target → full skeleton at root
d="$TMP/good-flat"; mkdir -p "$d"
assert_exit 0 "GOOD flat: scaffolds empty target" "$d" --corpus flat
for f in INDEX.md RESEARCH-STATE.md sources/SOURCES.md .claude/hooks/research-protocol.sh; do
  assert_file "  flat: $f" "$d/$f"
done
# eje #2 — NO per-target gen-catalog.py copy is seeded (the drift source is eliminated; CATALOG.md is
# regenerated by research-sdd-archive.sh via the kit generator). Pin that init does NOT scaffold it.
assert_absent "  flat: NO per-target tools/gen-catalog.py (eje #2)" "$d/tools/gen-catalog.py"
[ -d "$d/retros" ] && ok "  flat: retros/ at target root" || no "  flat: retros/ at target root"
assert_grep "  flat: .gitignore has .atl/"    ".atl/"    "$d/.gitignore"
assert_grep "  flat: .gitignore has .claude/" ".claude/" "$d/.gitignore"
[ -d "$d/.git" ] && ok "  flat: git initialized" || no "  flat: git initialized"
# kit-sup #5: tools/ provenance ledger seeded at target root (distinct from eje #2 gen-catalog.py drift)
assert_file "  flat: tools/README.md seeded"                     "$d/tools/README.md"
[ -s "$d/tools/README.md" ] && ok "  flat: tools/README.md non-empty (anti-silent-zero)" \
  || no "  flat: tools/README.md is empty or missing (anti-silent-zero)"
assert_grep "  flat: tools/README.md is a provenance ledger"     "Provenance" "$d/tools/README.md"

# GOOD 2 — auto nests when subject material is present; root stays clean
d="$TMP/good-nested"; mkdir -p "$d"; : > "$d/app.html"
assert_exit 0 "GOOD auto: nests on subject material" "$d" --corpus auto
assert_file   "  nested: corpus/INDEX.md"     "$d/corpus/INDEX.md"
assert_absent "  nested: NO root INDEX.md"    "$d/INDEX.md"
[ -d "$d/retros" ] && ok "  nested: retros/ at target root" || no "  nested: retros/ at root"
# kit-sup #5: tools/ at TARGET root (not corpus subdir) in nested layout
assert_file   "  nested: tools/README.md at target root"     "$d/tools/README.md"
assert_absent "  nested: NO tools/ under corpus/"            "$d/corpus/tools/README.md"

# GOOD 3 — auto on empty target → flat
d="$TMP/good-auto-empty"; mkdir -p "$d"
assert_exit 0 "GOOD auto: flat when empty" "$d" --corpus auto
assert_file "  auto-empty: root INDEX.md" "$d/INDEX.md"

# GOOD 4 — auto sees a HIDDEN subject file (dotglob) → nests
d="$TMP/good-dotfile"; mkdir -p "$d"; : > "$d/.env"
assert_exit 0 "GOOD auto: nests on a hidden subject file" "$d" --corpus auto
assert_file "  dotfile: corpus/INDEX.md" "$d/corpus/INDEX.md"

# GOOD 5 — auto on a dir whose only entry is .git/ (infra, skip-listed) → flat
d="$TMP/good-onlygit"; mkdir -p "$d/.git"
assert_exit 0 "GOOD auto: flat when only .git present" "$d" --corpus auto
assert_file "  onlygit: root INDEX.md" "$d/INDEX.md"

# GOOD 6 (kit issue #1114) — --document seeds the DOCUMENT CYCLE RESEARCH-STATE variant.
# NOTE: research-sdd-init.sh best-effort re-seeds the envelope via `research-sdd-status.sh --sync-state`
# after copying the template (reorders carried-forward fields like `method:` to the end of the envelope
# block and normalizes trailing whitespace on `last_iteration_ts:`), so a raw byte-for-byte cmp against
# the template source is NOT a valid assertion here — assert on the markers that actually distinguish
# the document-cycle variant instead.
d="$TMP/good-document"; mkdir -p "$d"
assert_exit 0 "GOOD document: scaffolds with --document" "$d" --corpus flat --document
assert_grep "  document: envelope carries method: document-cycle" "method: document-cycle" "$d/RESEARCH-STATE.md"
assert_grep "  document: has an ## Outline work-list section"    "## Outline"             "$d/RESEARCH-STATE.md"
# empty Gap-backlog + empty Blocked gaps ⇒ the template ships (and --sync-state agrees) every count as 0.
# Label says "is 0", not "re-seeded to 0": a static grep on the ALREADY-0 template can't tell "shipped
# as 0" from "correctly re-seeded" — that discriminating proof is the investigable_open check below.
for _f in requires_execution_open blocked_open deferred_open; do
  assert_grep "  document: envelope $_f is 0, matching the empty backlog" "$_f: 0" "$d/RESEARCH-STATE.md"
done
if grep -qF '<research question>' "$d/RESEARCH-STATE.md"; then
  no "  document: RESEARCH-STATE.md must NOT carry the discovery-template's placeholder gap row"
else
  ok "  document: RESEARCH-STATE.md must NOT carry the discovery-template's placeholder gap row"
fi
mkdir -p "$TMP/good-document-report"
_doc_report="$(bash "$SUT" "$TMP/good-document-report" --corpus flat --document 2>&1)"
assert_grep "  document: init report names the document-cycle mode" "mode   : document-cycle scaffold" <(printf '%s' "$_doc_report")

# GOOD 6b (kit issue #1114) — the JUDGMENT follow-ups tell a --document run to seed
# the OUTLINE, never the discovery-style "SEED 5-15 real gaps" line (which would contradict both the
# PROMPT-LOOP preflight text and the template's own "## Gap-backlog" comment).
assert_grep "  document: report step 3 names the Outline, not gap-seeding" "SEED THE OUTLINE" <(printf '%s' "$_doc_report")
if grep -qF 'SEED 5-15 real gaps' <<<"$_doc_report"; then
  no "  document: report must NOT tell a --document run to SEED 5-15 real gaps"
else
  ok "  document: report must NOT tell a --document run to SEED 5-15 real gaps"
fi

# GOOD 6c (kit issue #1114) — the NEXT line for --document must warn that
# research-sdd-status.sh's headline verdicts are gap-centric, not repeat the discovery-mode BOOTSTRAP
# claim verbatim (a fresh document-cycle corpus reports STOP/read-only-investigable-exhausted, not
# BOOTSTRAP, so that claim is simply wrong for this mode).
assert_grep "  document: NEXT line warns status verdicts are gap-centric" "GAP-CENTRIC" <(printf '%s' "$_doc_report")
if grep -qF 'it reports BOOTSTRAP until the follow-ups above are done' <<<"$_doc_report"; then
  no "  document: NEXT line must NOT repeat the discovery-mode BOOTSTRAP claim"
else
  ok "  document: NEXT line must NOT repeat the discovery-mode BOOTSTRAP claim"
fi

# GOOD 6d (kit issue #1114 review — discriminating re-seed proof, replaces the overclaiming
# "re-seeded to 0" label nit): corrupt investigable_open, re-run --sync-state, and confirm the empty
# Gap-backlog forces it back to 0 — this actually depends on --sync-state running, unlike a grep
# against a template that already ships 0.
sed -i 's/^investigable_open: [0-9]\+$/investigable_open: 9/' "$d/RESEARCH-STATE.md"
assert_grep "  document: envelope corruption fixture applied (pre-check)" "investigable_open: 9" "$d/RESEARCH-STATE.md"
bash "$HERE/../research-sdd-status.sh" "$d" --sync-state >/dev/null 2>&1
assert_grep "  document: --sync-state re-seeds investigable_open back to 0 from the empty backlog" "investigable_open: 0" "$d/RESEARCH-STATE.md"

# GOOD 7 (kit issue #1114) — omitting --document leaves the default scaffold UNCHANGED: no document-cycle
# marker leaks into RESEARCH-STATE.md, and the init report never mentions document-cycle mode.
d="$TMP/good-default-unchanged"; mkdir -p "$d"
_default_report="$(bash "$SUT" "$d" --corpus flat 2>&1)"
if grep -qF 'method: document-cycle' "$d/RESEARCH-STATE.md" || grep -qF '## Outline' "$d/RESEARCH-STATE.md"; then
  no "  default: RESEARCH-STATE.md (no --document) must NOT carry document-cycle markers"
else
  ok "  default: RESEARCH-STATE.md (no --document) must NOT carry document-cycle markers"
fi
if grep -qF 'mode   : document-cycle scaffold' <<<"$_default_report"; then
  no "  default: init report must NOT mention document-cycle mode when --document is omitted"
else
  ok "  default: init report must NOT mention document-cycle mode when --document is omitted"
fi

# _cm_digits <file>: extract any N/M ratio actually sitting on the "Coverage metric" line, using
# the SAME extraction shape research-sdd-status.sh/verify-state.sh use (case-insensitive label,
# digits/digits). Empty output = digit-free. Shared by GOOD 8 (pre- and post-sync-state) and GOOD 8b.
_cm_digits() { grep -iE '\*{0,2}coverage metric\*{0,2}:' "$1" 2>/dev/null | grep -oE '[0-9]+[[:space:]]*/[[:space:]]*[0-9]+'; }

# _coverage_section_label_count <file>: count LINES within the "## Coverage" section (up to the
# next "## " heading) that contain the phrase "coverage metric" (case-insensitive). Must be exactly
# 1 (the real Coverage metric field) — kit issue #1114: a SECOND such line (even without digits of
# its own) is what fed research-sdd-status.sh's loose, unanchored extraction the wrong ratio in the
# ORIGINAL "Outline coverage" trailing note.
_coverage_section_label_count() {
  awk '/^## Coverage/{c=1;next} /^## /{c=0} c' "$1" 2>/dev/null | grep -ci 'coverage metric'
}

# GOOD 8 (kit issue #1114) — a mid-run outline ratio recorded in the NEW "Outline coverage" line
# (never in "Coverage metric", which stays digit-free by design) must NOT trip verify-state's "stale
# denominator" WARN. This reproduces the exact repro shape: fill in ONLY the placeholders exactly as
# the template instructs ("OVERWRITE it each iteration"), KEEPING the trailing arrow note — an earlier
# version of this fixture's sed replaced the WHOLE line including that note, which hid a real defect
# (the note itself named the other field's label, so research-sdd-status.sh's loose "coverage metric"
# grep matched THIS line and stole its ratio).
d="$TMP/good-document-midrun"; mkdir -p "$d"
assert_exit 0 "GOOD document mid-run: scaffolds with --document" "$d" --corpus flat --document
sed -i "s#<outline-items-covered> / <outline-items-total>#2 / 5#" "$d/RESEARCH-STATE.md"
assert_grep "  document mid-run: Outline coverage fixture applied (pre-check, note preserved)" "**Outline coverage**: 2 / 5 covered" "$d/RESEARCH-STATE.md"
if [ "$(_coverage_section_label_count "$d/RESEARCH-STATE.md")" = 1 ]; then
  ok "  document mid-run: exactly ONE line in ## Coverage names \"coverage metric\" (the real field) — the note does not repeat that phrase"
else
  no "  document mid-run: exactly ONE line in ## Coverage should name \"coverage metric\" (found: $(_coverage_section_label_count "$d/RESEARCH-STATE.md"))"
fi
# Negative control for the exactly-one-line guard above: corrupt a SEPARATE fixture by reintroducing a
# second "coverage metric" mention in the ## Coverage section (the exact shape of the defect this guard
# exists to catch — the Outline-coverage note quoting the other field's label) and confirm the count
# assertion's own predicate actually flips to 2. This is the fixture-level mutant for a template-content
# fix; there is no script line to mutate here.
d2="$TMP/good-document-midrun-labelcount-negctrl"; mkdir -p "$d2"
bash "$SUT" "$d2" --corpus flat --document >/dev/null 2>&1
sed -i 's/Keep it honest by hand; see the note below/Keep it honest by hand; see the "Coverage metric" note below/' "$d2/RESEARCH-STATE.md"
if [ "$(_coverage_section_label_count "$d2/RESEARCH-STATE.md")" = 2 ]; then
  ok "  document mid-run negative control: reintroducing the other field's label makes the count assertion see 2 — the exactly-ONE guard is discriminating, not vacuously true"
else
  no "  document mid-run negative control: reintroducing the other field's label should make the count assertion see 2 (found: $(_coverage_section_label_count "$d2/RESEARCH-STATE.md")) — could not build the fixture"
fi
if [ -z "$(_cm_digits "$d/RESEARCH-STATE.md")" ]; then
  ok "  document mid-run: Coverage metric line stays digit-free BEFORE --sync-state (only Outline coverage carries the ratio)"
else
  no "  document mid-run: Coverage metric line stays digit-free BEFORE --sync-state (found: $(_cm_digits "$d/RESEARCH-STATE.md"))"
fi
_midrun_sync_out="$(bash "$HERE/../research-sdd-status.sh" "$d" --sync-state 2>&1)"; _midrun_sync_rc=$?
if [ "$_midrun_sync_rc" = 0 ]; then
  ok "  document mid-run: --sync-state exits 0 on a mid-run Outline-coverage corpus"
else
  no "  document mid-run: --sync-state exits 0 on a mid-run Outline-coverage corpus (rc=$_midrun_sync_rc, out=[$_midrun_sync_out])"
fi
assert_grep "  document mid-run: --sync-state derives gaps_closed=0 (not the outline numerator)" "gaps_closed=0" <(printf '%s' "$_midrun_sync_out")
assert_grep "  document mid-run: --sync-state derives known_gaps=0 (not the outline denominator)" "known_gaps=0" <(printf '%s' "$_midrun_sync_out")
if [ -z "$(_cm_digits "$d/RESEARCH-STATE.md")" ]; then
  ok "  document mid-run: Coverage metric line stays digit-free AFTER --sync-state too"
else
  no "  document mid-run: Coverage metric line stays digit-free AFTER --sync-state too (found: $(_cm_digits "$d/RESEARCH-STATE.md"))"
fi
_midrun_vs_out="$(bash "$HERE/../verify-state.sh" "$d" 2>&1)"; _midrun_vs_rc=$?
if [ "$_midrun_vs_rc" = 0 ]; then
  ok "  document mid-run: verify-state.sh exits 0 on a mid-run Outline-coverage corpus"
else
  no "  document mid-run: verify-state.sh exits 0 on a mid-run Outline-coverage corpus (rc=$_midrun_vs_rc, out=[$_midrun_vs_out])"
fi
if grep -qiF 'stale denominator' <<<"$_midrun_vs_out"; then
  no "  document mid-run: verify-state.sh must NOT WARN 'stale denominator' — out=[$_midrun_vs_out]"
else
  ok "  document mid-run: verify-state.sh must NOT WARN 'stale denominator'"
fi

# GOOD 8b — discriminating negative control (this IS the mutant for GOOD 8, no script mutant needed:
# the fix is template CONTENT, so the control reproduces the review's ORIGINAL repro shape — the ratio
# misplaced into "Coverage metric" instead of "Outline coverage" — against the SAME fixed template and
# scripts, and confirms the WARN still fires. This proves GOOD 8's pass is not a script change that
# suppressed the WARN outright; it depends on which LINE carries the ratio.
d="$TMP/good-document-midrun-negctrl"; mkdir -p "$d"
bash "$SUT" "$d" --corpus flat --document >/dev/null 2>&1
sed -i 's/\*\*Coverage metric\*\*: .*/**Coverage metric**: 2 \/ 5 closed/' "$d/RESEARCH-STATE.md"
assert_grep "  document mid-run negative control: Coverage metric misuse fixture applied (pre-check)" "**Coverage metric**: 2 / 5 closed" "$d/RESEARCH-STATE.md"
bash "$HERE/../research-sdd-status.sh" "$d" --sync-state >/dev/null 2>&1
_negctrl_out="$(bash "$HERE/../verify-state.sh" "$d" 2>&1)"
if grep -qiF 'stale denominator' <<<"$_negctrl_out"; then
  ok "  document mid-run negative control: misusing 'Coverage metric' for the ratio DOES still trigger the WARN — GOOD 8's pass is discriminating, not a blanket WARN suppression"
else
  no "  document mid-run negative control: misusing 'Coverage metric' for the ratio should still WARN (mechanism must still be intact) — out=[$_negctrl_out]"
fi

# GOOD 9 (kit issue #1114) — RESEARCH-STATE-document.template.md is required
# ONLY when --document is actually used. A target missing it must still be able to run the (far more
# common) default scaffold; only a --document run against it must FATAL.
mkdir -p "$TMP/notpldoc/toolbelt/lib"
cp -r "$HERE/../../templates" "$TMP/notpldoc/templates"
rm -f "$TMP/notpldoc/templates/RESEARCH-STATE-document.template.md"
cp "$HERE/../lib/corpus-markers.sh" "$TMP/notpldoc/toolbelt/lib/"; cp "$HERE/../lib/gh-visibility.sh" "$TMP/notpldoc/toolbelt/lib/"
cp "$SUT" "$TMP/notpldoc/toolbelt/init.sh"
d="$TMP/notpldoc-default"; mkdir -p "$d"
bash "$TMP/notpldoc/toolbelt/init.sh" "$d" --corpus flat >/dev/null 2>&1
if [ -f "$d/RESEARCH-STATE.md" ]; then
  ok "  notpldoc: default scaffold succeeds even when RESEARCH-STATE-document.template.md is absent"
else
  no "  notpldoc: default scaffold succeeds even when RESEARCH-STATE-document.template.md is absent"
fi
d="$TMP/notpldoc-document"; mkdir -p "$d"
_notpldoc_out="$(bash "$TMP/notpldoc/toolbelt/init.sh" "$d" --corpus flat --document 2>&1)"; _notpldoc_rc=$?
if [ "$_notpldoc_rc" = 2 ] && grep -qF 'RESEARCH-STATE-document.template.md' <<<"$_notpldoc_out" && [ ! -e "$d/RESEARCH-STATE.md" ]; then
  ok "  notpldoc: --document FATALs (exit 2, no write) when RESEARCH-STATE-document.template.md is absent"
else
  no "  notpldoc: --document FATALs (exit 2, no write) when RESEARCH-STATE-document.template.md is absent (rc=$_notpldoc_rc out=[$_notpldoc_out])"
fi

# _treesum <dir>: sha256 manifest of every file under <dir> (path + content), sorted. Used to prove
# "nothing written" over the WHOLE target tree (settings.json-absence alone does not cover hook files
# or RESEARCH-STATE.md). Probes for sha256sum, falls back to `shasum -a 256`, and FAILS LOUDLY with a
# typed message (never a silent empty manifest, kit CLAUDE.md §7) if neither is on PATH.
_treesum() {
  if command -v sha256sum >/dev/null 2>&1; then
    find "$1" -type f -print0 2>/dev/null | sort -z | xargs -0 sha256sum 2>/dev/null
  elif command -v shasum >/dev/null 2>&1; then
    find "$1" -type f -print0 2>/dev/null | sort -z | xargs -0 shasum -a 256 2>/dev/null
  else
    echo "_treesum: FATAL: neither sha256sum nor shasum found on PATH — cannot manifest $1" >&2
    return 1
  fi
}

# GOOD 10 (kit issue #1114) — --wire --document on an EXISTING corpus
# (no --force) is rejected loudly instead of silently ignoring --document, following the #1047
# no-silent-no-op precedent. Nothing is written: a sha256 manifest of the WHOLE target tree (every
# file, not just settings.json) is identical before and after the rejected call. The fixture corpus
# MUST be UNWIRED for this check: on an ALREADY-wired corpus, the wire-only repair path is idempotent
# and writes nothing regardless of whether the rejection guard runs first — the manifest assertion
# could never go red, even if a future edit moved the guard below the write. (Measured: with
# M-WIRE-DOC-REJECT's guard neutered, an unwired corpus's manifest CHANGES — 4 mutant FAILs — while an
# already-wired one's does not — only 3.) The corpus is wired for real ONLY AFTER this check, so the
# separate --force clobber proof further below still destroys a genuinely wired corpus.
d="$TMP/wire-document-existing-corpus"; mkdir -p "$d"
bash "$SUT" "$d" --corpus flat >/dev/null 2>&1   # UNWIRED existing corpus — see note above for why
_wdr_before="$(_treesum "$d")"
_wdr_out="$(bash "$SUT" "$d" --wire --document 2>&1)"; _wdr_rc=$?
_wdr_after="$(_treesum "$d")"
if [ "$_wdr_rc" = 2 ] && grep -qF 'usage: --document has no effect here' <<<"$_wdr_out"; then
  ok "  wire-document reject: --wire --document on an existing corpus exits 2 with a typed usage message"
else
  no "  wire-document reject: --wire --document on an existing corpus exits 2 with a typed usage message (rc=$_wdr_rc out=[$_wdr_out])"
fi
if [ "$_wdr_before" = "$_wdr_after" ] && [ -n "$_wdr_before" ]; then
  ok "  wire-document reject: whole-target-tree sha256 manifest is unchanged by the rejected call"
else
  no "  wire-document reject: whole-target-tree sha256 manifest changed (or was empty) — something was written by the rejected call"
fi
# The rejection message must NOT recommend --force as a targeted fix, and must state its real
# destructive scope (kit issue #1114).
if grep -qF 're-scaffold RESEARCH-STATE.md with the document-cycle variant' <<<"$_wdr_out"; then
  no "  force-warning: rejection message must NOT claim --force only re-scaffolds RESEARCH-STATE.md"
else
  ok "  force-warning: rejection message must NOT claim --force only re-scaffolds RESEARCH-STATE.md"
fi
assert_grep "  force-warning: rejection message states --force is NOT a targeted fix" "NOT a targeted fix" <(printf '%s' "$_wdr_out")
assert_grep "  force-warning: rejection message names --force's real destructive scope" "clobbers hand-adapted hooks, INDEX.md and real backlog rows" <(printf '%s' "$_wdr_out")

# NOW wire the corpus for real (plain --wire, no --document) so the --force clobber proof below
# destroys a genuinely WIRED, hand-adapted corpus, matching what the rejection message above warns
# about — the manifest check above already ran against the unwired state and does not depend on this.
bash "$SUT" "$d" --wire >/dev/null 2>&1
assert_file "  force-warning: fixture corpus is wired ahead of the --force clobber proof (pre-check)" "$d/.claude/settings.json"
_wdrf_settings_before="$(cat "$d/.claude/settings.json" 2>/dev/null)"
# --force still bypasses repair and re-scaffolds with --document honored (unchanged #1047 contract) —
# and IS genuinely destructive to hand-adapted CORPUS content (INDEX.md, the hook), exactly as the
# rejection message above now says. It does NOT clobber the settings.json wiring itself — that merge
# is idempotent on an unchanged hook path, so settings.json stays byte-identical; asserted below rather
# than claimed. Uses a distinctive sentinel (HANDWORK_1114) so no future hook-template wording could
# coincidentally match it.
printf '\nHANDWORK_1114\n' >> "$d/INDEX.md"
printf '\nHANDWORK_1114\n' >> "$d/.claude/hooks/research-protocol.sh"
_wdrf_out="$(bash "$SUT" "$d" --wire --document --force 2>&1)"; _wdrf_rc=$?
if [ "$_wdrf_rc" = 0 ] && grep -qF 'method: document-cycle' "$d/RESEARCH-STATE.md" 2>/dev/null; then
  ok "  wire-document reject: --wire --document --force still re-scaffolds with the document-cycle variant"
else
  no "  wire-document reject: --wire --document --force still re-scaffolds with the document-cycle variant (rc=$_wdrf_rc)"
fi
if grep -qF 'HANDWORK_1114' "$d/INDEX.md" 2>/dev/null || grep -qF 'HANDWORK_1114' "$d/.claude/hooks/research-protocol.sh" 2>/dev/null; then
  no "  force-warning: --force should be confirmed destructive — HANDWORK_1114 should be gone (it was NOT, message would be misleading either way)"
else
  ok "  force-warning: --force is confirmed destructive (HANDWORK_1114 sentinel gone from both INDEX.md and the wired hook) — the rejection message's warning is accurate, not just cautious"
fi
_wdrf_settings_after="$(cat "$d/.claude/settings.json" 2>/dev/null)"
if [ "$_wdrf_settings_before" = "$_wdrf_settings_after" ] && [ -n "$_wdrf_settings_before" ]; then
  ok "  force-warning: settings.json wiring SURVIVES --force byte-identical — --force clobbers corpus content, not the wiring itself"
else
  no "  force-warning: settings.json wiring should survive --force byte-identical (it did not, or was empty)"
fi

# BAD 1 — refuse over an existing INDEX
d="$TMP/bad-index"; mkdir -p "$d"; printf 'SENTINEL\n' > "$d/INDEX.md"
assert_exit 3 "BAD: refuses over existing INDEX.md" "$d" --corpus flat
assert_grep "  refuse: INDEX untouched" "SENTINEL" "$d/INDEX.md"

# BAD 2 (DATA-LOSS) — INDEX deleted but RESEARCH-STATE holds real curated data → must refuse, not clobber
d="$TMP/bad-dataloss"; mkdir -p "$d"; printf 'REAL HAND-CURATED GAPS\n' > "$d/RESEARCH-STATE.md"
assert_exit 3 "BAD: refuses when only RESEARCH-STATE exists (data-loss)" "$d" --corpus flat
assert_grep "  data-loss: RESEARCH-STATE untouched" "REAL HAND-CURATED GAPS" "$d/RESEARCH-STATE.md"

# BAD 3 (DUPLICATION) — a nested corpus exists; auto must NOT scaffold a second flat one
d="$TMP/bad-dup"; mkdir -p "$d/corpus" "$d/retros"; printf 'REAL NESTED CORPUS\n' > "$d/corpus/INDEX.md"
assert_exit 3 "BAD: refuses to duplicate an existing nested corpus" "$d" --corpus auto
assert_absent "  dup: NO second root INDEX.md" "$d/INDEX.md"
assert_grep   "  dup: nested corpus untouched" "REAL NESTED CORPUS" "$d/corpus/INDEX.md"

# BAD 4 (SILENT FAILURE) — read-only target → FATAL exit 2, tree left empty
# Also pins that the SUT's own writability probe fired (not an incidental downstream mkdir failure).
d="$TMP/bad-readonly"; mkdir -p "$d"; chmod 555 "$d"
ro_stderr="$(bash "$SUT" "$d" --corpus flat 2>&1 1>/dev/null)"
assert_exit 2 "BAD: read-only target fails loud (exit 2)" "$d" --corpus flat
assert_absent "  readonly: no INDEX created" "$d/INDEX.md"
grep -q "not writable" <<< "$ro_stderr" \
  && ok "  readonly: SUT's own writability probe fired ('not writable' in stderr)" \
  || no "  readonly: SUT's writability probe DID NOT fire (no 'not writable' in stderr)"
chmod u+w "$d"

# BAD 5 — nonexistent target dir
assert_exit 2 "BAD: nonexistent target dir" "$TMP/does-not-exist" --corpus flat

# BAD 5b — kit issue #1108 round 2: lib/corpus-markers.sh FILE absent → exit 1, 'cannot find
#          helper', before any scaffold write (corpus_present() cannot even be defined).
mkdir -p "$TMP/nolib5b/toolbelt"; ln -sfn "$HERE/../../templates" "$TMP/nolib5b/templates"
cp "$SUT" "$TMP/nolib5b/toolbelt/init.sh"
d="$TMP/nolib5b-target"; mkdir -p "$d"
_nolib5b_out="$(bash "$TMP/nolib5b/toolbelt/init.sh" "$d" --corpus flat 2>&1)"; _nolib5b_rc=$?
if [ "$_nolib5b_rc" = 1 ] && grep -q 'cannot find helper' <<<"$_nolib5b_out" && [ ! -e "$d/RESEARCH-STATE.md" ]; then
  ok "BAD 5b: corpus-markers helper file absent → exit 1, 'cannot find helper', no write"
else
  no "BAD 5b: corpus-markers helper file absent → exit 1, 'cannot find helper', no write" "rc=$_nolib5b_rc out=[$_nolib5b_out]"
fi

# BAD 5c — kit issue #1108 round 2: lib/corpus-markers.sh exists but defines no
#          corpus_has_marker → exit 1, 'failed to define', no write.
mkdir -p "$TMP/brokenlib5c/toolbelt/lib"; ln -sfn "$HERE/../../templates" "$TMP/brokenlib5c/templates"
cp "$SUT" "$TMP/brokenlib5c/toolbelt/init.sh"
printf '#!/usr/bin/env bash\n# broken: sources cleanly but defines no corpus_has_marker\n' \
  > "$TMP/brokenlib5c/toolbelt/lib/corpus-markers.sh"
d="$TMP/brokenlib5c-target"; mkdir -p "$d"
_brokenlib5c_out="$(bash "$TMP/brokenlib5c/toolbelt/init.sh" "$d" --corpus flat 2>&1)"; _brokenlib5c_rc=$?
if [ "$_brokenlib5c_rc" = 1 ] && grep -q 'failed to define corpus_has_marker' <<<"$_brokenlib5c_out" && [ ! -e "$d/RESEARCH-STATE.md" ]; then
  ok "BAD 5c: broken corpus-markers helper → exit 1, 'failed to define', no write"
else
  no "BAD 5c: broken corpus-markers helper → exit 1, 'failed to define', no write" "rc=$_brokenlib5c_rc out=[$_brokenlib5c_out]"
fi

# GITIGNORE 6 — pre-existing .gitignore with NO trailing newline must not fuse
d="$TMP/gi-nonewline"; mkdir -p "$d"; printf 'node_modules/' > "$d/.gitignore"   # no trailing \n
assert_exit 0 "GITIGNORE: appends without fusing the last line" "$d" --corpus flat
assert_grep "  gitignore: node_modules/ intact on its own line" "node_modules/" "$d/.gitignore"
grep -qxF 'node_modules/' "$d/.gitignore" && ok "  gitignore: node_modules/ not fused" || no "  gitignore: node_modules/ FUSED with next pattern"

# ROLLBACK 7 — a template fails mid-scaffold → clean up what THIS run created, leave NO partial tree
# PRECIOUS.md is pre-existing: rollback must NOT delete it (data-loss guard).
# A mutant rollback doing rm -rf "$target"/* would destroy PRECIOUS.md while the absence
# assertions all still pass — this sentinel makes the over-deletion visible (proven below).
cp -r "$HERE/../../templates" "$TMP/rbk-templates"
mkdir -p "$TMP/rbk/toolbelt/lib"; cp "$HERE/../lib/corpus-markers.sh" "$TMP/rbk/toolbelt/lib/"; cp "$HERE/../lib/gh-visibility.sh" "$TMP/rbk/toolbelt/lib/"; cp "$SUT" "$TMP/rbk/toolbelt/init.sh"; ln -sfn "$TMP/rbk-templates" "$TMP/rbk/templates"
chmod 000 "$TMP/rbk-templates/RESEARCH-STATE.template.md"   # 2nd cp fails after INDEX is copied
d="$TMP/rollback"; mkdir -p "$d"
printf 'PRECIOUS\n' > "$d/PRECIOUS.md"    # pre-existing file this run did NOT create
bash "$TMP/rbk/toolbelt/init.sh" "$d" --corpus flat >/dev/null 2>&1; rc=$?
[ "$rc" != 0 ] && ok "ROLLBACK: mid-scaffold failure exits non-zero (exit $rc)" || no "ROLLBACK: mid-scaffold failure exited 0"
assert_absent "  rollback: partial INDEX.md removed" "$d/INDEX.md"
assert_absent "  rollback: partial tools/ removed"   "$d/tools"
assert_absent "  rollback: no orphaned .claude/"     "$d/.claude"
assert_absent "  rollback: no orphaned retros/"      "$d/retros"
# sentinel must survive intact — rollback is scoped to what THIS run created
[ -f "$d/PRECIOUS.md" ] && ok "  rollback: sentinel PRECIOUS.md survived (rollback is scoped)" \
  || no "  rollback: sentinel PRECIOUS.md was DELETED — rollback over-deleted (DATA LOSS BUG)"
grep -qxF 'PRECIOUS' "$d/PRECIOUS.md" 2>/dev/null \
  && ok "  rollback: sentinel content unchanged (bytes intact)" \
  || no "  rollback: sentinel content corrupted or missing"
# only the sentinel must remain — no scaffold artifacts left behind
leftover="$(find "$d" -maxdepth 1 -mindepth 1 ! -name 'PRECIOUS.md' 2>/dev/null)"
[ -z "$leftover" ] && ok "  rollback: only sentinel remains (no scaffold artifacts)" \
  || no "  rollback: unexpected entries alongside sentinel: $leftover"
chmod u+w "$TMP/rbk-templates/RESEARCH-STATE.template.md"

# --force overrides the refuse
d="$TMP/force"; mkdir -p "$d"; printf 'SENTINEL\n' > "$d/INDEX.md"
assert_exit 0 "--force re-scaffolds over existing" "$d" --corpus flat --force

# --- Item 1: PROMPT-LOOP cross-references (stdout capture, no-prefix run) ---
d="$TMP/xref"; mkdir -p "$d"
bash "$SUT" "$d" --corpus flat > "$TMP/xref.out" 2>/dev/null
assert_grep "xref: step-1 has PROMPT-LOOP §b)" "PROMPT-LOOP §b)" "$TMP/xref.out"
assert_grep "xref: step-3 has §e)" "§e)" "$TMP/xref.out"
assert_grep "xref: step-4 has §c follow-up)" "§c follow-up)" "$TMP/xref.out"

# --- Item 1: step-5 conditional transparency ---
d="$TMP/nopfx"; mkdir -p "$d"
bash "$SUT" "$d" --corpus flat > "$TMP/nopfx.out" 2>/dev/null
assert_grep "step-5 note present in no-prefix run" "no --prefix given" "$TMP/nopfx.out"
if grep -qF "5. Block files use the prefix:" "$TMP/nopfx.out" 2>/dev/null; then
  no "step-5 absent in no-prefix run"
else
  ok "step-5 absent in no-prefix run"
fi
d="$TMP/pfx"; mkdir -p "$d"
bash "$SUT" "$d" --corpus flat --prefix foo > "$TMP/pfx.out" 2>/dev/null
assert_grep "step-5 present in prefix run" "5. Block files use the prefix: foo-blockN.md" "$TMP/pfx.out"
if grep -qF "no --prefix given" "$TMP/pfx.out" 2>/dev/null; then
  no "no-prefix note absent in prefix run"
else
  ok "no-prefix note absent in prefix run"
fi

# --- Item 2: already-git split message (dynamic $TMP fixture, never tests/fixtures/) ---
if ! command -v git >/dev/null 2>&1; then
  echo "  SKIP  already-git: git not on PATH"
else
  d="$TMP/already-git"; mkdir -p "$d"; git -C "$d" init -q 2>/dev/null
  bash "$SUT" "$d" --corpus flat > "$TMP/agit.out" 2>/dev/null
  assert_grep "already-git: corpus files land untracked" "corpus files land untracked" "$TMP/agit.out"
  assert_grep "already-git: .claude/ hook is gitignored" ".claude/ hook is gitignored" "$TMP/agit.out"
  assert_grep "already-git: git add --force mentioned" "git add --force" "$TMP/agit.out"
fi

# --- Item 3: NEXT next-step pointer and BOOTSTRAP mental model ---
d="$TMP/nextstep"; mkdir -p "$d"
bash "$SUT" "$d" --corpus flat > "$TMP/nextstep.out" 2>/dev/null
assert_grep "next-step: research-sdd-status.sh pointer" "research-sdd-status.sh" "$TMP/nextstep.out"
assert_grep "next-step: BOOTSTRAP in next-step section" "BOOTSTRAP" "$TMP/nextstep.out"

# --- Reframe: CONFIRM/THEN group markers and non-regressions ---
d="$TMP/reframe"; mkdir -p "$d"
bash "$SUT" "$d" --corpus flat > "$TMP/reframe.out" 2>/dev/null
assert_grep "reframe: CONFIRM group header present" "CONFIRM these are done" "$TMP/reframe.out"
assert_grep "reframe: THEN group header present" "THEN do next (post-scaffold)" "$TMP/reframe.out"
assert_grep "reframe: item-1 consequence unchanged" "cannot see its retros/" "$TMP/reframe.out"
assert_grep "reframe: item-2 cross-ref unchanged" "PROMPT-LOOP §b/§b2" "$TMP/reframe.out"
# Ordering: CONFIRM < item1 < THEN < item3 (group markers must frame items in correct order)
cl=$(grep -nF "CONFIRM these are done"      "$TMP/reframe.out" | head -1 | cut -d: -f1)
i1=$(grep -nF "1. REGISTER the target row"  "$TMP/reframe.out" | head -1 | cut -d: -f1)
tl=$(grep -nF "THEN do next (post-scaffold)" "$TMP/reframe.out" | head -1 | cut -d: -f1)
i3=$(grep -nF "3. SEED"                     "$TMP/reframe.out" | head -1 | cut -d: -f1)
if [ -n "$cl" ] && [ -n "$i1" ] && [ -n "$tl" ] && [ -n "$i3" ] \
   && [ "$cl" -lt "$i1" ] && [ "$i1" -lt "$tl" ] && [ "$tl" -lt "$i3" ]; then
  ok "reframe: group order CONFIRM<item1<THEN<item3"
else
  no "reframe: group order wrong (CONFIRM=$cl item1=$i1 THEN=$tl item3=$i3)"
fi

# EN2a — propose-never-apply wiring: default prints snippet, --wire opts in to write
# -------------------------------------------------------
# Default (no --wire): print the JSON snippet, do NOT write settings.json.
# --wire: write settings.json (requires jq); still idempotent.
# --no-wire: backward-compat alias for the new default (no write, print snippet).
echo "-- EN2a: propose-never-apply wiring --"
_en2a_has_jq=0; command -v jq >/dev/null 2>&1 && _en2a_has_jq=1

# (a-default) no flag → settings.json NOT written, JSON block printed in stdout
d="$TMP/en2a-a-default"; mkdir -p "$d"
_ad_out="$TMP/en2a-a-default.out"
bash "$SUT" "$d" --corpus flat > "$_ad_out" 2>/dev/null; _ad_rc=$?
[ "$_ad_rc" = 0 ] && ok "EN2a-(a-default) no-wire flag: exits 0" \
                  || no "EN2a-(a-default) no-wire flag: exits 0 (got $_ad_rc)"
assert_absent "EN2a-(a-default) no-wire flag: settings.json NOT written" "$d/.claude/settings.json"
assert_grep   "EN2a-(a-default) no-wire flag: JSON block in stdout"      '"hooks"' "$_ad_out"

if [ "$_en2a_has_jq" = 1 ]; then
  # (a-wire) --wire on a FRESH target requires the explicit --scaffold opt-in (kit issue #1047).
  # settings.json is created with the Stop hook; SessionStart is SKIPPED — a freshly-copied
  # hook-sessionstart.sh always carries a LIVE <SUBJECT> placeholder, so scaffold+wire in one call
  # must not wire an unadapted SessionStart card, exactly like the wire-only repair path.
  d="$TMP/en2a-a-wire"; mkdir -p "$d"
  _aw_out="$TMP/en2a-a-wire.out"; _aw_err="$TMP/en2a-a-wire.err"
  bash "$SUT" "$d" --corpus flat --wire --scaffold > "$_aw_out" 2>"$_aw_err"
  assert_file "EN2a-(a-wire) --scaffold --wire: settings.json created"               "$d/.claude/settings.json"
  if [ -f "$d/.claude/settings.json" ]; then
    assert_grep "EN2a-(a-wire) --scaffold --wire: Stop hook present"         "retro-gate-stop.sh"   "$d/.claude/settings.json"
    if grep -qF "research-protocol.sh" "$d/.claude/settings.json"; then
      no "EN2a-(a-wire) --scaffold --wire: SessionStart should NOT be wired (unadapted <SUBJECT>) but is present"
    else
      ok "EN2a-(a-wire) --scaffold --wire: SessionStart NOT wired (unadapted <SUBJECT>)"
    fi
  else
    no "EN2a-(a-wire) --scaffold --wire: Stop hook (file absent)"; no "EN2a-(a-wire) --scaffold --wire: SessionStart hook (file absent)"
  fi
  assert_grep "EN2a-(a-wire) --scaffold --wire: WARN names the unadapted file" "$d/.claude/hooks/research-protocol.sh" "$_aw_err"

  # (b-wire) --scaffold --wire + pre-existing settings.json with unrelated hook → merged, unrelated
  # preserved; SessionStart stays skipped for the same reason as (a-wire).
  d="$TMP/en2a-b-wire"; mkdir -p "$d/.claude"
  printf '{"hooks":{"PreToolUse":[{"matcher":"","hooks":[{"type":"command","command":"echo pre"}]}]}}\n' \
    > "$d/.claude/settings.json"
  bash "$SUT" "$d" --corpus flat --wire --scaffold >/dev/null 2>/dev/null
  assert_grep "EN2a-(b-wire) --scaffold --wire merge: PreToolUse preserved" "PreToolUse"         "$d/.claude/settings.json"
  assert_grep "EN2a-(b-wire) --scaffold --wire merge: Stop hook merged"     "retro-gate-stop.sh" "$d/.claude/settings.json"
  if grep -qF "research-protocol.sh" "$d/.claude/settings.json"; then
    no "EN2a-(b-wire) --scaffold --wire merge: SessionStart should NOT be merged (unadapted <SUBJECT>) but is present"
  else
    ok "EN2a-(b-wire) --scaffold --wire merge: SessionStart NOT merged (unadapted <SUBJECT>)"
  fi

  # (f-wire-only) --wire on EXISTING corpus does ONLY settings.json merge — no scaffold changes.
  # Mimics the adapt→wire flow from step 4: scaffold, adapt hook + seed state, then wire-only.
  # The adapted hook content and seeded state MUST survive (wire-only is non-destructive).
  # The <SUBJECT> placeholder is stripped here (real adaptation, not just a marker append) —
  # kit issue #1038 makes SessionStart wiring conditional on the placeholder being gone.
  d="$TMP/en2a-f-wire-only"; mkdir -p "$d"
  bash "$SUT" "$d" --corpus flat >/dev/null 2>/dev/null
  printf '%s\n' 'SEEDED-RESEARCH-STATE' >> "$d/RESEARCH-STATE.md"
  sed -i 's/<SUBJECT>/the-real-subject/g' "$d/.claude/hooks/research-protocol.sh"
  printf '%s\n' '# ADAPTED-HOOK-MARKER' >> "$d/.claude/hooks/research-protocol.sh"
  _fo_out="$TMP/en2a-f.out"; _fo_err="$TMP/en2a-f.err"
  bash "$SUT" "$d" --corpus flat --wire > "$_fo_out" 2>"$_fo_err"; _fo_rc=$?
  [ "$_fo_rc" = 0 ] && ok "EN2a-(f-wire-only) wire-only on existing corpus: exits 0" \
                     || no "EN2a-(f-wire-only) wire-only on existing corpus: expected exit 0 (got $_fo_rc) — re-run refused?"
  assert_file   "EN2a-(f-wire-only) wire-only: settings.json written"       "$d/.claude/settings.json"
  if [ -f "$d/.claude/settings.json" ]; then
    assert_grep "EN2a-(f-wire-only) wire-only: Stop hook in settings"       "retro-gate-stop.sh"   "$d/.claude/settings.json"
    assert_grep "EN2a-(f-wire-only) wire-only: SessionStart hook in settings (adapted, no <SUBJECT>)" "research-protocol.sh" "$d/.claude/settings.json"
  fi
  assert_grep   "EN2a-(f-wire-only) wire-only: SEEDED state survives"       "SEEDED-RESEARCH-STATE" "$d/RESEARCH-STATE.md"
  assert_grep   "EN2a-(f-wire-only) wire-only: ADAPTED hook survives"       "ADAPTED-HOOK-MARKER"   "$d/.claude/hooks/research-protocol.sh"

  # --- kit issue #1038: wire-only REPAIRS absent hook files, and gates SessionStart on the
  # <SUBJECT> placeholder. Real targets have a corpus but predate the hook scaffold, so the
  # wire-only path must be able to create missing hook files WITHOUT ever overwriting a
  # hand-adapted one, and must never wire an unadapted SessionStart card (#959 concern).
  echo "-- #1038: wire-only hook repair --"
  if [ "$_en2a_has_jq" != 1 ]; then
    echo "  SKIP  1038-(g)(h)(i)(j): jq not on PATH"
  else

  # (g) corpus exists, NO hooks at all → --wire CREATES both hook files (never refuses).
  # research-protocol.sh is created from the raw template, which still carries <SUBJECT> —
  # so SessionStart must be SKIPPED (WARN), while Stop is still merged.
  d="$TMP/1038-g-repair"; mkdir -p "$d"
  printf 'INDEX\n' > "$d/INDEX.md"   # corpus marker only — no .claude/hooks/ at all
  _g_out="$TMP/1038-g.out"; _g_err="$TMP/1038-g.err"
  bash "$SUT" "$d" --corpus flat --wire > "$_g_out" 2>"$_g_err"; _g_rc=$?
  [ "$_g_rc" = 0 ] && ok "1038-(g) repair on hookless corpus: exits 0" \
                    || no "1038-(g) repair on hookless corpus: expected exit 0 (got $_g_rc)"
  assert_file "1038-(g) repair: retro-gate-stop.sh created"   "$d/.claude/hooks/retro-gate-stop.sh"
  assert_file "1038-(g) repair: research-protocol.sh created" "$d/.claude/hooks/research-protocol.sh"
  if [ -f "$d/.claude/hooks/retro-gate-stop.sh" ]; then
    [ -x "$d/.claude/hooks/retro-gate-stop.sh" ] && ok "1038-(g) repair: retro-gate-stop.sh is executable" \
      || no "1038-(g) repair: retro-gate-stop.sh NOT executable"
    if grep -qF '<KIT>' "$d/.claude/hooks/retro-gate-stop.sh" || grep -qF '<TARGET>' "$d/.claude/hooks/retro-gate-stop.sh"; then
      no "1038-(g) repair: retro-gate-stop.sh still has an unsubstituted <KIT>/<TARGET> placeholder"
    else
      ok "1038-(g) repair: retro-gate-stop.sh has <KIT>/<TARGET> substituted"
    fi
    assert_grep "1038-(g) repair: retro-gate-stop.sh points at the target" "$d" "$d/.claude/hooks/retro-gate-stop.sh"
  fi
  assert_grep "1038-(g) repair: 'created:' printed for retro-gate-stop.sh"   "created: $d/.claude/hooks/retro-gate-stop.sh"   "$_g_out"
  assert_grep "1038-(g) repair: 'created:' printed for research-protocol.sh" "created: $d/.claude/hooks/research-protocol.sh" "$_g_out"
  assert_grep "1038-(g) repair: corpus untouched (INDEX.md sentinel intact)" "INDEX" "$d/INDEX.md"
  grep -qF '<SUBJECT>' "$d/.claude/hooks/research-protocol.sh" \
    && ok "1038-(g) repair: fixture precondition — created hook still has <SUBJECT>" \
    || no "1038-(g) repair: fixture precondition failed — created hook has no <SUBJECT>"
  assert_grep "1038-(g) repair: WARN names the unadapted file" "$d/.claude/hooks/research-protocol.sh" "$_g_err"
  grep -qF "<SUBJECT>" "$_g_err" && ok "1038-(g) repair: WARN mentions <SUBJECT>" \
                                  || no "1038-(g) repair: WARN does not mention <SUBJECT>"
  if [ -f "$d/.claude/settings.json" ]; then
    assert_grep "1038-(g) repair: Stop hook merged"              "retro-gate-stop.sh" "$d/.claude/settings.json"
    if grep -qF "research-protocol.sh" "$d/.claude/settings.json"; then
      no "1038-(g) repair: SessionStart should NOT be wired (unadapted <SUBJECT>) but is present"
    else
      ok "1038-(g) repair: SessionStart NOT wired (unadapted <SUBJECT>)"
    fi
  else
    no "1038-(g) repair: settings.json missing (Stop hook should have been merged)"
  fi

  # (h) a HAND-EDITED retro-gate-stop.sh must survive byte-identical (kept, never overwritten).
  d="$TMP/1038-h-keep"; mkdir -p "$d/.claude/hooks"
  printf 'INDEX\n' > "$d/INDEX.md"
  printf '#!/usr/bin/env bash\n# HAND-ADAPTED — do not clobber\nexit 0\n' > "$d/.claude/hooks/retro-gate-stop.sh"
  chmod +x "$d/.claude/hooks/retro-gate-stop.sh"
  _h_before="$(sha256sum "$d/.claude/hooks/retro-gate-stop.sh" | cut -d' ' -f1)"
  _h_out="$TMP/1038-h.out"
  bash "$SUT" "$d" --corpus flat --wire > "$_h_out" 2>/dev/null
  _h_after="$(sha256sum "$d/.claude/hooks/retro-gate-stop.sh" | cut -d' ' -f1)"
  [ "$_h_before" = "$_h_after" ] && ok "1038-(h) keep: hand-edited retro-gate-stop.sh is byte-identical after --wire" \
                                  || no "1038-(h) keep: hand-edited retro-gate-stop.sh was OVERWRITTEN"
  assert_grep "1038-(h) keep: 'kept:' printed for retro-gate-stop.sh" "kept: $d/.claude/hooks/retro-gate-stop.sh" "$_h_out"

  # (i) an ALREADY-ADAPTED research-protocol.sh (no <SUBJECT>) → SessionStart IS wired.
  d="$TMP/1038-i-adapted"; mkdir -p "$d/.claude/hooks"
  printf 'INDEX\n' > "$d/INDEX.md"
  sed 's/<SUBJECT>/the-real-subject/g' "$HERE/../../templates/hook-sessionstart.sh" \
    > "$d/.claude/hooks/research-protocol.sh"
  bash "$SUT" "$d" --corpus flat --wire >/dev/null 2>/dev/null
  if [ -f "$d/.claude/settings.json" ]; then
    assert_grep "1038-(i) adapted: SessionStart hook wired"  "research-protocol.sh" "$d/.claude/settings.json"
    assert_grep "1038-(i) adapted: Stop hook wired"          "retro-gate-stop.sh"   "$d/.claude/settings.json"
  else
    no "1038-(i) adapted: settings.json missing"
  fi
  grep -qF '<SUBJECT>' "$d/.claude/hooks/research-protocol.sh" \
    && no "1038-(i) adapted: fixture precondition failed — <SUBJECT> still present" \
    || ok "1038-(i) adapted: fixture precondition — <SUBJECT> absent"

  # (j) re-run is idempotent: no duplicate hook files, no duplicate settings entries, says "kept:".
  d="$TMP/1038-j-idem"; mkdir -p "$d"
  printf 'INDEX\n' > "$d/INDEX.md"
  bash "$SUT" "$d" --corpus flat --wire >/dev/null 2>/dev/null
  _j_out2="$TMP/1038-j2.out"
  bash "$SUT" "$d" --corpus flat --wire > "$_j_out2" 2>/dev/null; _j_rc2=$?
  [ "$_j_rc2" = 0 ] && ok "1038-(j) idempotent: second --wire run exits 0" \
                     || no "1038-(j) idempotent: second --wire run exit $_j_rc2"
  assert_grep "1038-(j) idempotent: second run reports 'kept:' for retro-gate-stop.sh" \
    "kept: $d/.claude/hooks/retro-gate-stop.sh" "$_j_out2"
  assert_grep "1038-(j) idempotent: second run reports 'kept:' for research-protocol.sh" \
    "kept: $d/.claude/hooks/research-protocol.sh" "$_j_out2"
  _j_stop_n=$(jq '[.hooks.Stop // [] | .[] | .hooks // [] | .[] | select(.command | rtrimstr("\"") | endswith("return-token-gate.sh") | not)] | length' "$d/.claude/settings.json" 2>/dev/null)
  [ "$_j_stop_n" = 1 ] && ok "1038-(j) idempotent: Stop still has exactly 1 entry after re-run" \
                         || no "1038-(j) idempotent: Stop count=$_j_stop_n (expected 1)"

  fi  # end 1038-(g)(h)(i)(j) jq guard

  # (k) jq ABSENT on a hookless corpus → NO writes at all: no hook files created, no settings.json.
  _1038k_jq_found="$(command -v jq 2>/dev/null)"
  if [ -z "$_1038k_jq_found" ]; then
    echo "  SKIP  1038-(k): jq not on PATH (cannot construct PATH-without-jq)"
  else
    _1038k_pnojq="$(_u7_nojq_path)"
    if PATH="$_1038k_pnojq" command -v jq >/dev/null 2>&1; then
      echo "  SKIP  1038-(k): jq still reachable after dir exclusion (multiple jq copies on PATH)"
    else
      d="$TMP/1038-k-nojq"; mkdir -p "$d"
      printf 'INDEX\n' > "$d/INDEX.md"
      _k_out="$TMP/1038-k.out"; _k_err="$TMP/1038-k.err"
      PATH="$_1038k_pnojq" bash "$SUT" "$d" --corpus flat --wire > "$_k_out" 2>"$_k_err"; _k_rc=$?
      [ "$_k_rc" = 0 ] && ok "1038-(k) jq-absent: exits 0 (graceful)" \
                        || no "1038-(k) jq-absent: expected exit 0 (got $_k_rc)"
      grep -qF "degraded" "$_k_err" && ok "1038-(k) jq-absent: 'degraded' in stderr" \
                                     || no "1038-(k) jq-absent: 'degraded' NOT in stderr"
      assert_absent "1038-(k) jq-absent: retro-gate-stop.sh NOT created"   "$d/.claude/hooks/retro-gate-stop.sh"
      assert_absent "1038-(k) jq-absent: research-protocol.sh NOT created" "$d/.claude/hooks/research-protocol.sh"
      assert_absent "1038-(k) jq-absent: settings.json NOT created"        "$d/.claude/settings.json"
      assert_grep   "1038-(k) jq-absent: JSON snippet printed"             '"hooks"' "$_k_out"
    fi
  fi

  # --- kit issue #1040 (round 2 of #1038): Opus-adversarial-review findings, reproduced live ---
  echo "-- #1040: wire-only hardening (dedup, pre-validation, comment-aware placeholder) --"
  if [ "$_en2a_has_jq" != 1 ]; then
    echo "  SKIP  1040-(l)(m)(n)(o): jq not on PATH"
  else

  # (l) finding 1 — a hook already registered via $CLAUDE_PROJECT_DIR (unquoted, variable-quoted,
  # braced, or the WHOLE command string quoted — round 3 finding 2, the form Claude Code's own
  # docs use and the kit's own settings.json templates carry) must be recognised as the SAME hook
  # as the absolute path this script writes, for BOTH Stop and SessionStart, or a second entry
  # gets appended (the hook then runs twice). Reproduces the real cloudflare target shape:
  # $CLAUDE_PROJECT_DIR/<rel> already registered.
  _1040l_i=0
  for _1040l_form in \
    '$CLAUDE_PROJECT_DIR/RELPATH' \
    '"$CLAUDE_PROJECT_DIR"/RELPATH' \
    '${CLAUDE_PROJECT_DIR}/RELPATH' \
    '"$CLAUDE_PROJECT_DIR/RELPATH"'; do
    _1040l_i=$((_1040l_i + 1))
    # index prefix: several forms strip down to the SAME alpha-only string (e.g. both the
    # variable-quoted and whole-string-quoted forms reduce to "CLAUDEPROJECTDIRRELPATH"), which
    # would otherwise collide on one shared fixture dir across loop iterations.
    d="$TMP/1040-l-$_1040l_i-$(printf '%s' "$_1040l_form" | tr -dc 'A-Za-z')"; mkdir -p "$d/.claude/hooks"
    printf 'INDEX\n' > "$d/INDEX.md"
    _1040l_stop_cmd="$(printf '%s' "$_1040l_form" | sed 's|RELPATH|.claude/hooks/retro-gate-stop.sh|')"
    _1040l_ss_cmd="$(printf '%s' "$_1040l_form" | sed 's|RELPATH|.claude/hooks/research-protocol.sh|')"
    jq -n --arg sc "$_1040l_stop_cmd" --arg ac "$_1040l_ss_cmd" \
      '{"hooks":{"Stop":[{"matcher":"","hooks":[{"type":"command","command":$sc}]}],"SessionStart":[{"matcher":"","hooks":[{"type":"command","command":$ac}]}]}}' \
      > "$d/.claude/settings.json"
    printf '#!/usr/bin/env bash\necho adapted, no live placeholder\n' > "$d/.claude/hooks/research-protocol.sh"
    printf '#!/usr/bin/env bash\nexit 0\n' > "$d/.claude/hooks/retro-gate-stop.sh"
    chmod +x "$d/.claude/hooks/research-protocol.sh" "$d/.claude/hooks/retro-gate-stop.sh"
    bash "$SUT" "$d" --corpus flat --wire >/dev/null 2>/dev/null
    _1040l_stop_n=$(jq '[.hooks.Stop // [] | .[] | .hooks // [] | .[] | select(.command | rtrimstr("\"") | endswith("return-token-gate.sh") | not)] | length' "$d/.claude/settings.json" 2>/dev/null)
    _1040l_ss_n=$(jq '[.hooks.SessionStart // [] | .[] | .hooks // [] | .[] | select(.command | contains("verify-skill-drift-hook.sh") | not)] | length' "$d/.claude/settings.json" 2>/dev/null)
    [ "$_1040l_stop_n" = 1 ] && ok "1040-(l) [$_1040l_form]: Stop stays at exactly 1 entry (no duplicate)" \
                              || no "1040-(l) [$_1040l_form]: Stop count=$_1040l_stop_n (expected 1 — duplicated)"
    [ "$_1040l_ss_n" = 1 ] && ok "1040-(l) [$_1040l_form]: SessionStart stays at exactly 1 entry (no duplicate)" \
                            || no "1040-(l) [$_1040l_form]: SessionStart count=$_1040l_ss_n (expected 1 — duplicated)"
    # jq-based membership check (not grep -F): the quoted variant embeds literal `"` characters
    # that JSON-escapes to `\"` on disk, so a raw substring grep is a false negative, not a
    # meaningful check.
    if jq -e --arg c "$_1040l_stop_cmd" '.hooks.Stop // [] | map(.hooks // [] | map(.command)) | add // [] | index($c) != null' \
        "$d/.claude/settings.json" >/dev/null 2>&1; then
      ok "1040-(l) [$_1040l_form]: the original $_1040l_form entry survives verbatim"
    else
      no "1040-(l) [$_1040l_form]: the original $_1040l_form entry is missing or was altered"
    fi
  done
  # control: an absolute-path entry already present (the form this script itself writes) must
  # also dedup — this is the pre-existing #1038 behaviour and must not regress.
  d="$TMP/1040-l-control-abs"; mkdir -p "$d/.claude/hooks"
  printf 'INDEX\n' > "$d/INDEX.md"
  printf '#!/usr/bin/env bash\necho adapted\n' > "$d/.claude/hooks/research-protocol.sh"
  printf '#!/usr/bin/env bash\nexit 0\n' > "$d/.claude/hooks/retro-gate-stop.sh"
  chmod +x "$d/.claude/hooks/research-protocol.sh" "$d/.claude/hooks/retro-gate-stop.sh"
  bash "$SUT" "$d" --corpus flat --wire >/dev/null 2>/dev/null   # first run: absolute-path form written
  bash "$SUT" "$d" --corpus flat --wire >/dev/null 2>/dev/null   # second run: must dedup against it
  _1040l_ctl_n=$(jq '[.hooks.SessionStart // [] | .[] | .hooks // [] | .[] | select(.command | contains("verify-skill-drift-hook.sh") | not)] | length' "$d/.claude/settings.json" 2>/dev/null)
  [ "$_1040l_ctl_n" = 1 ] && ok "1040-(l) control: absolute-path form still dedups (no regression)" \
                           || no "1040-(l) control: absolute-path SessionStart count=$_1040l_ctl_n (expected 1)"

  # (m) finding 2 (round 2) — an existing settings.json that does not even PARSE as JSON must be
  # refused BEFORE any hook file is created: exit non-zero, nothing written.
  d="$TMP/1040-m-malformed"; mkdir -p "$d/.claude"
  printf 'INDEX\n' > "$d/INDEX.md"
  printf '{"hooks": {\n' > "$d/.claude/settings.json"
  _m_before_sha="$(sha256sum "$d/.claude/settings.json" | cut -d' ' -f1)"
  _m_out="$TMP/1040-m.out"; _m_err="$TMP/1040-m.err"
  bash "$SUT" "$d" --corpus flat --wire > "$_m_out" 2>"$_m_err"; _m_rc=$?
  [ "$_m_rc" != 0 ] && ok "1040-(m) malformed settings.json: exits non-zero (got $_m_rc)" \
                     || no "1040-(m) malformed settings.json: exited 0 (should refuse)"
  assert_absent "1040-(m) malformed settings.json: retro-gate-stop.sh NOT created"   "$d/.claude/hooks/retro-gate-stop.sh"
  assert_absent "1040-(m) malformed settings.json: research-protocol.sh NOT created" "$d/.claude/hooks/research-protocol.sh"
  _m_after_sha="$(sha256sum "$d/.claude/settings.json" | cut -d' ' -f1)"
  [ "$_m_before_sha" = "$_m_after_sha" ] && ok "1040-(m) malformed settings.json: file untouched (byte-identical)" \
                                          || no "1040-(m) malformed settings.json: file was MODIFIED"
  grep -qF "refusing to wire" "$_m_err" && ok "1040-(m) malformed settings.json: typed message in stderr" \
                                         || no "1040-(m) malformed settings.json: no typed message in stderr"

  # --- kit issue #1040 round 3 finding 1: valid-JSON-but-not-usable-shape settings.json --------
  # `jq empty` (round 2) only checks that a file PARSES — it says nothing about the top-level
  # SHAPE. Three real shapes parse fine yet are unusable: an empty file, a top-level array, and
  # an object whose .hooks is not itself an object. Each one previously let both hook files get
  # created, then failed the merge downstream while still reporting exit 0 ("degraded" + success).

  # (m1) EMPTY file (`: > settings.json`) is an explicit, documented CARVE-OUT: treated as `{}`
  # (no hooks yet), NOT refused — an empty stub is not corrupt. Wiring proceeds normally.
  d="$TMP/1040-m1-empty"; mkdir -p "$d/.claude"
  printf 'INDEX\n' > "$d/INDEX.md"
  : > "$d/.claude/settings.json"
  _m1_out="$TMP/1040-m1.out"
  bash "$SUT" "$d" --corpus flat --wire > "$_m1_out" 2>/dev/null; _m1_rc=$?
  [ "$_m1_rc" = 0 ] && ok "1040-(m1) empty settings.json: exits 0 (treated as {}, not refused)" \
                     || no "1040-(m1) empty settings.json: expected exit 0 (got $_m1_rc)"
  assert_file "1040-(m1) empty settings.json: retro-gate-stop.sh created" "$d/.claude/hooks/retro-gate-stop.sh"
  assert_grep "1040-(m1) empty settings.json: Stop hook registered" "retro-gate-stop.sh" "$d/.claude/settings.json"

  # (m2) top-level ARRAY (`[]`) parses fine but is not an object — must refuse: exit 4, nothing
  # written (no hook file, no settings.json touched).
  d="$TMP/1040-m2-array"; mkdir -p "$d/.claude"
  printf 'INDEX\n' > "$d/INDEX.md"
  printf '[]' > "$d/.claude/settings.json"
  _m2_before_sha="$(sha256sum "$d/.claude/settings.json" | cut -d' ' -f1)"
  _m2_out="$TMP/1040-m2.out"; _m2_err="$TMP/1040-m2.err"
  bash "$SUT" "$d" --corpus flat --wire > "$_m2_out" 2>"$_m2_err"; _m2_rc=$?
  [ "$_m2_rc" = 4 ] && ok "1040-(m2) top-level array: exits 4 (got $_m2_rc)" \
                     || no "1040-(m2) top-level array: expected exit 4 (got $_m2_rc)"
  assert_absent "1040-(m2) top-level array: retro-gate-stop.sh NOT created"   "$d/.claude/hooks/retro-gate-stop.sh"
  assert_absent "1040-(m2) top-level array: research-protocol.sh NOT created" "$d/.claude/hooks/research-protocol.sh"
  _m2_after_sha="$(sha256sum "$d/.claude/settings.json" | cut -d' ' -f1)"
  [ "$_m2_before_sha" = "$_m2_after_sha" ] && ok "1040-(m2) top-level array: file untouched (byte-identical)" \
                                            || no "1040-(m2) top-level array: file was MODIFIED"
  grep -qF "refusing to wire" "$_m2_err" && ok "1040-(m2) top-level array: typed message in stderr" \
                                          || no "1040-(m2) top-level array: no typed message in stderr"

  # (m3) `.hooks` present but NOT an object (`{"hooks":"x"}`) — must refuse: exit 4, nothing
  # written.
  d="$TMP/1040-m3-hooksnotobj"; mkdir -p "$d/.claude"
  printf 'INDEX\n' > "$d/INDEX.md"
  printf '{"hooks":"x"}' > "$d/.claude/settings.json"
  _m3_before_sha="$(sha256sum "$d/.claude/settings.json" | cut -d' ' -f1)"
  _m3_out="$TMP/1040-m3.out"; _m3_err="$TMP/1040-m3.err"
  bash "$SUT" "$d" --corpus flat --wire > "$_m3_out" 2>"$_m3_err"; _m3_rc=$?
  [ "$_m3_rc" = 4 ] && ok "1040-(m3) .hooks not an object: exits 4 (got $_m3_rc)" \
                     || no "1040-(m3) .hooks not an object: expected exit 4 (got $_m3_rc)"
  assert_absent "1040-(m3) .hooks not an object: retro-gate-stop.sh NOT created"   "$d/.claude/hooks/retro-gate-stop.sh"
  assert_absent "1040-(m3) .hooks not an object: research-protocol.sh NOT created" "$d/.claude/hooks/research-protocol.sh"
  _m3_after_sha="$(sha256sum "$d/.claude/settings.json" | cut -d' ' -f1)"
  [ "$_m3_before_sha" = "$_m3_after_sha" ] && ok "1040-(m3) .hooks not an object: file untouched (byte-identical)" \
                                            || no "1040-(m3) .hooks not an object: file was MODIFIED"
  grep -qF "refusing to wire" "$_m3_err" && ok "1040-(m3) .hooks not an object: typed message in stderr" \
                                          || no "1040-(m3) .hooks not an object: no typed message in stderr"

  # (m4) a shape that PASSES pre-validation (.hooks IS an object) but crashes the merge filter
  # downstream (`{"hooks":{"Stop":"x"}}` — .hooks.Stop is a string, not an array) must exit
  # non-zero (4), NEVER 0 — a merge failure must never be reported as success.
  d="$TMP/1040-m4-mergefails"; mkdir -p "$d/.claude"
  printf 'INDEX\n' > "$d/INDEX.md"
  printf '{"hooks":{"Stop":"x"}}' > "$d/.claude/settings.json"
  _m4_out="$TMP/1040-m4.out"; _m4_err="$TMP/1040-m4.err"
  bash "$SUT" "$d" --corpus flat --wire > "$_m4_out" 2>"$_m4_err"; _m4_rc=$?
  [ "$_m4_rc" != 0 ] && ok "1040-(m4) merge-failure shape: exits non-zero (got $_m4_rc)" \
                      || no "1040-(m4) merge-failure shape: exited 0 (a merge failure must never report success)"

  # (m-control) a VALID, non-trivial pre-existing settings.json still proceeds normally — the
  # shape check must not become an over-eager refusal of ordinary, well-formed files.
  d="$TMP/1040-m-control-valid"; mkdir -p "$d/.claude"
  printf 'INDEX\n' > "$d/INDEX.md"
  printf '{"hooks":{"PreToolUse":[{"matcher":"","hooks":[{"type":"command","command":"echo pre"}]}]}}' \
    > "$d/.claude/settings.json"
  bash "$SUT" "$d" --corpus flat --wire >/dev/null 2>/dev/null; _mctl_rc=$?
  [ "$_mctl_rc" = 0 ] && ok "1040-(m-control) valid settings.json: exits 0 (not refused)" \
                       || no "1040-(m-control) valid settings.json: expected exit 0 (got $_mctl_rc)"
  assert_grep "1040-(m-control) valid settings.json: PreToolUse preserved" "PreToolUse" "$d/.claude/settings.json"
  assert_grep "1040-(m-control) valid settings.json: Stop hook registered" "retro-gate-stop.sh" "$d/.claude/settings.json"

  fi  # end 1040-(l)(m) jq guard

  # (n) finding 3 — <SUBJECT> inside a COMMENT line (e.g. the template's own header, kept as-is
  # by a real adaptation) must NOT block SessionStart wiring; only a LIVE occurrence counts.
  if [ "$_en2a_has_jq" != 1 ]; then
    echo "  SKIP  1040-(n): jq not on PATH"
  else
    d="$TMP/1040-n-comment-only"; mkdir -p "$d/.claude/hooks"
    printf 'INDEX\n' > "$d/INDEX.md"
    printf '#!/usr/bin/env bash\n# SessionStart hook — Research-SDD protocol for <SUBJECT>.\n# header retained as-is by the adapter\necho adapted body, no live placeholder\n' \
      > "$d/.claude/hooks/research-protocol.sh"
    _n_out="$TMP/1040-n.out"; _n_err="$TMP/1040-n.err"
    bash "$SUT" "$d" --corpus flat --wire > "$_n_out" 2>"$_n_err"
    if [ -f "$d/.claude/settings.json" ]; then
      assert_grep "1040-(n) comment-only <SUBJECT>: SessionStart still wired" "research-protocol.sh" "$d/.claude/settings.json"
    else
      no "1040-(n) comment-only <SUBJECT>: settings.json missing (SessionStart should have wired)"
    fi
    grep -qF "<SUBJECT>" "$_n_err" && no "1040-(n) comment-only <SUBJECT>: WARN wrongly fired for a comment-only occurrence" \
                                    || ok "1040-(n) comment-only <SUBJECT>: no WARN (correctly ignored the comment)"
  fi

  # (o) finding 4 — a re-run that finds a hook ALREADY registered reports "already wired", not
  # "registered" (which would misleadingly claim fresh credit for a pre-existing entry).
  if [ "$_en2a_has_jq" = 1 ]; then
    d="$TMP/1040-o-alreadywired"; mkdir -p "$d"
    printf 'INDEX\n' > "$d/INDEX.md"
    bash "$SUT" "$d" --corpus flat --wire >/dev/null 2>/dev/null   # first run: registers
    _o_out2="$TMP/1040-o2.out"
    bash "$SUT" "$d" --corpus flat --wire > "$_o_out2" 2>/dev/null   # second run: already there
    assert_grep "1040-(o) already-wired wording: Stop reported as already wired" "already wired" "$_o_out2"
    if grep -qF "Stop hook registered" "$_o_out2"; then
      no "1040-(o) already-wired wording: second run still says 'registered' for Stop (should say 'already wired')"
    else
      ok "1040-(o) already-wired wording: second run does not re-claim 'registered' for Stop"
    fi
  else
    echo "  SKIP  1040-(o): jq not on PATH"
  fi

  # (p) never-overwrite research-protocol.sh — a hand-edited SessionStart hook must survive
  # byte-identical after --wire, exactly like 1038-(h) pins for retro-gate-stop.sh.
  d="$TMP/1040-p-keep-ss"; mkdir -p "$d/.claude/hooks"
  printf 'INDEX\n' > "$d/INDEX.md"
  printf '#!/usr/bin/env bash\n# HAND-ADAPTED research-protocol.sh — do not clobber\necho adapted\n' \
    > "$d/.claude/hooks/research-protocol.sh"
  _p_before="$(sha256sum "$d/.claude/hooks/research-protocol.sh" | cut -d' ' -f1)"
  _p_out="$TMP/1040-p.out"
  bash "$SUT" "$d" --corpus flat --wire > "$_p_out" 2>/dev/null
  _p_after="$(sha256sum "$d/.claude/hooks/research-protocol.sh" | cut -d' ' -f1)"
  [ "$_p_before" = "$_p_after" ] && ok "1040-(p) keep: hand-edited research-protocol.sh is byte-identical after --wire" \
                                  || no "1040-(p) keep: hand-edited research-protocol.sh was OVERWRITTEN"
  assert_grep "1040-(p) keep: 'kept:' printed for research-protocol.sh" "kept: $d/.claude/hooks/research-protocol.sh" "$_p_out"

  # (q) round 3 finding 3 — settings.json is written PRETTY (multi-line), not compact single-line,
  # so a hand-maintained file keeps its indentation.
  if [ "$_en2a_has_jq" != 1 ]; then
    echo "  SKIP  1040-(q): jq not on PATH"
  else
    d="$TMP/1040-q-pretty"; mkdir -p "$d"
    printf 'INDEX\n' > "$d/INDEX.md"
    bash "$SUT" "$d" --corpus flat --wire >/dev/null 2>/dev/null
    _q_lines=$(wc -l < "$d/.claude/settings.json" 2>/dev/null)
    [ "${_q_lines:-0}" -gt 1 ] 2>/dev/null && ok "1040-(q) pretty-print: settings.json is multi-line ($_q_lines lines)" \
                                            || no "1040-(q) pretty-print: settings.json is single-line or missing (lines=$_q_lines)"
  fi

  # (r) round 3 finding 4 — the jq-absent print-only snippet must omit SessionStart not only for
  # a LIVE placeholder, but also when research-protocol.sh does not exist at all yet.
  _1040r_jq_found="$(command -v jq 2>/dev/null)"
  if [ -z "$_1040r_jq_found" ]; then
    echo "  SKIP  1040-(r): jq not on PATH (cannot construct PATH-without-jq)"
  else
    _1040r_pnojq="$(_u7_nojq_path)"
    if PATH="$_1040r_pnojq" command -v jq >/dev/null 2>&1; then
      echo "  SKIP  1040-(r): jq still reachable after dir exclusion (multiple jq copies on PATH)"
    else
      d="$TMP/1040-r-nojq-absent-ss"; mkdir -p "$d"
      printf 'INDEX\n' > "$d/INDEX.md"   # no .claude/hooks/ at all — research-protocol.sh absent
      _r_out="$TMP/1040-r.out"; _r_err="$TMP/1040-r.err"
      PATH="$_1040r_pnojq" bash "$SUT" "$d" --corpus flat --wire > "$_r_out" 2>"$_r_err"
      if grep -qF 'research-protocol.sh\"' "$_r_out"; then
        no "1040-(r) jq-absent + absent ss hook: snippet WRONGLY offers SessionStart"
      else
        ok "1040-(r) jq-absent + absent ss hook: snippet omits SessionStart"
      fi
      grep -qF "does not exist yet" "$_r_err" && ok "1040-(r) jq-absent + absent ss hook: WARN explains why" \
                                                || no "1040-(r) jq-absent + absent ss hook: no explanatory WARN"
      assert_grep "1040-(r) jq-absent + absent ss hook: Stop still offered" '"Stop"' "$_r_out"
    fi
  fi

  # (s) round 3 finding 5 — when SessionStart is SKIPPED for a live <SUBJECT> placeholder but an
  # entry is ALREADY present from an earlier run (left untouched by the merge — skip never
  # removes an existing entry), the message must say "already wired", not "NOT registered" (which
  # would misleadingly imply settings.json carries none).
  if [ "$_en2a_has_jq" != 1 ]; then
    echo "  SKIP  1040-(s): jq not on PATH"
  else
    d="$TMP/1040-s-skip-but-present"; mkdir -p "$d/.claude/hooks"
    printf 'INDEX\n' > "$d/INDEX.md"
    printf '#!/usr/bin/env bash\nexit 0\n' > "$d/.claude/hooks/retro-gate-stop.sh"
    chmod +x "$d/.claude/hooks/retro-gate-stop.sh"
    # research-protocol.sh carries a LIVE placeholder — skip_ss will be true.
    printf '#!/usr/bin/env bash\necho <SUBJECT> is not adapted\n' > "$d/.claude/hooks/research-protocol.sh"
    jq -n --arg ac "$d/.claude/hooks/research-protocol.sh" \
      '{"hooks":{"SessionStart":[{"matcher":"","hooks":[{"type":"command","command":$ac}]}]}}' \
      > "$d/.claude/settings.json"
    _s_out="$TMP/1040-s.out"
    bash "$SUT" "$d" --corpus flat --wire > "$_s_out" 2>/dev/null
    assert_grep "1040-(s) skip-but-present: reports 'already wired', not 'NOT registered'" "already wired" "$_s_out"
    if grep -qF "NOT registered" "$_s_out"; then
      no "1040-(s) skip-but-present: wrongly says 'NOT registered' for an entry that IS present"
    else
      ok "1040-(s) skip-but-present: does not say 'NOT registered'"
    fi
    _s_n=$(jq '[.hooks.SessionStart // [] | .[] | .hooks // [] | .[] | select(.command | contains("verify-skill-drift-hook.sh") | not)] | length' "$d/.claude/settings.json" 2>/dev/null)
    [ "$_s_n" = 1 ] && ok "1040-(s) skip-but-present: the pre-existing entry survives, uncounted twice" \
                     || no "1040-(s) skip-but-present: SessionStart count=$_s_n (expected 1)"
  fi

  # (d-wire) --wire idempotent — first run scaffolds+wires (--scaffold, kit issue #1047), second
  # run is a plain --wire (the corpus now exists, so it takes the wire-only repair path) → no
  # duplicate Stop entry. SessionStart stays skipped both times: the hook is still unadapted.
  d="$TMP/en2a-d-wire"; mkdir -p "$d"
  bash "$SUT" "$d" --corpus flat --wire --scaffold >/dev/null 2>/dev/null
  bash "$SUT" "$d" --corpus flat --wire >/dev/null 2>/dev/null
  _sc_n=$(jq '[.hooks.Stop // [] | .[] | .hooks // [] | .[] | select(.command | rtrimstr("\"") | endswith("return-token-gate.sh") | not)] | length' \
    "$d/.claude/settings.json" 2>/dev/null)
  _ss_n=$(jq '[.hooks.SessionStart // [] | .[] | .hooks // [] | .[] | select(.command | contains("verify-skill-drift-hook.sh") | not)] | length' \
    "$d/.claude/settings.json" 2>/dev/null)
  [ "$_sc_n" = 1 ] && ok "EN2a-(d-wire) idempotent: Stop has exactly 1 entry" \
                    || no "EN2a-(d-wire) idempotent: Stop count=$_sc_n (expected 1)"
  [ "$_ss_n" = 0 ] && ok "EN2a-(d-wire) idempotent: SessionStart stays skipped (live <SUBJECT>, kit issue #1047)" \
                    || no "EN2a-(d-wire) idempotent: SessionStart count=$_ss_n (expected 0 — placeholder still live)"
else
  echo "  SKIP  EN2a-(a-wire)(b-wire)(d-wire): jq not on PATH"
fi

# (c) --no-wire → backward compat: settings.json NOT written, JSON block in stdout
d="$TMP/en2a-c"; mkdir -p "$d"
_nw_out="$TMP/en2a-c.out"
bash "$SUT" "$d" --corpus flat --no-wire > "$_nw_out" 2>/dev/null; _nw_rc=$?
[ "$_nw_rc" = 0 ] && ok 'EN2a-(c) --no-wire exits 0' || no "EN2a-(c) --no-wire exits 0 (got $_nw_rc)"
assert_absent "EN2a-(c) --no-wire: settings.json NOT written" "$d/.claude/settings.json"
assert_grep   'EN2a-(c) --no-wire: JSON block in stdout'      '"hooks"' "$_nw_out"

# (e) jq-absent + --scaffold --wire on a FRESH target → 'degraded' in stderr, settings.json NOT
# created, block printed. --scaffold is required here (kit issue #1047): plain --wire on a target
# with no corpus marker refuses BEFORE the jq probe even runs — see the (a-jq-absent-refuse) test.
_jq_found="$(command -v jq 2>/dev/null)"
if [ -z "$_jq_found" ]; then
  echo "  SKIP  EN2a-(e): jq not on PATH (cannot construct PATH-without-jq)"
else
  _path_nojq="$(_u7_nojq_path)"
  if PATH="$_path_nojq" command -v jq >/dev/null 2>&1; then
    echo "  SKIP  EN2a-(e): jq still reachable after dir exclusion (multiple jq copies on PATH)"
  else
    d="$TMP/en2a-e"; mkdir -p "$d"
    _e_out="$TMP/en2a-e.out"; _e_err="$TMP/en2a-e.err"
    PATH="$_path_nojq" bash "$SUT" "$d" --corpus flat --wire --scaffold > "$_e_out" 2>"$_e_err"
    _e_rc=$?
    [ "$_e_rc" = 0 ] && ok "EN2a-(e) jq-absent + --wire: exits 0 (graceful)" \
                      || no "EN2a-(e) jq-absent + --wire: exits 0 (got $_e_rc)"
    grep -qF "degraded" "$_e_err" && ok "EN2a-(e) jq-absent + --wire: 'degraded' in stderr" \
                                   || no "EN2a-(e) jq-absent + --wire: 'degraded' NOT in stderr"
    assert_absent "EN2a-(e) jq-absent + --wire: settings.json NOT created" "$d/.claude/settings.json"
    assert_grep   "EN2a-(e) jq-absent + --wire: JSON block printed"        '"hooks"' "$_e_out"
  fi
fi

# --- kit issue #1047: --wire refuses to implicitly scaffold a target with no corpus marker -----
# Found 2026-09-24 during T7 fleet wiring: --wire on a target with NO corpus marker silently ran
# the full scaffold (created corpus/, retros/, tools/, .claude/hooks/*, appended to .gitignore,
# wired an unadapted SessionStart card) — rc=0, indistinguishable from a repair. An operator
# asking to WIRE never intends to SCAFFOLD.
echo "-- #1047: --wire refuses to scaffold a target with no corpus marker --"

# snapshot helper: hashes every file under a dir, sorted — a stronger "nothing written" check
# than presence/absence alone (it also catches an EXISTING file being silently modified). Uses
# sha256sum when present, falls back to the POSIX-standard cksum otherwise; returns 1 (prints
# nothing) when NEITHER is on PATH — the caller MUST treat that as a hard failure, never compare
# two empty snapshots and pass vacuously (kit CLAUDE.md §7 anti-silent-zero).
_1047_snapshot() {
  local d="$1" hasher
  if command -v sha256sum >/dev/null 2>&1; then hasher='sha256sum'
  elif command -v cksum >/dev/null 2>&1; then hasher='cksum'
  else return 1
  fi
  find "$d" -type f -exec "$hasher" {} \; 2>/dev/null | sort
}

# (a) in-project dir with its OWN files (no corpus marker) + --wire → refuses, typed message, the
# NEW exit code 5, and a byte-for-byte snapshot proves NOTHING was created or modified — including
# .gitignore (this proves the refusal fires before ANY mutation, not just before the corpus files).
d="$TMP/1047-a-inproject"; mkdir -p "$d"
printf 'own project file\n' > "$d/app.py"
printf 'node_modules/\n' > "$d/.gitignore"
if _1047a_before="$(_1047_snapshot "$d")"; then
  _1047a_snap_ok=1
else
  _1047a_snap_ok=0
  no "1047-(a) in-project, no marker: cannot snapshot the tree — neither sha256sum nor cksum on PATH (test environment degraded; refusing to pass vacuously)"
fi
_1047a_out="$TMP/1047-a.out"; _1047a_err="$TMP/1047-a.err"
bash "$SUT" "$d" --wire > "$_1047a_out" 2>"$_1047a_err"; _1047a_rc=$?
[ "$_1047a_rc" = 5 ] && ok "1047-(a) in-project, no marker, --wire: exits 5 (got $_1047a_rc)" \
                       || no "1047-(a) in-project, no marker, --wire: expected exit 5 (got $_1047a_rc)"
grep -qF "REFUSED" "$_1047a_err" && ok "1047-(a) in-project, no marker: typed REFUSED message in stderr" \
                                  || no "1047-(a) in-project, no marker: no typed REFUSED message in stderr"
grep -qF "kit issue #1047" "$_1047a_err" && ok "1047-(a) in-project, no marker: message names kit issue #1047" \
                                          || no "1047-(a) in-project, no marker: message does not name kit issue #1047"
grep -qF -- "--scaffold" "$_1047a_err" && ok "1047-(a) in-project, no marker: message names the --scaffold opt-in" \
                                        || no "1047-(a) in-project, no marker: message does not name --scaffold"
if [ "$_1047a_snap_ok" = 1 ]; then
  _1047a_after="$(_1047_snapshot "$d")"
  [ "$_1047a_before" = "$_1047a_after" ] && ok "1047-(a) in-project, no marker: tree byte-for-byte unchanged (nothing created or modified)" \
                                          || no "1047-(a) in-project, no marker: tree CHANGED (before/after snapshots differ)"
else
  echo "  SKIP  1047-(a) byte-for-byte snapshot: hashing tool unavailable (see FAIL above)"
fi
assert_absent "1047-(a) in-project, no marker: NO corpus/ created"     "$d/corpus"
assert_absent "1047-(a) in-project, no marker: NO retros/ created"     "$d/retros"
assert_absent "1047-(a) in-project, no marker: NO tools/ created"      "$d/tools"
assert_absent "1047-(a) in-project, no marker: NO .claude/ created"    "$d/.claude"
assert_absent "1047-(a) in-project, no marker: NO git repo initialized" "$d/.git"
grep -qxF 'node_modules/' "$d/.gitignore" 2>/dev/null && ok "1047-(a) in-project, no marker: .gitignore left untouched" \
                                                        || no "1047-(a) in-project, no marker: .gitignore was modified"

# (b) EMPTY dir + --wire → same refusal (no "own files" to preserve, but still zero-mutation).
d="$TMP/1047-b-empty"; mkdir -p "$d"
_1047b_out="$TMP/1047-b.out"; _1047b_err="$TMP/1047-b.err"
bash "$SUT" "$d" --wire > "$_1047b_out" 2>"$_1047b_err"; _1047b_rc=$?
[ "$_1047b_rc" = 5 ] && ok "1047-(b) empty dir, --wire: exits 5 (got $_1047b_rc)" \
                       || no "1047-(b) empty dir, --wire: expected exit 5 (got $_1047b_rc)"
_1047b_leftover="$(find "$d" -mindepth 1 2>/dev/null)"
[ -z "$_1047b_leftover" ] && ok "1047-(b) empty dir, --wire: dir still empty (nothing written)" \
                            || no "1047-(b) empty dir, --wire: unexpected entries: $_1047b_leftover"

_1047_has_jq=0; command -v jq >/dev/null 2>&1 && _1047_has_jq=1

# (c) NESTED corpus/INDEX.md present + --wire → the wire-only repair path still works (the
# refusal must only fire when NEITHER candidate root has a marker — a nested corpus is a valid
# marker location the script itself checks).
if [ "$_1047_has_jq" != 1 ]; then
  echo "  SKIP  1047-(c): jq not on PATH"
else
  d="$TMP/1047-c-nested"; mkdir -p "$d/corpus"
  printf 'INDEX\n' > "$d/corpus/INDEX.md"
  _1047c_out="$TMP/1047-c.out"
  bash "$SUT" "$d" --wire > "$_1047c_out" 2>/dev/null; _1047c_rc=$?
  [ "$_1047c_rc" = 0 ] && ok "1047-(c) nested corpus/INDEX.md, --wire: exits 0 (wire-only repair, not refused)" \
                         || no "1047-(c) nested corpus/INDEX.md, --wire: expected exit 0 (got $_1047c_rc)"
  assert_file "1047-(c) nested corpus/INDEX.md, --wire: settings.json written" "$d/.claude/settings.json"
  if [ -f "$d/.claude/settings.json" ]; then
    assert_grep "1047-(c) nested corpus/INDEX.md, --wire: Stop hook wired" "retro-gate-stop.sh" "$d/.claude/settings.json"
  fi
  assert_grep "1047-(c) nested corpus/INDEX.md, --wire: nested corpus untouched (INDEX sentinel intact)" "INDEX" "$d/corpus/INDEX.md"
fi

# (d) --scaffold --wire on a FRESH target (the explicit opt-in) → scaffolds AND wires; Stop is
# wired, SessionStart is SKIPPED + WARN because the freshly-copied hook still carries the LIVE
# <SUBJECT> placeholder (kit issue #1047 requirement 2 — same guard as the wire-only repair path).
if [ "$_1047_has_jq" != 1 ]; then
  echo "  SKIP  1047-(d): jq not on PATH"
else
  d="$TMP/1047-d-scaffold-wire"; mkdir -p "$d"
  _1047d_out="$TMP/1047-d.out"; _1047d_err="$TMP/1047-d.err"
  bash "$SUT" "$d" --corpus flat --scaffold --wire > "$_1047d_out" 2>"$_1047d_err"; _1047d_rc=$?
  [ "$_1047d_rc" = 0 ] && ok "1047-(d) --scaffold --wire fresh target: exits 0" \
                         || no "1047-(d) --scaffold --wire fresh target: expected exit 0 (got $_1047d_rc)"
  assert_file "1047-(d) --scaffold --wire fresh target: corpus scaffolded (INDEX.md)" "$d/INDEX.md"
  assert_file "1047-(d) --scaffold --wire fresh target: settings.json written" "$d/.claude/settings.json"
  if [ -f "$d/.claude/settings.json" ]; then
    assert_grep "1047-(d) --scaffold --wire fresh target: Stop hook wired" "retro-gate-stop.sh" "$d/.claude/settings.json"
    if grep -qF "research-protocol.sh" "$d/.claude/settings.json"; then
      no "1047-(d) --scaffold --wire fresh target: SessionStart should NOT be wired (unadapted <SUBJECT>) but is present"
    else
      ok "1047-(d) --scaffold --wire fresh target: SessionStart NOT wired (unadapted <SUBJECT>)"
    fi
  fi
  grep -qF "<SUBJECT>" "$_1047d_err" && ok "1047-(d) --scaffold --wire fresh target: WARN mentions <SUBJECT>" \
                                      || no "1047-(d) --scaffold --wire fresh target: WARN does not mention <SUBJECT>"
fi

# --- kit issue #1047 round 2: --force must not bypass the no-marker --wire refusal -------------
# RDD finding R3-force-bypasses-refusal: the refusal lived only inside the force=0 branch, so
# `--force --wire` on a marker-less target (dir with only src.c) silently scaffolded — rc=0,
# created .claude .git .gitignore corpus retros tools. --force means "bypass the anti-clobber
# guard on an EXISTING corpus", never "scaffold something that does not exist yet".
echo "-- #1047 round 2: --force does not bypass the no-marker --wire refusal --"

# (e) in-project dir with its OWN files, no corpus marker, --force --wire → still refuses (exit
# 5), tree byte-for-byte unchanged. Mirrors 1047-(a) but with --force added.
d="$TMP/1047e-force-inproject"; mkdir -p "$d"
printf 'int main(){}\n' > "$d/src.c"
if _1047e_before="$(_1047_snapshot "$d")"; then
  _1047e_snap_ok=1
else
  _1047e_snap_ok=0
  no "1047-(e) --force --wire, no marker: cannot snapshot the tree — neither sha256sum nor cksum on PATH"
fi
_1047e_out="$TMP/1047e.out"; _1047e_err="$TMP/1047e.err"
bash "$SUT" "$d" --force --wire > "$_1047e_out" 2>"$_1047e_err"; _1047e_rc=$?
[ "$_1047e_rc" = 5 ] && ok "1047-(e) --force --wire, no marker: exits 5 (got $_1047e_rc)" \
                       || no "1047-(e) --force --wire, no marker: expected exit 5 (got $_1047e_rc)"
grep -qF "REFUSED" "$_1047e_err" && ok "1047-(e) --force --wire, no marker: typed REFUSED message in stderr" \
                                  || no "1047-(e) --force --wire, no marker: no typed REFUSED message in stderr"
if [ "$_1047e_snap_ok" = 1 ]; then
  _1047e_after="$(_1047_snapshot "$d")"
  [ "$_1047e_before" = "$_1047e_after" ] && ok "1047-(e) --force --wire, no marker: tree byte-for-byte unchanged" \
                                          || no "1047-(e) --force --wire, no marker: tree CHANGED (before/after snapshots differ)"
fi
assert_absent "1047-(e) --force --wire, no marker: NO corpus/ created"     "$d/corpus"
assert_absent "1047-(e) --force --wire, no marker: NO retros/ created"     "$d/retros"
assert_absent "1047-(e) --force --wire, no marker: NO tools/ created"      "$d/tools"
assert_absent "1047-(e) --force --wire, no marker: NO .claude/ created"    "$d/.claude"
assert_absent "1047-(e) --force --wire, no marker: NO git repo initialized" "$d/.git"

# (f) regression safety net: --force --wire on an EXISTING corpus is UNCHANGED — it still
# bypasses wire-only repair and falls through to a full re-scaffold (this round only closes the
# no-marker gap; it must not touch the existing-corpus + --force contract).
if [ "$_1047_has_jq" != 1 ]; then
  echo "  SKIP  1047-(f): jq not on PATH"
else
  d="$TMP/1047f-force-existing"; mkdir -p "$d"
  printf 'SENTINEL\n' > "$d/INDEX.md"
  _1047f_out="$TMP/1047f.out"
  bash "$SUT" "$d" --corpus flat --force --wire > "$_1047f_out" 2>/dev/null; _1047f_rc=$?
  [ "$_1047f_rc" = 0 ] && ok "1047-(f) --force --wire, EXISTING corpus: exits 0 (unchanged contract)" \
                         || no "1047-(f) --force --wire, EXISTING corpus: expected exit 0 (got $_1047f_rc)"
  assert_file "1047-(f) --force --wire, EXISTING corpus: RESEARCH-STATE.md re-scaffolded" "$d/RESEARCH-STATE.md"
fi

# --- kit issue #1047 round 2: multi-focus corpora (RESEARCH-STATE-<focus>.md) are a marker ------
# RDD finding: a multi-focus-only corpus (no plain RESEARCH-STATE.md, only RESEARCH-STATE-
# <focus>.md — §16 naming convention, same glob lib/state-files.sh uses) must be recognised as a
# present corpus by BOTH the --wire refusal check and the anti-clobber guard.
echo "-- #1047 round 2: RESEARCH-STATE-<focus>.md counts as a corpus marker --"

if [ "$_1047_has_jq" != 1 ]; then
  echo "  SKIP  1047-(g)(h): jq not on PATH"
else
  # (g) multi-focus-only corpus (RESEARCH-STATE-frontend.md, no plain RESEARCH-STATE.md) + --wire
  # → takes the wire-only REPAIR path (exit 0), never the no-marker refusal (exit 5).
  d="$TMP/1047g-multifocus"; mkdir -p "$d"
  printf 'state\n' > "$d/RESEARCH-STATE-frontend.md"
  _1047g_out="$TMP/1047g.out"
  bash "$SUT" "$d" --wire > "$_1047g_out" 2>/dev/null; _1047g_rc=$?
  [ "$_1047g_rc" = 0 ] && ok "1047-(g) multi-focus-only corpus, --wire: exits 0 (wire-only repair, not refused)" \
                         || no "1047-(g) multi-focus-only corpus, --wire: expected exit 0 (got $_1047g_rc)"
  assert_file "1047-(g) multi-focus-only corpus, --wire: settings.json written" "$d/.claude/settings.json"
  assert_grep "1047-(g) multi-focus-only corpus, --wire: multi-focus state file untouched" "state" "$d/RESEARCH-STATE-frontend.md"

  # (h) anti-clobber: --scaffold --wire on the SAME multi-focus-only corpus must NOT scaffold a
  # second corpus next to it — the wire-only repair path takes precedence over --scaffold once a
  # corpus is present.
  d="$TMP/1047h-multifocus-scaffold"; mkdir -p "$d"
  printf 'state\n' > "$d/RESEARCH-STATE-backend.md"
  _1047h_out="$TMP/1047h.out"
  bash "$SUT" "$d" --scaffold --wire > "$_1047h_out" 2>/dev/null; _1047h_rc=$?
  [ "$_1047h_rc" = 0 ] && ok "1047-(h) multi-focus-only corpus, --scaffold --wire: exits 0 (wire-only repair)" \
                         || no "1047-(h) multi-focus-only corpus, --scaffold --wire: expected exit 0 (got $_1047h_rc)"
  assert_absent "1047-(h) multi-focus-only corpus, --scaffold --wire: NO plain RESEARCH-STATE.md scaffolded" "$d/RESEARCH-STATE.md"
  assert_absent "1047-(h) multi-focus-only corpus, --scaffold --wire: NO INDEX.md scaffolded" "$d/INDEX.md"
  assert_absent "1047-(h) multi-focus-only corpus, --scaffold --wire: NO second sources/ scaffolded" "$d/sources"
fi

# (i) the refusal message lists EVERY recognized marker form, including RESEARCH-STATE-<focus>.md
d="$TMP/1047i-message"; mkdir -p "$d"
_1047i_err="$TMP/1047i.err"
bash "$SUT" "$d" --wire >/dev/null 2>"$_1047i_err"
assert_grep "1047-(i) refusal message names INDEX.md"              "INDEX.md"               "$_1047i_err"
assert_grep "1047-(i) refusal message names RESEARCH-STATE.md"     "RESEARCH-STATE.md"      "$_1047i_err"
assert_grep "1047-(i) refusal message names RESEARCH-STATE-<focus>.md (multi-focus §16)" "RESEARCH-STATE-<focus>.md" "$_1047i_err"
assert_grep "1047-(i) refusal message names CATALOG.md"            "CATALOG.md"             "$_1047i_err"

# --- kit issue #1047 round 2: --scaffold without --wire is a typed usage error -------------------
echo "-- #1047 round 2: --scaffold without --wire is rejected --"
d="$TMP/1047j-scaffold-only"; mkdir -p "$d"
_1047j_out="$TMP/1047j.out"; _1047j_err="$TMP/1047j.err"
bash "$SUT" "$d" --scaffold > "$_1047j_out" 2>"$_1047j_err"; _1047j_rc=$?
[ "$_1047j_rc" = 2 ] && ok "1047-(j) --scaffold without --wire: exits 2 (usage error)" \
                       || no "1047-(j) --scaffold without --wire: expected exit 2 (got $_1047j_rc)"
grep -qF -- "--scaffold requires --wire" "$_1047j_err" && ok "1047-(j) --scaffold without --wire: typed usage message in stderr" \
                                                         || no "1047-(j) --scaffold without --wire: no typed usage message in stderr"
assert_absent "1047-(j) --scaffold without --wire: NO INDEX.md scaffolded (refused before any write)" "$d/INDEX.md"
# --scaffold + --wire together remains valid (regression check against the new usage guard)
d="$TMP/1047j-scaffold-wire-ok"; mkdir -p "$d"
_1047jok_rc=""
bash "$SUT" "$d" --corpus flat --scaffold --wire >/dev/null 2>/dev/null; _1047jok_rc=$?
[ "$_1047jok_rc" = 0 ] && ok "1047-(j) --scaffold --wire together: still exits 0 (usage guard does not over-reject)" \
                        || no "1047-(j) --scaffold --wire together: expected exit 0 (got $_1047jok_rc)"

# TPL — template wording: installed hook must NOT ask user which tool; must say to pick yourself
echo "-- TPL: SessionStart hook template wording --"
d="$TMP/tpl-wording"; mkdir -p "$d"
bash "$SUT" "$d" --corpus flat >/dev/null 2>/dev/null
_tpl_hook="$d/.claude/hooks/research-protocol.sh"
if [ -f "$_tpl_hook" ]; then
  if grep -qF "ask which toolbelt tool" "$_tpl_hook" 2>/dev/null; then
    no "TPL: installed hook does NOT contain 'ask which toolbelt tool' (old wording still present)"
  else
    ok "TPL: installed hook does not contain 'ask which toolbelt tool' (old wording removed)"
  fi
  if grep -qF "tool-registry.md" "$_tpl_hook" 2>/dev/null; then
    ok "TPL: installed hook contains 'tool-registry.md' pointer"
  else
    no "TPL: installed hook missing 'tool-registry.md' pointer"
  fi
  if grep -qF "yourself" "$_tpl_hook" 2>/dev/null; then
    ok "TPL: installed hook contains 'yourself' (choose tool yourself)"
  else
    no "TPL: installed hook missing 'yourself' (choose tool yourself)"
  fi
else
  no "TPL: research-protocol.sh not found at $_tpl_hook (file absent)"
fi

# ---- kit issue #1024 round 4, SYSTEMIC: symlinked toolbelt (render dir) ---------------------------
# KIT used to be derived via `cd "$(dirname "$0")/.." && pwd` WITHOUT -P. TPL="$KIT/templates" alone
# self-heals through a render dir's symlinked toolbelt/ (kit issue #993 WU2 + #1024 F1 also
# completes templates/ as its own top-level symlink) — but $KIT is ALSO embedded VERBATIM into
# user-facing guidance text (the "REGISTER ... in $KIT/TARGETS.md", "$KIT/toolbelt/ensure-remote.sh"
# and "$KIT/toolbelt/research-sdd-status.sh" lines) and spliced into the deployed retro-gate hook
# (`sed -i "s|<KIT>|$KIT|g"`). A wrong KIT there is not a crash — it is a PERSISTED and PRINTED
# path pointing at the ephemeral render dir instead of the durable kit root. Reproduced against a
# hand-reverted copy: the guidance named `.../research-sdd/profile/general/TARGETS.md` (the render
# dir — would not durably exist once the render is cleaned up) instead of the real kit's TARGETS.md.
# Built as a fully SYNTHETIC nested mini-kit (mktemp -d) with a render dir whose toolbelt/ is a
# genuine whole-directory SYMLINK (the real F1 shape) — never the live tracked toolbelt/.
_ki_altkit="$TMP/ki-altkit"
mkdir -p "$_ki_altkit/toolbelt/lib"
cp "$HERE/../lib/corpus-markers.sh" "$_ki_altkit/toolbelt/lib/"; cp "$HERE/../lib/gh-visibility.sh" "$_ki_altkit/toolbelt/lib/"
cp "$SUT" "$_ki_altkit/toolbelt/research-sdd-init.sh"
chmod +x "$_ki_altkit/toolbelt/research-sdd-init.sh"
ln -sfn "$HERE/../../templates" "$_ki_altkit/templates"
mkdir -p "$_ki_altkit/render/profile/general" "$_ki_altkit/newtarget"
ln -s "$_ki_altkit/toolbelt" "$_ki_altkit/render/profile/general/toolbelt"
# F1 completion (kit issue #993 WU2 + #1024 F1) symlinks templates/ into the render dir too.
ln -sfn "$HERE/../../templates" "$_ki_altkit/render/profile/general/templates"
_ki_out="$(bash "$_ki_altkit/render/profile/general/toolbelt/research-sdd-init.sh" \
  "$_ki_altkit/newtarget" --corpus flat 2>&1)"
if <<<"$_ki_out" grep -qF "$_ki_altkit/toolbelt/ensure-remote.sh" \
   && ! <<<"$_ki_out" grep -qF '/render/profile/general/'; then
  ok "SYMLINK-TOOLBELT: invoked through a symlinked toolbelt/, guidance text names the real kit root"
else
  no "SYMLINK-TOOLBELT: guidance text leaked the render dir instead of the real kit root (out=[$_ki_out])"
fi

# ---- kit issue #1043 -------------------------------------------------------------------------
# (1) sed-substitution metacharacters in the target path: `&` re-inserts the matched <TARGET>, `|`
# is the s||| delimiter and `\` is an escape. The rendered hook must carry the LITERAL path.
_k1_name='a&b|c\d'
d="$TMP/k1/$_k1_name"; mkdir -p "$d"
assert_exit 0 "K1043-1 scaffold: target path with & | \\ scaffolds" "$d" --corpus flat
if grep -qxF "TARGET=\"$d\" # replaced by research-sdd-init.sh: absolute path to this research target" "$d/.claude/hooks/retro-gate-stop.sh"; then
  ok "K1043-1 scaffold: retro-gate-stop.sh carries the literal target path"
else
  no "K1043-1 scaffold: TARGET line mangled: $(grep -m1 '^TARGET=' "$d/.claude/hooks/retro-gate-stop.sh")"
fi
d="$TMP/k1w/$_k1_name"; mkdir -p "$d"; : > "$d/INDEX.md"
assert_exit 0 "K1043-1 wire-only: target path with & | \\ repairs hooks" "$d" --wire
if grep -qxF "TARGET=\"$d\" # replaced by research-sdd-init.sh: absolute path to this research target" "$d/.claude/hooks/retro-gate-stop.sh"; then
  ok "K1043-1 wire-only: retro-gate-stop.sh carries the literal target path"
else
  no "K1043-1 wire-only: TARGET line mangled: $(grep -m1 '^TARGET=' "$d/.claude/hooks/retro-gate-stop.sh" 2>&1)"
fi

# (2) dangling-symlink research-protocol.sh: every precondition is checked BEFORE any write, so the
# refusal leaves NO partial state (previously retro-gate-stop.sh was created, then cp refused).
d="$TMP/k2w"; mkdir -p "$d/.claude/hooks"; : > "$d/INDEX.md"
ln -s "$d/does-not-exist" "$d/.claude/hooks/research-protocol.sh"
bash "$SUT" "$d" --wire >/dev/null 2>&1; _k2_rc=$?
[ "$_k2_rc" != 0 ] && ok "K1043-2 wire-only: dangling research-protocol.sh symlink refused (exit $_k2_rc)" \
  || no "K1043-2 wire-only: dangling symlink did not fail"
assert_absent "K1043-2 wire-only: NO retro-gate-stop.sh left behind" "$d/.claude/hooks/retro-gate-stop.sh"
assert_absent "K1043-2 wire-only: NO settings.json written"         "$d/.claude/settings.json"
[ -L "$d/.claude/hooks/research-protocol.sh" ] && ok "K1043-2 wire-only: the user's symlink is untouched" \
  || no "K1043-2 wire-only: the user's symlink was removed"
d="$TMP/k2s"; mkdir -p "$d/.claude/hooks"
ln -s "$d/does-not-exist" "$d/.claude/hooks/research-protocol.sh"
bash "$SUT" "$d" --corpus flat >/dev/null 2>&1; _k2_rc=$?
[ "$_k2_rc" != 0 ] && ok "K1043-2 scaffold: dangling research-protocol.sh symlink refused (exit $_k2_rc)" \
  || no "K1043-2 scaffold: dangling symlink did not fail"
assert_absent "K1043-2 scaffold: NO INDEX.md left behind" "$d/INDEX.md"
assert_absent "K1043-2 scaffold: NO retros/ left behind"  "$d/retros"
[ -L "$d/.claude/hooks/research-protocol.sh" ] && ok "K1043-2 scaffold: the user's symlink is untouched" \
  || no "K1043-2 scaffold: the user's symlink was removed by rollback"

# (3) settings.json merge preserves mode and writes THROUGH a symlink (--wire on an existing corpus
# and --scaffold --wire on a marker-less target both go through the merge).
d="$TMP/k3w"; mkdir -p "$d/.claude"; : > "$d/INDEX.md"
printf '{"permissions":{}}\n' > "$d/.claude/settings.json"; chmod 644 "$d/.claude/settings.json"
bash "$SUT" "$d" --wire >/dev/null 2>&1
_k3_mode="$(_u7_mode "$d/.claude/settings.json")"
[ "$_k3_mode" = 644 ] && ok "K1043-3 wire-only: settings.json mode preserved (644)" \
  || no "K1043-3 wire-only: settings.json mode became $_k3_mode"
grep -qF 'retro-gate-stop.sh' "$d/.claude/settings.json" && ok "K1043-3 wire-only: merge still applied" || no "K1043-3 wire-only: merge missing"
d="$TMP/k3l"; mkdir -p "$d/.claude" "$d/real"; : > "$d/INDEX.md"
printf '{"permissions":{}}\n' > "$d/real/settings.json"; chmod 640 "$d/real/settings.json"
ln -s "$d/real/settings.json" "$d/.claude/settings.json"
bash "$SUT" "$d" --wire >/dev/null 2>&1
[ -L "$d/.claude/settings.json" ] && ok "K1043-3 wire-only: symlinked settings.json is still a symlink" \
  || no "K1043-3 wire-only: symlink replaced by a regular file"
grep -qF 'retro-gate-stop.sh' "$d/real/settings.json" && ok "K1043-3 wire-only: merge landed in the link target" \
  || no "K1043-3 wire-only: link target not updated"
[ "$(_u7_mode "$d/real/settings.json")" = 640 ] && ok "K1043-3 wire-only: link target mode preserved (640)" \
  || no "K1043-3 wire-only: link target mode became $(_u7_mode "$d/real/settings.json")"
d="$TMP/k3s"; mkdir -p "$d/.claude"
printf '{"permissions":{}}\n' > "$d/.claude/settings.json"; chmod 644 "$d/.claude/settings.json"
bash "$SUT" "$d" --corpus flat --wire --scaffold >/dev/null 2>&1
[ "$(_u7_mode "$d/.claude/settings.json")" = 644 ] && ok "K1043-3 scaffold+wire: settings.json mode preserved (644)" \
  || no "K1043-3 scaffold+wire: settings.json mode became $(_u7_mode "$d/.claude/settings.json")"
d="$TMP/k3sl"; mkdir -p "$d/.claude" "$d/real"
printf '{"permissions":{}}\n' > "$d/real/settings.json"
ln -s "$d/real/settings.json" "$d/.claude/settings.json"
bash "$SUT" "$d" --corpus flat --wire --scaffold >/dev/null 2>&1
{ [ -L "$d/.claude/settings.json" ] && grep -qF 'retro-gate-stop.sh' "$d/real/settings.json"; } \
  && ok "K1043-3 scaffold+wire: merge written through the symlink" \
  || no "K1043-3 scaffold+wire: symlinked settings.json replaced or not updated"
# dangling settings.json symlink: typed refusal, nothing written
d="$TMP/k3d"; mkdir -p "$d/.claude"; : > "$d/INDEX.md"
ln -s "$d/nowhere/settings.json" "$d/.claude/settings.json"
bash "$SUT" "$d" --wire >/dev/null 2>&1; _k3_rc=$?
[ "$_k3_rc" = 4 ] && ok "K1043-3 wire-only: dangling settings.json symlink refused (exit 4)" \
  || no "K1043-3 wire-only: dangling settings.json symlink exit $_k3_rc (want 4)"
assert_absent "K1043-3 wire-only: dangling settings case wrote no hook file" "$d/.claude/hooks/retro-gate-stop.sh"

# ---- kit issue #1043 fix-first round ----------------------------------------------------------
# (B) atomic settings install: a mid-write failure (ulimit -f) must leave the ORIGINAL bytes and no temp.
d="$TMP/k4a"; mkdir -p "$d/.claude"; : > "$d/INDEX.md"
python3 -c 'import json,sys; json.dump({"permissions":{"allow":["Bash(x%d:*)" % i for i in range(1500)]}}, open(sys.argv[1],"w"), indent=2)' "$d/.claude/settings.json"
_k4a_before="$(sha256sum "$d/.claude/settings.json")"
# A `cat` shim that fails mid-write ONLY when its stdout is a regular file (the install redirect), and
# is the real cat for pipes/command substitution (ulimit -f would kill jq's own temp write first).
_k4a_shim="$TMP/k4a-shim"; mkdir -p "$_k4a_shim"; _k4a_realcat="$(type -P cat)"
cat > "$_k4a_shim/cat" <<SHIM
#!/usr/bin/env bash
if [ -f /dev/stdout ] && [ ! -p /dev/stdout ]; then head -c 10 "\$1"; exit 1; fi
exec "$_k4a_realcat" "\$@"
SHIM
chmod +x "$_k4a_shim/cat"
( PATH="$_k4a_shim:$PATH" bash "$SUT" "$d" --wire >/dev/null 2>&1 ); _k4a_rc=$?
[ "$_k4a_rc" != 0 ] && ok "K1043-B atomic: failed write exits non-zero (exit $_k4a_rc)" || no "K1043-B atomic: failed write reported success"
[ "$(sha256sum "$d/.claude/settings.json")" = "$_k4a_before" ] && ok "K1043-B atomic: original settings.json bytes survive a mid-write failure" \
  || no "K1043-B atomic: settings.json was truncated/modified ($(wc -c < "$d/.claude/settings.json") bytes)"
_k4a_tmp="$(find "$d/.claude" -maxdepth 1 -name '.settings.*' | wc -l)"
[ "$_k4a_tmp" = 0 ] && ok "K1043-B atomic: no temp file left behind" || no "K1043-B atomic: $_k4a_tmp temp file(s) left in .claude"

# (2) dangling DIRECTORY symlinks (.claude, .claude/hooks) are refused pre-write, link survives.
d="$TMP/k4b"; mkdir -p "$d/.claude"
ln -s "$d/nowhere" "$d/.claude/hooks"
bash "$SUT" "$d" --corpus flat >/dev/null 2>&1; _rc=$?
{ [ "$_rc" = 2 ] && [ -L "$d/.claude/hooks" ] && [ ! -e "$d/INDEX.md" ]; } \
  && ok "K1043-2 scaffold: dangling .claude/hooks symlink refused (exit 2), link survives, nothing created" \
  || no "K1043-2 scaffold: dangling .claude/hooks rc=$_rc link=$([ -L "$d/.claude/hooks" ] && echo kept || echo DELETED)"
d="$TMP/k4c"; mkdir -p "$d"; ln -s "$d/nowhere" "$d/.claude"
bash "$SUT" "$d" --corpus flat >/dev/null 2>&1; _rc=$?
{ [ "$_rc" = 2 ] && [ -L "$d/.claude" ]; } && ok "K1043-2 scaffold: dangling .claude symlink refused, link survives" \
  || no "K1043-2 scaffold: dangling .claude rc=$_rc link=$([ -L "$d/.claude" ] && echo kept || echo DELETED)"
d="$TMP/k4d"; mkdir -p "$d/.claude"; : > "$d/INDEX.md"; ln -s "$d/nowhere" "$d/.claude/hooks"
bash "$SUT" "$d" --wire >/dev/null 2>&1; _rc=$?
{ [ "$_rc" = 2 ] && [ -L "$d/.claude/hooks" ]; } && ok "K1043-2 wire-only: dangling .claude/hooks symlink refused, link survives" \
  || no "K1043-2 wire-only: dangling .claude/hooks rc=$_rc"

# (3) newline in the target path: typed refusal up front, nothing written.
d="$TMP/k4e/a
b"; mkdir -p "$d"; : > "$d/INDEX.md"
bash "$SUT" "$d" --wire >/dev/null 2>"$TMP/k4e.err"; _rc=$?
{ [ "$_rc" = 2 ] && grep -q 'newline' "$TMP/k4e.err" && [ ! -e "$d/.claude" ]; } \
  && ok "K1043-3 newline: target path with a newline refused (exit 2, typed message, nothing written)" \
  || no "K1043-3 newline: rc=$_rc err=[$(cat "$TMP/k4e.err")] .claude=$([ -e "$d/.claude" ] && echo created || echo absent)"

# (4) scaffold WITHOUT --wire does not care about a dangling settings.json symlink (exit-2/4 split stays narrow).
d="$TMP/k4f"; mkdir -p "$d/.claude"; ln -s "$d/nowhere/s.json" "$d/.claude/settings.json"
bash "$SUT" "$d" --corpus flat >/dev/null 2>&1; _rc=$?
[ "$_rc" = 0 ] && ok "K1043-4 scaffold w/o --wire: dangling settings.json symlink is not a precondition (exit 0)" \
  || no "K1043-4 scaffold w/o --wire: dangling settings.json refused (exit $_rc)"

# ---- kit issue #1496: pkill-guard PreToolUse hook is installed AND registered (matcher Bash) ------
_PKT="$HERE/../../templates/hook-pretool-pkill-guard.sh"
if ! command -v jq >/dev/null 2>&1; then
  echo "  SKIP  1496: jq not on PATH"
else
  # (a) plain scaffold: hook installed byte-identical + executable; snippet PROPOSES it; no settings write.
  d="$TMP/1496-a"; mkdir -p "$d"; _o="$TMP/1496-a.out"
  bash "$SUT" "$d" --corpus flat >"$_o" 2>&1
  assert_file "K1496-a scaffold installs .claude/hooks/pkill-guard.sh" "$d/.claude/hooks/pkill-guard.sh"
  cmp -s "$_PKT" "$d/.claude/hooks/pkill-guard.sh" && ok "K1496-a installed hook is byte-identical to the template" \
    || no "K1496-a installed hook differs from (or is missing vs) the template"
  [ -x "$d/.claude/hooks/pkill-guard.sh" ] && ok "K1496-a installed hook is executable" || no "K1496-a installed hook is not executable"
  assert_absent "K1496-a propose-never-apply: no settings.json without --wire" "$d/.claude/settings.json"
  assert_grep "K1496-a printed snippet carries PreToolUse" '"PreToolUse"' "$_o"
  assert_grep "K1496-a printed snippet names the Bash matcher + hook path" "{\"matcher\":\"Bash\",\"hooks\":[{\"type\":\"command\",\"command\":\"$d/.claude/hooks/pkill-guard.sh\"}]}" "$_o"

  # (b) scaffold + wire: PreToolUse/Bash registered exactly once.
  d="$TMP/1496-b"; mkdir -p "$d"
  bash "$SUT" "$d" --corpus flat --scaffold --wire >/dev/null 2>&1
  [ "$(jq -r --arg c "$d/.claude/hooks/pkill-guard.sh" '[.hooks.PreToolUse[]? | select(.matcher=="Bash") | .hooks[]? | select(.command==$c)] | length' "$d/.claude/settings.json" 2>/dev/null)" = "1" ] \
    && ok "K1496-b --scaffold --wire registers PreToolUse/Bash pkill-guard once" \
    || no "K1496-b --scaffold --wire did not register PreToolUse/Bash pkill-guard exactly once"

  # (c) wire-only repair on a corpus with NO guard: creates it, registers it; second run is idempotent.
  d="$TMP/1496-c"; mkdir -p "$d"; : > "$d/INDEX.md"
  bash "$SUT" "$d" --wire >"$TMP/1496-c1.out" 2>&1
  assert_file "K1496-c wire-only repair creates the missing pkill-guard hook" "$d/.claude/hooks/pkill-guard.sh"
  assert_grep "K1496-c wire-only reports created" "created: $d/.claude/hooks/pkill-guard.sh" "$TMP/1496-c1.out"
  _c_sha="$(sha256sum "$d/.claude/settings.json" | cut -d' ' -f1)"
  bash "$SUT" "$d" --wire >"$TMP/1496-c2.out" 2>&1
  [ "$(sha256sum "$d/.claude/settings.json" | cut -d' ' -f1)" = "$_c_sha" ] && ok "K1496-c re-run leaves settings.json byte-identical (idempotent)" \
    || no "K1496-c re-run changed settings.json (not idempotent)"
  assert_grep "K1496-c re-run reports kept" "kept: $d/.claude/hooks/pkill-guard.sh" "$TMP/1496-c2.out"
  assert_grep "K1496-c re-run reports already wired" "PreToolUse pkill-guard hook already wired" "$TMP/1496-c2.out"
  [ "$(jq '.hooks.PreToolUse | length' "$d/.claude/settings.json")" = "1" ] && ok "K1496-c exactly one PreToolUse entry after two runs" \
    || no "K1496-c PreToolUse entry count != 1 after two runs"

  # (d) a hand-adapted guard is NEVER overwritten (create-only).
  d="$TMP/1496-d"; mkdir -p "$d/.claude/hooks"; : > "$d/INDEX.md"
  printf '#!/usr/bin/env bash\n# MARK-1496-LOCAL\nexit 0\n' > "$d/.claude/hooks/pkill-guard.sh"
  _d_sha="$(sha256sum "$d/.claude/hooks/pkill-guard.sh" | cut -d' ' -f1)"
  bash "$SUT" "$d" --wire >"$TMP/1496-d.out" 2>&1
  [ "$(sha256sum "$d/.claude/hooks/pkill-guard.sh" | cut -d' ' -f1)" = "$_d_sha" ] && ok "K1496-d hand-adapted pkill-guard survives byte-for-byte" \
    || no "K1496-d hand-adapted pkill-guard was overwritten"
  assert_grep "K1496-d reports kept" "kept: $d/.claude/hooks/pkill-guard.sh" "$TMP/1496-d.out"

  # (e) already registered via $CLAUDE_PROJECT_DIR (whole-command-quoted form) is the SAME hook — not re-added.
  d="$TMP/1496-e"; mkdir -p "$d/.claude"; : > "$d/INDEX.md"
  printf '%s' '{"hooks":{"PreToolUse":[{"matcher":"Bash","hooks":[{"type":"command","command":"\"$CLAUDE_PROJECT_DIR/.claude/hooks/pkill-guard.sh\""}]}]}}' > "$d/.claude/settings.json"
  bash "$SUT" "$d" --wire >/dev/null 2>&1
  [ "$(jq '[.hooks.PreToolUse[].hooks[]] | length' "$d/.claude/settings.json")" = "1" ] && ok "K1496-e CLAUDE_PROJECT_DIR-registered guard is deduped (not double-registered)" \
    || no "K1496-e CLAUDE_PROJECT_DIR-registered guard was registered a second time"

  # (f) an unrelated pre-existing PreToolUse entry is preserved alongside the new one.
  d="$TMP/1496-f"; mkdir -p "$d/.claude"; : > "$d/INDEX.md"
  printf '%s' '{"hooks":{"PreToolUse":[{"matcher":"Edit","hooks":[{"type":"command","command":"/x/mine.sh"}]}]}}' > "$d/.claude/settings.json"
  bash "$SUT" "$d" --wire >/dev/null 2>&1
  [ "$(jq -r '[.hooks.PreToolUse[].hooks[].command] | sort | join(",")' "$d/.claude/settings.json")" = "$d/.claude/hooks/pkill-guard.sh,/x/mine.sh" ] \
    && ok "K1496-f existing unrelated PreToolUse entry preserved, guard appended" \
    || no "K1496-f merge lost or mangled the existing PreToolUse entry"

  # (g) jq absent: wire-only prints a snippet that carries PreToolUse and writes NOTHING (no hook file).
  _g_pnojq="$(_u7_nojq_path)"
  if PATH="$_g_pnojq" command -v jq >/dev/null 2>&1; then
    echo "  SKIP  K1496-g: jq still reachable after dir exclusion"
  else
    d="$TMP/1496-g"; mkdir -p "$d"; : > "$d/INDEX.md"
    PATH="$_g_pnojq" bash "$SUT" "$d" --wire >"$TMP/1496-g.out" 2>"$TMP/1496-g.err"
    # #1509: prove the run reached the jq-absent branch (not died early for an unrelated PATH reason).
    assert_grep "K1496-g run reached the jq-absent degraded branch" "degraded: jq not found" "$TMP/1496-g.err"
    assert_grep "K1496-g jq-absent snippet carries the PreToolUse guard" "\"command\":\"$d/.claude/hooks/pkill-guard.sh\"" "$TMP/1496-g.out"
    assert_absent "K1496-g jq-absent: no hook file written" "$d/.claude/hooks/pkill-guard.sh"
  fi

  # (h) dangling symlink at the guard path is refused BEFORE any write (wire-only).
  d="$TMP/1496-h"; mkdir -p "$d/.claude/hooks"; : > "$d/INDEX.md"; ln -s "$d/nowhere" "$d/.claude/hooks/pkill-guard.sh"
  bash "$SUT" "$d" --wire >/dev/null 2>&1; _rc=$?
  [ "$_rc" = 2 ] && [ ! -e "$d/.claude/hooks/retro-gate-stop.sh" ] && [ ! -e "$d/.claude/settings.json" ] \
    && ok "K1496-h dangling pkill-guard symlink refused (exit 2), nothing else written" \
    || no "K1496-h dangling pkill-guard symlink: exit $_rc or partial write"
fi


# ---- kit issue #1496 round 2: scaffold --wire shares the wire-only dedup predicate -----------------
if command -v jq >/dev/null 2>&1; then
  # (i) scaffold+wire with the guard AND stop hook already registered via a non-canonical
  # $CLAUDE_PROJECT_DIR form: neither is registered a second time.
  d="$TMP/1496-i"; mkdir -p "$d/.claude"
  printf '%s' '{"hooks":{"PreToolUse":[{"matcher":"Bash","hooks":[{"type":"command","command":"\"$CLAUDE_PROJECT_DIR/.claude/hooks/pkill-guard.sh\""}]}],"Stop":[{"matcher":"","hooks":[{"type":"command","command":"${CLAUDE_PROJECT_DIR}/.claude/hooks/retro-gate-stop.sh"}]}]}}' > "$d/.claude/settings.json"
  bash "$SUT" "$d" --corpus flat --scaffold --wire >/dev/null 2>&1
  [ "$(jq '[.hooks.PreToolUse[].hooks[]] | length' "$d/.claude/settings.json" 2>/dev/null)" = "1" ] \
    && ok "K1496-i scaffold --wire dedups a non-canonical PreToolUse form" \
    || no "K1496-i scaffold --wire double-registered the pkill-guard"
  [ "$(jq '[.hooks.Stop[].hooks[] | select(.command | rtrimstr("\"") | endswith("return-token-gate.sh") | not)] | length' "$d/.claude/settings.json" 2>/dev/null)" = "1" ] \
    && ok "K1496-i scaffold --wire dedups a non-canonical Stop form" \
    || no "K1496-i scaffold --wire double-registered the Stop hook"
  # (j) a kept hand-adapted guard that is not executable draws a WARN (wire-only).
  d="$TMP/1496-j"; mkdir -p "$d/.claude/hooks"; : > "$d/INDEX.md"
  printf '#!/usr/bin/env bash\nexit 0\n' > "$d/.claude/hooks/pkill-guard.sh"; chmod -x "$d/.claude/hooks/pkill-guard.sh"
  bash "$SUT" "$d" --wire >"$TMP/1496-j.out" 2>&1
  assert_grep "K1496-j kept non-executable guard warns" "WARN: $d/.claude/hooks/pkill-guard.sh is not executable" "$TMP/1496-j.out"
  [ ! -x "$d/.claude/hooks/pkill-guard.sh" ] && ok "K1496-j kept guard left untouched (still not executable)" || no "K1496-j kept guard was modified"
fi

# ---- kit issue #1509: matcher-aware pkill-guard dedup; scaffold --wire reports per-hook state ------
if command -v jq >/dev/null 2>&1; then
  # <settings> <guard-cmd> -> number of guard registrations whose matcher COVERS the Bash tool
  _k9_nbash() {
    jq --arg c "$2" '[.hooks.PreToolUse[]? | select(((.matcher // "") as $m | ($m == "" or $m == "*") or (try ("Bash" | test("^(?:" + $m + ")$")) catch false))) | .hooks[]? | select(.command == $c)] | length' "$1" 2>/dev/null
  }
  # (a) a guard registered ONLY under a matcher that never fires for Bash (Edit) is NOT "present":
  # the wire-only repair and scaffold --wire must each register a Bash-covering entry.
  for _k9_mode in wireonly scaffold; do
    d="$TMP/1509-a-$_k9_mode"; mkdir -p "$d/.claude"
    [ "$_k9_mode" = wireonly ] && : > "$d/INDEX.md"
    printf '{"hooks":{"PreToolUse":[{"matcher":"Edit","hooks":[{"type":"command","command":"%s/.claude/hooks/pkill-guard.sh"}]}]}}' "$d" > "$d/.claude/settings.json"
    if [ "$_k9_mode" = wireonly ]; then bash "$SUT" "$d" --wire >/dev/null 2>&1; else bash "$SUT" "$d" --corpus flat --scaffold --wire >/dev/null 2>&1; fi
    [ "$(_k9_nbash "$d/.claude/settings.json" "$d/.claude/hooks/pkill-guard.sh")" = "1" ] \
      && ok "K1509-a ($_k9_mode) guard under a non-Bash matcher is not counted as present; a Bash-covering entry is added" \
      || no "K1509-a ($_k9_mode) guard under matcher Edit was deduped - Bash is unguarded (covering entries: $(_k9_nbash "$d/.claude/settings.json" "$d/.claude/hooks/pkill-guard.sh"))"
  done
  # (c) controls: matchers that DO cover Bash (empty, absent, "*", alternation, exact) are present - not re-added.
  _k9_i=0
  for _k9_m in '"matcher":"",' '' '"matcher":"*",' '"matcher":"Bash|Edit",' '"matcher":"Bash",'; do
    _k9_i=$((_k9_i+1))
    for _k9_mode in wireonly scaffold; do
      d="$TMP/1509-c$_k9_i-$_k9_mode"; mkdir -p "$d/.claude"
      [ "$_k9_mode" = wireonly ] && : > "$d/INDEX.md"
      printf '{"hooks":{"PreToolUse":[{%s"hooks":[{"type":"command","command":"%s/.claude/hooks/pkill-guard.sh"}]}]}}' "$_k9_m" "$d" > "$d/.claude/settings.json"
      if [ "$_k9_mode" = wireonly ]; then bash "$SUT" "$d" --wire >/dev/null 2>&1; else bash "$SUT" "$d" --corpus flat --scaffold --wire >/dev/null 2>&1; fi
      [ "$(jq '[.hooks.PreToolUse[].hooks[]] | length' "$d/.claude/settings.json" 2>/dev/null)" = "1" ] \
        && ok "K1509-c ($_k9_mode, matcher [$_k9_m]) Bash-covering registration is deduped" \
        || no "K1509-c ($_k9_mode, matcher [$_k9_m]) Bash-covering registration was double-registered"
    done
  done
  # (d) scaffold --wire reports each hook's state: fresh -> registered; already present -> already wired.
  d="$TMP/1509-d"; mkdir -p "$d"
  bash "$SUT" "$d" --corpus flat --scaffold --wire >"$TMP/1509-d1.out" 2>&1
  assert_grep "K1509-d fresh scaffold --wire reports the guard as registered" "PreToolUse pkill-guard hook registered in" "$TMP/1509-d1.out"
  assert_grep "K1509-d fresh scaffold --wire reports Stop as registered" "Stop hook registered in" "$TMP/1509-d1.out"
  d="$TMP/1509-d3"; mkdir -p "$d/.claude"
  printf '%s' '{"hooks":{"PreToolUse":[{"matcher":"Bash","hooks":[{"type":"command","command":"\"$CLAUDE_PROJECT_DIR/.claude/hooks/pkill-guard.sh\""}]}]}}' > "$d/.claude/settings.json"
  bash "$SUT" "$d" --corpus flat --scaffold --wire >"$TMP/1509-d3.out" 2>&1
  assert_grep "K1509-d scaffold --wire on an already-registered guard says already wired" "PreToolUse pkill-guard hook already wired" "$TMP/1509-d3.out"
  assert_grep "K1509-d scaffold --wire still registers the absent Stop hook" "Stop hook registered in" "$TMP/1509-d3.out"
  # (f) a merge FAILURE on the scaffold --wire path (settings.json whose .hooks is a string, so the
  # shared merge's jq errors) is a typed, guarded failure like the wire-only path: message names the
  # file + "refusing to report success", exit 4, settings.json byte-untouched, and no bare errexit abort.
  d="$TMP/1509-f"; mkdir -p "$d/.claude"
  printf '%s' '{"hooks":"oops"}' > "$d/.claude/settings.json"
  bash "$SUT" "$d" --corpus flat --scaffold --wire >"$TMP/1509-f.out" 2>"$TMP/1509-f.err"; _k9_rc=$?
  [ "$_k9_rc" = 4 ] && ok "K1509-f scaffold --wire merge failure exits 4" || no "K1509-f scaffold --wire merge failure: exit $_k9_rc (want 4); stderr: $(tail -3 "$TMP/1509-f.err" | tr '\n' ' ')"
  assert_grep "K1509-f typed message on stderr" "degraded: jq failed on $d/.claude/settings.json — refusing to report success" "$TMP/1509-f.err"
  [ "$(cat "$d/.claude/settings.json")" = '{"hooks":"oops"}' ] && ok "K1509-f settings.json untouched on merge failure" || no "K1509-f settings.json was modified on merge failure"
  assert_grep "K1509-f paste-able snippet still printed" '"PreToolUse"' "$TMP/1509-f.out"
  # (e) the scaffold print-only snippet and the wire-only (jq-absent) snippet carry the identical hook block.
  # jq-absent PATH is an ALLOWLIST of symlinks (not "PATH minus jq's dir", which also drops bash/coreutils
  # when jq lives in /usr/bin) and the run is asserted to have reached the degraded branch.
  d="$TMP/1509-e"; mkdir -p "$d"
  bash "$SUT" "$d" --corpus flat >"$TMP/1509-e1.out" 2>&1
  d2="$TMP/1509-e2"; mkdir -p "$d2"; : > "$d2/INDEX.md"
  _k9_nojq="$TMP/1509-nojq-bin"; mkdir -p "$_k9_nojq"
  for _k9_t in bash cat mktemp rm mkdir cp chmod grep sed tr dirname basename date ls ln mv head tail sort wc printf env readlink cut awk git find uname id touch cmp diff tee; do
    _k9_p="$(command -v "$_k9_t" 2>/dev/null)"; [ -n "$_k9_p" ] && [ -x "$_k9_p" ] && ln -sf "$_k9_p" "$_k9_nojq/$_k9_t"
  done
  PATH="$_k9_nojq" bash "$SUT" "$d2" --wire >"$TMP/1509-e2.out" 2>"$TMP/1509-e2.err"
  assert_grep "K1509-e jq-absent (allowlist PATH) reaches the degraded branch" "degraded: jq not found" "$TMP/1509-e2.err"
  # SessionStart is legitimately omitted on the wire-only path (no adapted hook), so compare the
  # Stop + PreToolUse portion only (everything before the SessionStart key), target path normalised.
  # Only the hook entries ("matcher" lines) are compared: the closing-bracket lines legitimately differ
  # (a trailing comma when SessionStart follows).
  _k9_blk() { sed -n '/^{$/,/^}$/p' "$1" | sed '/"SessionStart"/,$d' | grep -F '"matcher"' | sed "s|$2|<T>|g"; }
  [ -n "$(_k9_blk "$TMP/1509-e1.out" "$d")" ] && [ "$(_k9_blk "$TMP/1509-e1.out" "$d")" = "$(_k9_blk "$TMP/1509-e2.out" "$d2")" ] \
    && ok "K1509-e scaffold snippet and wire-only snippet carry the identical Stop+PreToolUse block" \
    || no "K1509-e snippet blocks diverge between the scaffold and wire-only paths"
fi


# ---- kit issue #1271 slice 2: vendor-leak guard wiring (gh stubbed via PATH — hermetic, no network) ----
if command -v git >/dev/null 2>&1; then
  K71_BIN="$TMP/k71bin"; mkdir -p "$K71_BIN"
  # gh stub: prints $K71_VIS and exits $K71_RC; records that it was called.
  cat > "$K71_BIN/gh" <<'GHEOF'
#!/usr/bin/env bash
echo "$* [GH_PROMPT_DISABLED=${GH_PROMPT_DISABLED:-unset}] [GH_REPO=${GH_REPO:-unset}]" >> "${K71_LOG:-/dev/null}"
if [ -n "${K71_MAP:-}" ]; then  # "substr=VIS;substr=VIS": answer by the repo argument
  IFS=';' read -ra _e <<<"$K71_MAP"
  for _x in "${_e[@]}"; do case "$*" in *"${_x%%=*}"*) K71_VIS="${_x#*=}" ;; esac; done
fi
[ -n "${K71_SLEEP:-}" ] && sleep "$K71_SLEEP"
[ -n "${K71_ERR:-}" ] && printf '%s\nsecond line\n' "$K71_ERR" >&2
[ -n "${K71_VIS:-}" ] && printf '%s\n' "$K71_VIS"
exit "${K71_RC:-0}"
GHEOF
  chmod +x "$K71_BIN/gh"
  # PATH with NO gh at all: symlink every tool the SUT needs except gh.
  K71_NOGH="$TMP/k71nogh"; mkdir -p "$K71_NOGH"
  for _t in bash git sed cp mkdir cat rm dirname mktemp jq grep awk chmod ln date tr sort cut wc ls mv stat uname basename env head tail touch printf readlink tee find xargs id timeout sleep; do
    _p="$(command -v "$_t" 2>/dev/null)" && [ -x "$_p" ] && ln -sf "$_p" "$K71_NOGH/$_t"
  done
  _k71_target() {  # <name> [remote-url] — an empty git target, optionally with an origin remote
    local d="$TMP/k71-$1"; mkdir -p "$d"; git -C "$d" init -q 2>/dev/null
    [ -n "${2:-}" ] && git -C "$d" remote add origin "$2"
    printf '%s' "$d"
  }
  _k71_run() {  # <target> <vis> <rc> [init args…] → stdout+stderr in $TMP/k71.out, rc in K71_RC_OUT
    local d="$1" vis="$2" rc="$3"; shift 3
    PATH="$K71_BIN:$PATH" K71_VIS="$vis" K71_RC="$rc" K71_LOG="$TMP/k71.gh.log" bash "$SUT" "$d" --corpus flat "$@" >"$TMP/k71.out" 2>&1
    K71_RC_OUT=$?
  }

  # K1820-rel (R3): the toolbelt dir is resolved ONCE at startup. A kit copy whose init does `cd /` right after the startup lib loads (so a
  # later `dirname $0` lookup of a RELATIVE $0 would miss) and is invoked via a relative path from another cwd must still
  # reach the visibility probe (a PUBLIC answer scaffolds the conf), not DEGRADE with "lib/gh-visibility.sh unavailable".
  _k71_relkit() {  # <name> [extra sed -e …] — kit copy with `cd /` injected after the startup lib loads; echoes the kit dir
    local kd="$TMP/k71rel-$1"; shift; rm -rf "$kd"; mkdir -p "$kd/toolbelt/lib"
    cp "$HERE/../lib/corpus-markers.sh" "$HERE/../lib/gh-visibility.sh" "$kd/toolbelt/lib/"; ln -sfn "$HERE/../../templates" "$kd/templates"
    sed -e '/^unset _ri_cm_lib$/a cd /' "$@" "$SUT" > "$kd/toolbelt/init.sh"; chmod +x "$kd/toolbelt/init.sh"; printf '%s' "$kd"
  }
  _k71_relrun() {  # <kitdir> <target> → init output in $TMP/k71rel.out, run via a RELATIVE path from the kit's parent dir
    ( cd "$(dirname "$1")" && PATH="$K71_BIN:$PATH" K71_VIS=PUBLIC K71_RC=0 K71_LOG="$TMP/k71.gh.log" bash "$(basename "$1")/toolbelt/init.sh" "$2" --corpus flat >"$TMP/k71rel.out" 2>&1 )
  }
  kd="$(_k71_relkit ok)"; d="$(_k71_target relok https://example.invalid/pub.git)"; _k71_relrun "$kd" "$d"
  assert_grep "K1820-rel relative \$0 + cwd change: the probe ran (typed PUBLIC line)" "vendor-leak: PUBLIC" "$TMP/k71rel.out"
  grep -qF "gh-visibility.sh unavailable" "$TMP/k71rel.out" && no "K1820-rel relative \$0 + cwd change: DEGRADED lib-missing" || ok "K1820-rel relative \$0 + cwd change: not DEGRADED lib-missing"

  # K1271-a PUBLIC remote → stub conf scaffolded, typed line, CI snippet proposed (not written without --wire)
  d="$(_k71_target a https://example.invalid/pub.git)"; : > "$TMP/k71.gh.log"
  _k71_run "$d" PUBLIC 0
  [ "$K71_RC_OUT" = 0 ] && ok "K1271-a PUBLIC: scaffold exits 0" || no "K1271-a PUBLIC: exit $K71_RC_OUT"
  assert_file "K1271-a PUBLIC: .research-sdd/vendor-leak.conf stub scaffolded" "$d/.research-sdd/vendor-leak.conf"
  assert_grep "K1271-a PUBLIC: stub names the directive vocabulary" "allow  <glob>" "$d/.research-sdd/vendor-leak.conf"
  assert_grep "K1271-a PUBLIC: typed PUBLIC line" "vendor-leak: PUBLIC" "$TMP/k71.out"
  assert_grep "K1271-a PUBLIC: CI snippet proposed (carries the scanner run step)" "run: bash kit/research-sdd/toolbelt/scan-vendor-leak.sh target --tracked --strict" "$TMP/k71.out"
  assert_absent "K1271-a PUBLIC: workflow NOT written without --wire (propose-never-apply)" "$d/.github/workflows/vendor-leak.yml"
  assert_grep "K1271-a: gh asked for visibility" "repo view" "$TMP/k71.gh.log"
  # the scanner itself accepts the stub: EMPTY-CONF, exit 0 on an empty tree
  _k71_scan="$(cd "$d" && bash "$HERE/../scan-vendor-leak.sh" "$d" 2>&1)"; _k71_rc=$?
  { [ "$_k71_rc" = 0 ] && grep -qF 'EMPTY-CONF' <<<"$_k71_scan"; } && ok "K1271-a: scanner reads the stub as EMPTY-CONF (exit 0)" || no "K1271-a: scanner on the stub: rc=$_k71_rc out=[$_k71_scan]"
  _k71_scan="$(cd "$d" && bash "$HERE/../scan-vendor-leak.sh" "$d" --strict 2>&1)"; _k71_rc=$?
  { [ "$_k71_rc" = 4 ] && grep -qF 'STRICT-FAIL EMPTY-CONF' <<<"$_k71_scan"; } && ok "K1566: the proposed CI's --strict makes the untouched stub a non-pass (exit 4)" || no "K1566: strict scanner on the stub: rc=$_k71_rc out=[$_k71_scan]"

  # K1271-b PUBLIC + --scaffold --wire → workflow written; K1271-c existing conf / workflow never overwritten
  d="$(_k71_target b https://example.invalid/pub.git)"
  _k71_run "$d" PUBLIC 0 --scaffold --wire
  assert_file "K1271-b PUBLIC --wire: workflow written" "$d/.github/workflows/vendor-leak.yml"
  assert_grep "K1271-b PUBLIC --wire: workflow runs the scanner" "scan-vendor-leak.sh" "$d/.github/workflows/vendor-leak.yml"
  d="$(_k71_target c https://example.invalid/pub.git)"; mkdir -p "$d/.research-sdd" "$d/.github/workflows"
  printf 'prefix com.keepme\n' > "$d/.research-sdd/vendor-leak.conf"; printf 'hand-written\n' > "$d/.github/workflows/vendor-leak.yml"
  _k71_run "$d" PUBLIC 0 --scaffold --wire
  assert_grep "K1271-c existing conf untouched" "prefix com.keepme" "$d/.research-sdd/vendor-leak.conf"
  assert_grep "K1271-c existing workflow untouched" "hand-written" "$d/.github/workflows/vendor-leak.yml"
  assert_grep "K1271-c typed kept-existing line" "kept existing" "$TMP/k71.out"

  # K1271-d PRIVATE → no scaffold, typed message
  d="$(_k71_target d https://example.invalid/priv.git)"
  _k71_run "$d" PRIVATE 0 --scaffold --wire
  assert_absent "K1271-d PRIVATE: no conf scaffolded" "$d/.research-sdd/vendor-leak.conf"
  assert_absent "K1271-d PRIVATE: no workflow written" "$d/.github/workflows/vendor-leak.yml"
  assert_grep "K1271-d PRIVATE: typed message" "vendor-leak: PRIVATE" "$TMP/k71.out"

  # K1566 R4: a target that is a SUBDIRECTORY of a repo inherits the parent's remotes; GitHub ignores a workflow
  # written under <sub>/.github/workflows, so --wire must NOT write it nor claim success — typed SUBDIR state.
  d="$(_k71_target r4 https://example.invalid/pub.git)"; mkdir -p "$d/sub"; : > "$TMP/k71.gh.log"
  _k71_run "$d/sub" PUBLIC 0 --scaffold --wire
  [ "$K71_RC_OUT" = 0 ] && ok "K1566-R4 subdir target: scaffold still exits 0" || no "K1566-R4 subdir target: exit $K71_RC_OUT"
  assert_grep "K1566-R4 subdir target: typed SUBDIR state" "vendor-leak: SUBDIR" "$TMP/k71.out"
  assert_absent "K1566-R4 subdir target: no workflow written under the subdirectory" "$d/sub/.github/workflows/vendor-leak.yml"
  assert_absent "K1566-R4 subdir target: no conf scaffolded in the subdirectory" "$d/sub/.research-sdd/vendor-leak.conf"
  { ! grep -qF 'wrote CI workflow' "$TMP/k71.out" && ! grep -qF 'vendor-leak: PUBLIC' "$TMP/k71.out"; } && ok "K1566-R4 subdir target: no success claim in the output" || no "K1566-R4 subdir target: success claimed"
  [ ! -s "$TMP/k71.gh.log" ] && ok "K1566-R4 subdir target: gh not asked about the parent's remote" || no "K1566-R4 subdir target: gh was called"
  # the repo ROOT is unaffected (K1271-b), including when reached through a symlink
  ln -sfn "$d" "$TMP/k71-r4-link"; : > "$TMP/k71.gh.log"
  _k71_run "$TMP/k71-r4-link" PUBLIC 0 --scaffold --wire
  assert_file "K1566-R4 repo root via symlink: workflow still written" "$d/.github/workflows/vendor-leak.yml"
  # K1271-e no remote → no gh call, no scaffold, typed message
  d="$(_k71_target e)"; : > "$TMP/k71.gh.log"
  _k71_run "$d" PUBLIC 0
  assert_absent "K1271-e no remote: no conf scaffolded" "$d/.research-sdd/vendor-leak.conf"
  assert_grep "K1271-e no remote: typed message" "vendor-leak: NO-REMOTE" "$TMP/k71.out"
  [ ! -s "$TMP/k71.gh.log" ] && ok "K1271-e no remote: gh never invoked" || no "K1271-e no remote: gh was invoked"

  # K1271-f gh failing → typed DEGRADED, never a silent pass or a scaffold; scaffold itself still succeeds
  d="$(_k71_target f https://example.invalid/x.git)"
  _k71_run "$d" "" 1
  [ "$K71_RC_OUT" = 0 ] && ok "K1271-f gh fails: corpus scaffold still exits 0" || no "K1271-f gh fails: exit $K71_RC_OUT"
  assert_grep "K1271-f gh fails: typed DEGRADED" "vendor-leak: DEGRADED" "$TMP/k71.out"
  assert_absent "K1271-f gh fails: no conf scaffolded" "$d/.research-sdd/vendor-leak.conf"
  # K1271-g gh answering something unrecognised → DEGRADED, not PUBLIC and not PRIVATE
  d="$(_k71_target g https://example.invalid/x.git)"
  _k71_run "$d" "WEIRD" 0
  assert_grep "K1271-g unrecognised visibility: typed DEGRADED" "vendor-leak: DEGRADED" "$TMP/k71.out"
  assert_absent "K1271-g unrecognised visibility: no conf scaffolded" "$d/.research-sdd/vendor-leak.conf"
  # K1271-h gh absent from PATH → typed DEGRADED
  d="$(_k71_target h https://example.invalid/x.git)"
  PATH="$K71_NOGH" bash "$SUT" "$d" --corpus flat >"$TMP/k71.out" 2>&1; _k71_rc=$?
  { [ "$_k71_rc" = 0 ] && grep -qF 'vendor-leak: DEGRADED' "$TMP/k71.out" && grep -qF 'gh not found' "$TMP/k71.out"; } \
    && ok "K1271-h gh missing: typed DEGRADED (gh not found), scaffold exit 0" || no "K1271-h gh missing: rc=$_k71_rc"
  assert_absent "K1271-h gh missing: no conf scaffolded" "$d/.research-sdd/vendor-leak.conf"

  if command -v timeout >/dev/null 2>&1; then   # K1271-i/o need a real timeout(1)
  # K1271-i gh hangs → bounded by timeout (RSDD_GH_TIMEOUT), typed DEGRADED "gh timed out"; prompts disabled
  d="$(_k71_target i https://example.invalid/x.git)"; : > "$TMP/k71.gh.log"
  RSDD_GH_TIMEOUT=1 K71_SLEEP=6 _k71_run "$d" PUBLIC 0
  [ "$K71_RC_OUT" = 0 ] && ok "K1271-i gh hangs: scaffold still exits 0" || no "K1271-i gh hangs: exit $K71_RC_OUT"
  assert_grep "K1271-i gh hangs: typed 'gh timed out'" "gh timed out" "$TMP/k71.out"
  assert_absent "K1271-i gh hangs: no conf scaffolded" "$d/.research-sdd/vendor-leak.conf"
  assert_grep "K1271-i gh runs with GH_PROMPT_DISABLED=1" "GH_PROMPT_DISABLED=1" "$TMP/k71.gh.log"
  # K1271-o RSDD_GH_TIMEOUT validated: 0 / abc / empty fall back to the bounded default 20 with a note (never 0 = unbounded)
  K71_TO="$TMP/k71to"; mkdir -p "$K71_TO"
  cat > "$K71_TO/timeout" <<TOEOF
#!/usr/bin/env bash
echo "\$1" >> "\${K71_TOLOG:-/dev/null}"
exec "$(command -v timeout)" "\$@"
TOEOF
  chmod +x "$K71_TO/timeout"
  for _bad in 0 00 abc ""; do
    d="$(_k71_target "o-${_bad:-empty}" https://example.invalid/x.git)"; : > "$TMP/k71.to.log"
    PATH="$K71_TO:$K71_BIN:$PATH" RSDD_GH_TIMEOUT="$_bad" K71_TOLOG="$TMP/k71.to.log" K71_VIS=PUBLIC K71_RC=0 bash "$SUT" "$d" --corpus flat >"$TMP/k71.out" 2>&1
    assert_grep "K1271-o RSDD_GH_TIMEOUT='$_bad': note about the invalid value" "RSDD_GH_TIMEOUT" "$TMP/k71.out"
    [ "$(head -1 "$TMP/k71.to.log")" = 20 ] && ok "K1271-o RSDD_GH_TIMEOUT='$_bad': bounded default 20 passed to timeout" || no "K1271-o RSDD_GH_TIMEOUT='$_bad': timeout got '$(head -1 "$TMP/k71.to.log")'"
  done
  d="$(_k71_target o-ok https://example.invalid/x.git)"; : > "$TMP/k71.to.log"
  PATH="$K71_TO:$K71_BIN:$PATH" RSDD_GH_TIMEOUT=7 K71_TOLOG="$TMP/k71.to.log" K71_VIS=PUBLIC K71_RC=0 bash "$SUT" "$d" --corpus flat >"$TMP/k71.out" 2>&1
  [ "$(head -1 "$TMP/k71.to.log")" = 7 ] && ok "K1271-o valid RSDD_GH_TIMEOUT=7 honoured" || no "K1271-o valid RSDD_GH_TIMEOUT=7 not honoured"
  # K1566 R2: a positive integer with leading zeros is valid (decimal, not octal) — not rejected, not mis-parsed
  for _lz in 05:5 010:10 0020:20 0000000007:7; do
    d="$(_k71_target "lz-${_lz%%:*}" https://example.invalid/x.git)"; : > "$TMP/k71.to.log"
    PATH="$K71_TO:$K71_BIN:$PATH" RSDD_GH_TIMEOUT="${_lz%%:*}" K71_TOLOG="$TMP/k71.to.log" K71_VIS=PUBLIC K71_RC=0 bash "$SUT" "$d" --corpus flat >"$TMP/k71.out" 2>&1
    { [ "$(head -1 "$TMP/k71.to.log")" = "${_lz##*:}" ] && ! grep -qF 'not a positive integer' "$TMP/k71.out"; } \
      && ok "K1566 RSDD_GH_TIMEOUT=${_lz%%:*} → decimal ${_lz##*:}, no invalid-value note" || no "K1566 RSDD_GH_TIMEOUT=${_lz%%:*}: timeout got '$(head -1 "$TMP/k71.to.log")'"
  done
  else echo "  SKIP  K1271-i/o: GNU timeout not on PATH (the SUT then runs gh unbounded, announced)"; fi
  # K1271-p rc 125 (timeout itself failed) has its own wording; gh's first stderr line is surfaced on failure
  d="$(_k71_target p1 https://example.invalid/x.git)"
  PATH="$K71_BIN:$PATH" K71_RC=125 K71_VIS="" bash "$SUT" "$d" --corpus flat >"$TMP/k71.out" 2>&1
  assert_grep "K1271-p rc 125: own DEGRADED wording" "timeout could not run gh" "$TMP/k71.out"
  d="$(_k71_target p2 https://example.invalid/x.git)"
  PATH="$K71_BIN:$PATH" K71_RC=1 K71_VIS="" K71_ERR="HTTP 401: bad credentials" bash "$SUT" "$d" --corpus flat >"$TMP/k71.out" 2>&1
  assert_grep "K1271-p gh failure: first stderr line surfaced" "HTTP 401: bad credentials" "$TMP/k71.out"
  grep -qF 'second line' "$TMP/k71.out" && no "K1271-p only the FIRST stderr line is surfaced" || ok "K1271-p only the first stderr line is surfaced"

  # K1271-q the probed repo is the PUSH remote (origin), not whatever gh would pick; GH_REPO is neutralised
  d="$(_k71_target q1 https://example.invalid/pub.git)"; git -C "$d" remote add upstream https://example.invalid/priv.git; : > "$TMP/k71.gh.log"
  PATH="$K71_BIN:$PATH" GH_REPO=someone/else K71_MAP="pub.git=PUBLIC;priv.git=PRIVATE" K71_VIS=PRIVATE K71_RC=0 K71_LOG="$TMP/k71.gh.log" bash "$SUT" "$d" --corpus flat >"$TMP/k71.out" 2>&1
  assert_file "K1271-q origin PUBLIC + upstream PRIVATE: PUBLIC wins (stub conf scaffolded)" "$d/.research-sdd/vendor-leak.conf"
  assert_grep "K1271-q the typed line names the probed remote" "remote 'origin'" "$TMP/k71.out"
  assert_grep "K1271-q gh got the origin URL as its repo argument" "repo view https://example.invalid/pub.git" "$TMP/k71.gh.log"
  assert_grep "K1271-q GH_REPO neutralised for the call" "GH_REPO=unset" "$TMP/k71.gh.log"
  d="$(_k71_target q2)"; git -C "$d" remote add up1 https://example.invalid/a.git; git -C "$d" remote add up2 https://example.invalid/b.git; : > "$TMP/k71.gh.log"
  _k71_run "$d" PUBLIC 0
  assert_grep "K1271-q several remotes and no origin: DEGRADED ambiguous remote" "DEGRADED ambiguous remote" "$TMP/k71.out"
  assert_absent "K1271-q ambiguous remote: no conf scaffolded" "$d/.research-sdd/vendor-leak.conf"
  [ ! -s "$TMP/k71.gh.log" ] && ok "K1271-q ambiguous remote: gh never invoked" || no "K1271-q ambiguous remote: gh was invoked"
  d="$(_k71_target q3)"; git -C "$d" remote add fork https://example.invalid/fork.git
  _k71_run "$d" PUBLIC 0
  assert_grep "K1271-q a single non-origin remote is used (named in the line)" "remote 'fork'" "$TMP/k71.out"

  # K1271-r conf directory guard: .research-sdd as a symlink / regular file → DEGRADED, nothing written through it
  d="$(_k71_target r1 https://example.invalid/x.git)"; mkdir -p "$TMP/k71-rs-out"; ln -s "$TMP/k71-rs-out" "$d/.research-sdd"
  _k71_run "$d" PUBLIC 0
  assert_grep "K1271-r .research-sdd symlink: typed DEGRADED" "DEGRADED $d/.research-sdd is a symlink" "$TMP/k71.out"
  assert_absent "K1271-r .research-sdd symlink: nothing written through it" "$TMP/k71-rs-out/vendor-leak.conf"
  d="$(_k71_target r2 https://example.invalid/x.git)"; : > "$d/.research-sdd"
  _k71_run "$d" PUBLIC 0
  assert_grep "K1271-r .research-sdd regular file: typed DEGRADED" "DEGRADED $d/.research-sdd is a symlink or not a directory" "$TMP/k71.out"
  # K1271-s INTERNAL visibility takes the PRIVATE path
  d="$(_k71_target s https://example.invalid/x.git)"; _k71_run "$d" INTERNAL 0
  assert_grep "K1271-s INTERNAL: PRIVATE path, visibility named" "visibility is INTERNAL" "$TMP/k71.out"
  assert_absent "K1271-s INTERNAL: no conf scaffolded" "$d/.research-sdd/vendor-leak.conf"

  # K1271-j no `timeout` binary → still runs, says so (unbounded probe is announced, never silent)
  K71_NOTO="$TMP/k71noto"; mkdir -p "$K71_NOTO"; cp -P "$K71_NOGH"/* "$K71_NOTO"/; rm -f "$K71_NOTO/timeout"; cp "$K71_BIN/gh" "$K71_NOTO/gh"
  d="$(_k71_target j https://example.invalid/x.git)"
  PATH="$K71_NOTO" K71_VIS=PUBLIC K71_RC=0 bash "$SUT" "$d" --corpus flat >"$TMP/k71.out" 2>&1
  assert_grep "K1271-j no timeout binary: announced" "timeout not found" "$TMP/k71.out"
  assert_file "K1271-j no timeout binary: probe still ran (PUBLIC scaffold)" "$d/.research-sdd/vendor-leak.conf"

  # K1271-k --wire with a symlinked / non-directory .github or .github/workflows → DEGRADED, nothing written through it
  d="$(_k71_target k1 https://example.invalid/x.git)"; mkdir -p "$TMP/k71-elsewhere"; ln -s "$TMP/k71-elsewhere" "$d/.github"
  _k71_run "$d" PUBLIC 0 --scaffold --wire
  assert_grep "K1271-k .github symlink: typed DEGRADED" "DEGRADED $d/.github" "$TMP/k71.out"
  assert_absent "K1271-k .github symlink: nothing written through it" "$TMP/k71-elsewhere/workflows"
  d="$(_k71_target k2 https://example.invalid/x.git)"; mkdir -p "$d/.github" "$TMP/k71-elsewhere2"; ln -s "$TMP/k71-elsewhere2" "$d/.github/workflows"
  _k71_run "$d" PUBLIC 0 --scaffold --wire
  assert_grep "K1271-k .github/workflows symlink: typed DEGRADED" "DEGRADED $d/.github/workflows" "$TMP/k71.out"
  assert_absent "K1271-k .github/workflows symlink: nothing written through it" "$TMP/k71-elsewhere2/vendor-leak.yml"
  d="$(_k71_target k3 https://example.invalid/x.git)"; : > "$d/.github"
  _k71_run "$d" PUBLIC 0 --scaffold --wire
  assert_grep "K1271-k .github regular file: typed DEGRADED" "DEGRADED $d/.github" "$TMP/k71.out"

  # K1271-l git wrapper: not-a-repo → NO-REMOTE; a real `git remote` failure inside a repo → DEGRADED
  K71_GIT="$TMP/k71git"; mkdir -p "$K71_GIT"; K71_REALGIT="$(command -v git)"
  cat > "$K71_GIT/git" <<GITEOF
#!/usr/bin/env bash
case "\$*" in
  *"rev-parse --is-inside-work-tree"*)
    [ -n "\${K71_NOTREPO:-}" ] && { echo "fatal: not a git repository (or any of the parent directories): .git" >&2; exit 128; }
    [ -n "\${K71_DUBIOUS:-}" ] && { echo "fatal: detected dubious ownership in repository at '/x'" >&2; exit 128; } ;;
  *" remote"*) [ -n "\${K71_REMOTEFAIL:-}" ] && exit 1 ;;
esac
exec "$K71_REALGIT" "\$@"
GITEOF
  chmod +x "$K71_GIT/git"
  d="$(_k71_target l1)"
  PATH="$K71_GIT:$K71_BIN:$PATH" K71_NOTREPO=1 K71_REMOTEFAIL=1 bash "$SUT" "$d" --corpus flat >"$TMP/k71.out" 2>&1
  assert_grep "K1271-l not a git repo: NO-REMOTE (not DEGRADED)" "vendor-leak: NO-REMOTE" "$TMP/k71.out"
  d="$(_k71_target l2)"
  PATH="$K71_GIT:$K71_BIN:$PATH" K71_REMOTEFAIL=1 bash "$SUT" "$d" --corpus flat >"$TMP/k71.out" 2>&1
  assert_grep "K1271-l git remote failing inside a repo: DEGRADED" "vendor-leak: DEGRADED could not list git remotes" "$TMP/k71.out"
  d="$(_k71_target l3)"
  PATH="$K71_GIT:$K71_BIN:$PATH" K71_DUBIOUS=1 bash "$SUT" "$d" --corpus flat >"$TMP/k71.out" 2>&1
  assert_grep "K1271-l rev-parse failing inside a repo (dubious ownership): DEGRADED, not NO-REMOTE" "vendor-leak: DEGRADED git rev-parse failed" "$TMP/k71.out"
  assert_grep "K1271-l rev-parse failure surfaces git's reason" "dubious ownership" "$TMP/k71.out"

  # K1271-m advice text: a plain run scaffolds the conf; --wire only adds the CI workflow
  d="$(_k71_target m2)"; _k71_run "$d" PUBLIC 0
  assert_grep "K1271-m NO-REMOTE advice: a plain re-run scaffolds the conf" "a plain run scaffolds the conf" "$TMP/k71.out"
  d="$(_k71_target m3 https://example.invalid/x.git)"; _k71_run "$d" PRIVATE 0
  assert_grep "K1271-m PRIVATE advice: a plain re-run scaffolds the conf" "a plain run scaffolds the conf" "$TMP/k71.out"

  # K1271-n PUBLIC but a kit template missing → typed DEGRADED, nothing scaffolded
  mkdir -p "$TMP/k71kit/toolbelt/lib" "$TMP/k71kit/templates"; cp "$HERE/../lib/corpus-markers.sh" "$TMP/k71kit/toolbelt/lib/"; cp "$HERE/../lib/gh-visibility.sh" "$TMP/k71kit/toolbelt/lib/"
  cp "$HERE/../../templates/"* "$TMP/k71kit/templates/"; rm -f "$TMP/k71kit/templates/vendor-leak.conf.template"
  cp "$SUT" "$TMP/k71kit/toolbelt/init.sh"; chmod +x "$TMP/k71kit/toolbelt/init.sh"
  d="$(_k71_target n https://example.invalid/x.git)"
  PATH="$K71_BIN:$PATH" K71_VIS=PUBLIC K71_RC=0 bash "$TMP/k71kit/toolbelt/init.sh" "$d" --corpus flat >"$TMP/k71.out" 2>&1
  assert_grep "K1271-n missing template: typed DEGRADED" "kit templates missing" "$TMP/k71.out"
  assert_absent "K1271-n missing template: no conf scaffolded" "$d/.research-sdd/vendor-leak.conf"
fi


# ---- kit issue #1732: the return-token Stop gate is wired (second Stop entry) by --wire and in the snippet ------
if command -v jq >/dev/null 2>&1; then
  _k32_kit="$(cd -P "$HERE/../.." && pwd -P)"; _k32_gate="$_k32_kit/toolbelt/return-token-gate.sh"; _k32_gq="\"$_k32_gate\""
  # <settings> <command> -> how many Stop registrations carry exactly that command
  _k32_n() { jq --arg c "$2" '[.hooks.Stop[]? | .hooks[]? | select(.command == $c)] | length' "$1" 2>/dev/null; }
  # (a) scaffold + wire registers the retro gate AND the return-token gate once each; reports it.
  d="$TMP/1732-a"; mkdir -p "$d"
  bash "$SUT" "$d" --corpus flat --scaffold --wire >"$TMP/1732-a.out" 2>&1
  [ "$(_k32_n "$d/.claude/settings.json" "$_k32_gq")" = 1 ] && [ "$(_k32_n "$d/.claude/settings.json" "$d/.claude/hooks/retro-gate-stop.sh")" = 1 ] \
    && ok "K1732-a --scaffold --wire registers the return-token gate and keeps the retro gate (once each)" \
    || no "K1732-a Stop registrations wrong: $(jq -c '.hooks.Stop' "$d/.claude/settings.json" 2>&1)"
  assert_grep "K1732-a reports the return-token gate registered" "Stop return-token gate registered" "$TMP/1732-a.out"
  # (b) a wire-only re-run is idempotent and says so.
  bash "$SUT" "$d" --wire >"$TMP/1732-b.out" 2>&1
  [ "$(_k32_n "$d/.claude/settings.json" "$_k32_gq")" = 1 ] && ok "K1732-b re-run does not duplicate the gate" || no "K1732-b gate registered $(_k32_n "$d/.claude/settings.json" "$_k32_gq") times after a re-run"
  assert_grep "K1732-b re-run reports already wired" "Stop return-token gate already wired" "$TMP/1732-b.out"
  # (c) wire-only repair preserves a hand-made Stop hook and adds the gate.
  d="$TMP/1732-c"; mkdir -p "$d/.claude"; : > "$d/INDEX.md"
  printf '%s' '{"hooks":{"Stop":[{"matcher":"","hooks":[{"type":"command","command":"/x/mine.sh"}]}]}}' > "$d/.claude/settings.json"
  bash "$SUT" "$d" --wire >/dev/null 2>&1
  [ "$(_k32_n "$d/.claude/settings.json" "/x/mine.sh")" = 1 ] && [ "$(_k32_n "$d/.claude/settings.json" "$_k32_gq")" = 1 ] \
    && ok "K1732-c wire-only keeps the existing Stop hook and adds the gate" || no "K1732-c Stop: $(jq -c '.hooks.Stop' "$d/.claude/settings.json" 2>&1)"
  # (d) a gate registered from a kit path that NO LONGER EXISTS is stale: it is replaced by the current one and reported.
  d="$TMP/1732-d"; mkdir -p "$d/.claude"; : > "$d/INDEX.md"
  printf '%s' '{"hooks":{"Stop":[{"matcher":"","hooks":[{"type":"command","command":"/other/kit/toolbelt/return-token-gate.sh"}]}]}}' > "$d/.claude/settings.json"
  bash "$SUT" "$d" --wire >"$TMP/1732-d.out" 2>&1
  [ "$(_k32_n "$d/.claude/settings.json" "$_k32_gq")" = 1 ] && [ "$(jq '[.hooks.Stop[]? | .hooks[]?] | map(select(.command | rtrimstr("\"") | endswith("return-token-gate.sh"))) | length' "$d/.claude/settings.json")" = 1 ] \
    && ok "K1732-d a stale gate path is replaced by the current kit path (one entry)" || no "K1732-d Stop: $(jq -c '.hooks.Stop' "$d/.claude/settings.json")"
  assert_grep "K1732-d reports the repair with the old path" "Stop return-token gate repaired (stale path /other/kit/toolbelt/return-token-gate.sh)" "$TMP/1732-d.out"
  # (d2) a gate at ANOTHER kit path that still exists is left alone (never rewritten behind the operator's back).
  d="$TMP/1732-d2"; mkdir -p "$d/.claude" "$TMP/otherkit"; : > "$d/INDEX.md"; printf '#!/bin/sh\n' > "$TMP/otherkit/return-token-gate.sh"
  printf '{"hooks":{"Stop":[{"matcher":"","hooks":[{"type":"command","command":"%s"}]}]}}' "$TMP/otherkit/return-token-gate.sh" > "$d/.claude/settings.json"
  bash "$SUT" "$d" --wire >"$TMP/1732-d2.out" 2>&1
  [ "$(_k32_n "$d/.claude/settings.json" "$TMP/otherkit/return-token-gate.sh")" = 1 ] \
    && ok "K1732-d2 an existing gate at another path is kept as-is" || no "K1732-d2 Stop: $(jq -c '.hooks.Stop' "$d/.claude/settings.json")"
  assert_grep "K1732-d2 reports it as another form" "already wired (other form: $TMP/otherkit/return-token-gate.sh)" "$TMP/1732-d2.out"
  # (d3) a QUOTED registration of the current gate is the same hook (not duplicated); a QUOTED stale one is repaired.
  d="$TMP/1732-d3"; mkdir -p "$d/.claude"; : > "$d/INDEX.md"
  jq -n --arg c "\"$_k32_gate\"" '{hooks:{Stop:[{matcher:"",hooks:[{type:"command",command:$c}]}]}}' > "$d/.claude/settings.json"
  bash "$SUT" "$d" --wire >"$TMP/1732-d3.out" 2>&1
  [ "$(jq '[.hooks.Stop[]? | .hooks[]? | select(.command | endswith("return-token-gate.sh\"") or endswith("return-token-gate.sh"))] | length' "$d/.claude/settings.json")" = 1 ] \
    && ok "K1732-d3 a quoted current gate is not duplicated" || no "K1732-d3 Stop: $(jq -c '.hooks.Stop' "$d/.claude/settings.json")"
  d="$TMP/1732-d4"; mkdir -p "$d/.claude"; : > "$d/INDEX.md"
  printf '%s' '{"hooks":{"Stop":[{"matcher":"","hooks":[{"type":"command","command":"\"/gone/kit/toolbelt/return-token-gate.sh\""}]}]}}' > "$d/.claude/settings.json"
  bash "$SUT" "$d" --wire >"$TMP/1732-d4.out" 2>&1
  [ "$(_k32_n "$d/.claude/settings.json" "$_k32_gq")" = 1 ] && ok "K1732-d4 a quoted stale gate is replaced by the current path" || no "K1732-d4 Stop: $(jq -c '.hooks.Stop' "$d/.claude/settings.json")"
  assert_grep "K1732-d4 reports the repair with the unquoted old path" "repaired (stale path /gone/kit/toolbelt/return-token-gate.sh)" "$TMP/1732-d4.out"
  # (d5) stale AND current both registered: the stale one is dropped, the current kept once.
  d="$TMP/1732-d5"; mkdir -p "$d/.claude"; : > "$d/INDEX.md"
  jq -n --arg c "$_k32_gate" '{hooks:{Stop:[{matcher:"",hooks:[{type:"command",command:"/gone/return-token-gate.sh"}]},{matcher:"",hooks:[{type:"command",command:$c}]}]}}' > "$d/.claude/settings.json"
  bash "$SUT" "$d" --wire >/dev/null 2>&1
  [ "$(_k32_n "$d/.claude/settings.json" "$_k32_gate")" = 1 ] && [ "$(jq '[.hooks.Stop[]? | .hooks[]? | select(.command | rtrimstr("\"") | endswith("return-token-gate.sh"))] | length' "$d/.claude/settings.json")" = 1 ] \
    && ok "K1732-d5 a stale gate next to the current one is dropped" || no "K1732-d5 Stop: $(jq -c '.hooks.Stop' "$d/.claude/settings.json")"
  # (d6) SEVERAL stale gate entries and no current one: exactly ONE current entry results; other hooks untouched.
  d="$TMP/1732-d6"; mkdir -p "$d/.claude"; : > "$d/INDEX.md"
  printf '%s' '{"hooks":{"Stop":[{"matcher":"","hooks":[{"type":"command","command":"/gone/a/return-token-gate.sh"}]},{"matcher":"","hooks":[{"type":"command","command":"/x/mine.sh"}]},{"matcher":"","hooks":[{"type":"command","command":"\"/gone/b/return-token-gate.sh\""},{"type":"command","command":"/gone/c/return-token-gate.sh"}]}]}}' > "$d/.claude/settings.json"
  bash "$SUT" "$d" --wire >"$TMP/1732-d6.out" 2>&1
  [ "$(jq '[.hooks.Stop[]? | .hooks[]? | select(.command | rtrimstr("\"") | endswith("return-token-gate.sh"))] | length' "$d/.claude/settings.json")" = 1 ] \
    && [ "$(_k32_n "$d/.claude/settings.json" "$_k32_gq")" = 1 ] && [ "$(_k32_n "$d/.claude/settings.json" "/x/mine.sh")" = 1 ] \
    && ok "K1732-d6 three stale gate entries collapse to ONE current entry; a non-gate hook is untouched" || no "K1732-d6 Stop: $(jq -c '.hooks.Stop' "$d/.claude/settings.json")"
  # (f) a kit under a path with a SPACE: the registered command must survive shell word-splitting, and the printed snippet
  # must be JSON-escaped.
  _k32_sp="$TMP/1732 kit sp/research-sdd"; mkdir -p "$_k32_sp/toolbelt/lib"; cp "$HERE/../research-sdd-init.sh" "$_k32_sp/toolbelt/init.sh"
  cp "$HERE/../lib/corpus-markers.sh" "$_k32_sp/toolbelt/lib/"; cp "$HERE/../lib/gh-visibility.sh" "$_k32_sp/toolbelt/lib/"; ln -s "$HERE/../../templates" "$_k32_sp/templates"
  printf '#!/bin/sh\necho gate-ran\n' > "$_k32_sp/toolbelt/return-token-gate.sh"; chmod +x "$_k32_sp/toolbelt/return-token-gate.sh"
  d="$TMP/1732-f"; mkdir -p "$d"
  bash "$_k32_sp/toolbelt/init.sh" "$d" --corpus flat --scaffold --wire >"$TMP/1732-f.out" 2>&1
  _k32_cmd="$(jq -r '[.hooks.Stop[]? | .hooks[]? | .command | select(contains("return-token-gate.sh"))] | first // empty' "$d/.claude/settings.json" 2>/dev/null)"
  [ "$(sh -c "$_k32_cmd" 2>&1)" = "gate-ran" ] && ok "K1732-f a kit path with a space: the registered gate command runs through the shell" || no "K1732-f registered command does not survive word-splitting: [$_k32_cmd]"
  d="$TMP/1732-f2"; mkdir -p "$d"
  bash "$_k32_sp/toolbelt/init.sh" "$d" --corpus flat >"$TMP/1732-f2.out" 2>&1
  assert_grep "K1732-f2 snippet carries the space path as an escaped JSON string" "\"command\":\"\\\"$_k32_sp/toolbelt/return-token-gate.sh\\\"\"" "$TMP/1732-f2.out"
  # (f3) kit issue #1757: a BARE (unquoted) registration of the current kit gate path that contains a space word-splits and
  # never runs, so it is NOT "already wired": it is rewritten to the quoted form (one entry, runnable), reported as requoted.
  _k57_gate="$_k32_sp/toolbelt/return-token-gate.sh"
  d="$TMP/1757-a"; mkdir -p "$d/.claude"; : > "$d/INDEX.md"
  jq -n --arg c "$_k57_gate" '{hooks:{Stop:[{matcher:"",hooks:[{type:"command",command:$c}]}]}}' > "$d/.claude/settings.json"
  bash "$_k32_sp/toolbelt/init.sh" "$d" --wire >"$TMP/1757-a.out" 2>&1
  _k57_cmd="$(jq -r '[.hooks.Stop[]? | .hooks[]? | .command | select(contains("return-token-gate.sh"))] | first // empty' "$d/.claude/settings.json" 2>/dev/null)"
  [ "$(_k32_n "$d/.claude/settings.json" "\"$_k57_gate\"")" = 1 ] && [ "$(_k32_n "$d/.claude/settings.json" "$_k57_gate")" = 0 ] \
    && ok "K1757-a a bare spaced current gate is rewritten to the quoted form (one entry, no bare leftover)" \
    || no "K1757-a Stop: $(jq -c '.hooks.Stop' "$d/.claude/settings.json")"
  [ "$(sh -c "$_k57_cmd" 2>&1)" = "gate-ran" ] && ok "K1757-a2 the rewritten gate command runs through the shell" || no "K1757-a2 command does not run: [$_k57_cmd]"
  assert_grep "K1757-a3 the rewrite is reported as requoted (not stale, not 'already wired')" "Stop return-token gate requoted (unquoted path with whitespace $_k57_gate would word-split)" "$TMP/1757-a.out"
  bash "$_k32_sp/toolbelt/init.sh" "$d" --wire >"$TMP/1757-b.out" 2>&1
  [ "$(_k32_n "$d/.claude/settings.json" "\"$_k57_gate\"")" = 1 ] && [ "$(jq '[.hooks.Stop[]? | .hooks[]? | select(.command | contains("return-token-gate.sh"))] | length' "$d/.claude/settings.json")" = 1 ] \
    && ok "K1757-b a re-run after the rewrite keeps exactly one quoted gate" || no "K1757-b Stop: $(jq -c '.hooks.Stop' "$d/.claude/settings.json")"
  assert_grep "K1757-b2 the re-run reports already wired" "Stop return-token gate already wired" "$TMP/1757-b.out"
  # (f4) control: a bare current gate WITHOUT whitespace is still a current form (runs fine): left byte-for-byte, no duplicate.
  d="$TMP/1757-c"; mkdir -p "$d/.claude"; : > "$d/INDEX.md"
  jq -n --arg c "$_k32_gate" '{hooks:{Stop:[{matcher:"",hooks:[{type:"command",command:$c}]}]}}' > "$d/.claude/settings.json"
  bash "$SUT" "$d" --wire >"$TMP/1757-c.out" 2>&1
  [ "$(_k32_n "$d/.claude/settings.json" "$_k32_gate")" = 1 ] && [ "$(_k32_n "$d/.claude/settings.json" "$_k32_gq")" = 0 ] \
    && ok "K1757-c a bare gate path without whitespace stays as-is (still a current form)" || no "K1757-c Stop: $(jq -c '.hooks.Stop' "$d/.claude/settings.json")"
  # (g) a gate in ANY other working form is a registered gate: kept byte-for-byte, no second gate is added, and it is
  # never classified stale (interpreter prefix, arguments, relative, ~ and $CLAUDE_PROJECT_DIR forms).
  _k32_gi=0
  # shellcheck disable=SC2088 # the literal tilde is the fixture: an unexpanded ~ command form
  for _k32_form in 'bash /x/return-token-gate.sh' '/x/return-token-gate.sh --flag' './tools/return-token-gate.sh' \
      '$CLAUDE_PROJECT_DIR/tools/return-token-gate.sh' '"$CLAUDE_PROJECT_DIR"/tools/return-token-gate.sh' '~/kit/return-token-gate.sh'; do
    _k32_gi=$((_k32_gi + 1)); d="$TMP/1732-g$_k32_gi"; mkdir -p "$d/.claude"; : > "$d/INDEX.md"
    jq -n --arg c "$_k32_form" '{hooks:{Stop:[{matcher:"",hooks:[{type:"command",command:$c}]}]}}' > "$d/.claude/settings.json"
    bash "$SUT" "$d" --wire >"$TMP/1732-g$_k32_gi.out" 2>&1
    if [ "$(jq '[.hooks.Stop[]? | .hooks[]? | select(.command | contains("return-token-gate.sh"))] | length' "$d/.claude/settings.json")" = 1 ] \
       && [ "$(jq -r '[.hooks.Stop[]? | .hooks[]? | select(.command | contains("return-token-gate.sh")) | .command] | first' "$d/.claude/settings.json")" = "$_k32_form" ] \
       && grep -qF "already wired (other form: $_k32_form)" "$TMP/1732-g$_k32_gi.out"; then
      ok "K1732-g [$_k32_form] is kept untouched, no second gate, reported as another form"
    else no "K1732-g [$_k32_form] Stop: $(jq -c '.hooks.Stop' "$d/.claude/settings.json") out: $(grep -i 'gate' "$TMP/1732-g$_k32_gi.out" | head -2)"; fi
  done
  # (g2) a dead bare absolute gate next to a WORKING other-form gate: the dead one is repaired away, no second gate is added.
  d="$TMP/1732-g2"; mkdir -p "$d/.claude"; : > "$d/INDEX.md"
  printf '%s' '{"hooks":{"Stop":[{"matcher":"","hooks":[{"type":"command","command":"/gone/return-token-gate.sh"}]},{"matcher":"","hooks":[{"type":"command","command":"bash /x/return-token-gate.sh"}]}]}}' > "$d/.claude/settings.json"
  bash "$SUT" "$d" --wire >/dev/null 2>&1
  [ "$(jq -r '[.hooks.Stop[]? | .hooks[]? | select(.command | contains("return-token-gate.sh")) | .command] | join("|")' "$d/.claude/settings.json")" = "bash /x/return-token-gate.sh" ] \
    && ok "K1732-g2 a dead gate is dropped, the working other-form gate stays, no second gate" || no "K1732-g2 Stop: $(jq -c '.hooks.Stop' "$d/.claude/settings.json")"
  # (e) print-only scaffold: the proposed snippet carries the gate and no settings.json is written.
  d="$TMP/1732-e"; mkdir -p "$d"
  bash "$SUT" "$d" --corpus flat >"$TMP/1732-e.out" 2>&1
  assert_grep "K1732-e printed snippet carries the return-token gate" "{\"matcher\":\"\",\"hooks\":[{\"type\":\"command\",\"command\":\"\\\"$_k32_gate\\\"\"}]}" "$TMP/1732-e.out"
  assert_absent "K1732-e propose-never-apply: no settings.json without --wire" "$d/.claude/settings.json"
fi

# ---- kit issue #1787 item 1: the stale-KIT drift hook is wired into a target's SessionStart ----
# A kit under a path with a SPACE and a runnable drift-hook stub: the registered command must survive word-splitting.
_k87_kit() {  # <dir> — builds <dir>/research-sdd/{toolbelt,templates} and prints the kit root
  local k="$1/research-sdd"
  mkdir -p "$k/toolbelt/lib"; cp "$HERE/../research-sdd-init.sh" "$k/toolbelt/init.sh"; cp "$HERE/../lib/corpus-markers.sh" "$k/toolbelt/lib/"; cp "$HERE/../lib/gh-visibility.sh" "$k/toolbelt/lib/"
  ln -s "$HERE/../../templates" "$k/templates"; cp "$HERE/../scan-vendor-leak.sh" "$k/toolbelt/"
  printf '#!/bin/sh\necho drift-ran\n' > "$k/toolbelt/verify-skill-drift-hook.sh"; chmod +x "$k/toolbelt/verify-skill-drift-hook.sh"
  printf '%s' "$k"
}
_k87_n() { jq --arg c "$2" '[.hooks.SessionStart[]? | .hooks[]? | select(.command == $c)] | length' "$1" 2>/dev/null; }
_k87_all() { jq '[.hooks.SessionStart[]? | .hooks[]? | select((.command // "") | contains("verify-skill-drift-hook.sh"))] | length' "$1" 2>/dev/null; }
if command -v jq >/dev/null 2>&1; then
  _k87_k="$(_k87_kit "$TMP/1787 kit sp")"; _k87_dp="$_k87_k/toolbelt/verify-skill-drift-hook.sh"; _k87_dq="\"$_k87_dp\""
  # (a) scaffold --wire: registered once, double-quoted, runs through the shell; the live <SUBJECT> SessionStart skip does not block it.
  d="$TMP/1787-a"; mkdir -p "$d"
  bash "$_k87_k/toolbelt/init.sh" "$d" --corpus flat --scaffold --wire >"$TMP/1787-a.out" 2>&1
  _k87_cmd="$(jq -r '[.hooks.SessionStart[]? | .hooks[]? | .command | select(contains("verify-skill-drift-hook.sh"))] | first // empty' "$d/.claude/settings.json" 2>/dev/null)"
  [ "$(_k87_n "$d/.claude/settings.json" "$_k87_dq")" = 1 ] && [ "$(_k87_all "$d/.claude/settings.json")" = 1 ] \
    && ok "K1787-a scaffold --wire registers the drift hook once, double-quoted (spaced kit path)" || no "K1787-a SessionStart: $(jq -c '.hooks.SessionStart' "$d/.claude/settings.json" 2>/dev/null)"
  [ "$(sh -c "$_k87_cmd" 2>&1)" = "drift-ran" ] && ok "K1787-a2 the registered command runs through the shell" || no "K1787-a2 does not run: [$_k87_cmd]"
  assert_grep "K1787-a3 typed registered line" "SessionStart stale-KIT drift hook registered" "$TMP/1787-a.out"
  # (b) re-run (wire-only path): a no-op on the bytes, reported as already wired.
  cp "$d/.claude/settings.json" "$TMP/1787-a.before"
  bash "$_k87_k/toolbelt/init.sh" "$d" --wire >"$TMP/1787-b.out" 2>&1
  cmp -s "$TMP/1787-a.before" "$d/.claude/settings.json" && ok "K1787-b re-run leaves settings.json byte-identical" || no "K1787-b settings.json changed on a re-run"
  assert_grep "K1787-b2 re-run reports already wired" "SessionStart stale-KIT drift hook already wired" "$TMP/1787-b.out"
  # (c) a user's SessionStart hook is preserved; a STALE absolute drift path is repaired; a still-existing OTHER form is kept untouched.
  d="$TMP/1787-c"; mkdir -p "$d/.claude"; : > "$d/INDEX.md"
  printf '%s' '{"hooks":{"SessionStart":[{"matcher":"","hooks":[{"type":"command","command":"/x/mine.sh"}]},{"matcher":"","hooks":[{"type":"command","command":"\"/gone/kit/verify-skill-drift-hook.sh\""},{"type":"command","command":"/x/other.sh"}]}]}}' > "$d/.claude/settings.json"
  bash "$_k87_k/toolbelt/init.sh" "$d" --wire >"$TMP/1787-c.out" 2>&1
  [ "$(_k87_n "$d/.claude/settings.json" "/x/mine.sh")" = 1 ] && [ "$(_k87_n "$d/.claude/settings.json" "/x/other.sh")" = 1 ] \
    && [ "$(_k87_n "$d/.claude/settings.json" "$_k87_dq")" = 1 ] && [ "$(_k87_all "$d/.claude/settings.json")" = 1 ] \
    && ok "K1787-c user hooks preserved, stale drift path replaced by exactly one current entry" || no "K1787-c SessionStart: $(jq -c '.hooks.SessionStart' "$d/.claude/settings.json")"
  assert_grep "K1787-c2 the repair is reported" "stale-KIT drift hook repaired (stale path /gone/kit/verify-skill-drift-hook.sh)" "$TMP/1787-c.out"
  d="$TMP/1787-c3"; mkdir -p "$d/.claude"; : > "$d/INDEX.md"
  jq -n --arg c "\$CLAUDE_PROJECT_DIR/kit/verify-skill-drift-hook.sh" '{hooks:{SessionStart:[{matcher:"",hooks:[{type:"command",command:$c}]}]}}' > "$d/.claude/settings.json"
  bash "$_k87_k/toolbelt/init.sh" "$d" --wire >"$TMP/1787-c3.out" 2>&1
  [ "$(_k87_all "$d/.claude/settings.json")" = 1 ] && assert_grep "K1787-c3 a working registration in another form is kept, nothing is added next to it" "already wired (other form:" "$TMP/1787-c3.out" \
    || no "K1787-c3 duplicate next to another form: $(jq -c '.hooks.SessionStart' "$d/.claude/settings.json")"
  # (d) a bare spaced current path word-splits: rewritten to the quoted form (one entry).
  d="$TMP/1787-d"; mkdir -p "$d/.claude"; : > "$d/INDEX.md"
  jq -n --arg c "$_k87_dp" '{hooks:{SessionStart:[{matcher:"",hooks:[{type:"command",command:$c}]}]}}' > "$d/.claude/settings.json"
  bash "$_k87_k/toolbelt/init.sh" "$d" --wire >"$TMP/1787-d.out" 2>&1
  [ "$(_k87_n "$d/.claude/settings.json" "$_k87_dq")" = 1 ] && [ "$(_k87_all "$d/.claude/settings.json")" = 1 ] \
    && ok "K1787-d a bare spaced drift path is rewritten to the quoted form (one entry)" || no "K1787-d SessionStart: $(jq -c '.hooks.SessionStart' "$d/.claude/settings.json")"
  assert_grep "K1787-d2 reported as requoted" "stale-KIT drift hook requoted" "$TMP/1787-d.out"
  # (e) propose-never-apply: the plain run prints the drift entry and writes no settings.json.
  d="$TMP/1787-e"; mkdir -p "$d"
  bash "$_k87_k/toolbelt/init.sh" "$d" --corpus flat >"$TMP/1787-e.out" 2>&1
  assert_grep "K1787-e snippet carries the drift hook" "verify-skill-drift-hook.sh" "$TMP/1787-e.out"
  assert_absent "K1787-e no settings.json without --wire" "$d/.claude/settings.json"
  # (f) RDD round 1: the drift pass is ADVISORY. A forced failure is a typed WARN, the exit code of the core wire is unchanged, and
  # the settings the main merge wrote stay intact (wire-only path).
  d="$TMP/1787-f"; mkdir -p "$d/.claude"; : > "$d/INDEX.md"
  RSDD_TEST_DRIFT_FAIL=1 bash "$_k87_k/toolbelt/init.sh" "$d" --wire >"$TMP/1787-f.out" 2>&1; _k87_rc=$?
  [ "$_k87_rc" = 0 ] && ok "K1787-f a drift-pass failure leaves the core wire's exit code at 0" || no "K1787-f exit $_k87_rc (a drift failure must not be fatal)"
  assert_grep "K1787-f2 typed WARN" "WARN   : drift hook not registered:" "$TMP/1787-f.out"
  [ "$(_k87_all "$d/.claude/settings.json")" = 0 ] && [ "$(jq '[.hooks.Stop[]? | .hooks[]? | select(.command | contains("return-token-gate.sh"))] | length' "$d/.claude/settings.json")" = 1 ] \
    && ok "K1787-f3 settings from the main merge intact (gate wired, no drift entry)" || no "K1787-f3 settings: $(jq -c '.hooks' "$d/.claude/settings.json" 2>/dev/null)"
  assert_grep "K1787-f4 the rest of the wire still reported" "== done ==" "$TMP/1787-f.out"
  # (g) RDD round 1: a stale entry dropped while a current one remains must not print an empty "other form".
  d="$TMP/1787-g"; mkdir -p "$d/.claude"; : > "$d/INDEX.md"
  jq -n --arg c "$_k87_dq" '{hooks:{SessionStart:[{matcher:"",hooks:[{type:"command",command:"\"/gone/kit/verify-skill-drift-hook.sh\""},{type:"command",command:$c}]}]}}' > "$d/.claude/settings.json"
  bash "$_k87_k/toolbelt/init.sh" "$d" --wire >"$TMP/1787-g.out" 2>&1
  assert_grep "K1787-g the stale drop is reported" "drift hook repaired (stale path /gone/kit/verify-skill-drift-hook.sh)" "$TMP/1787-g.out"
  if grep -qF "other form: )" "$TMP/1787-g.out" || ! grep -qF "drift hook already wired in" "$TMP/1787-g.out"; then no "K1787-g misleading outcome line: $(grep 'drift hook' "$TMP/1787-g.out" | tr '\n' '|')"
  else ok "K1787-g accurate outcome line (already wired, no empty other form)"; fi
fi

# ---- kit issue #1271 (last item): vendor-leak pre-push hook on a PUBLIC remote ----
if command -v git >/dev/null 2>&1 && command -v jq >/dev/null 2>&1 && [ -n "${K71_BIN:-}" ]; then
  _k87_k="$(_k87_kit "$TMP/1271 kit sp")"; _kpp_init="$_k87_k/toolbelt/init.sh"
  _kpp_run() {  # <target> <vis> [init args…] — spaced kit, stubbed gh
    local d="$1" vis="$2"; shift 2
    PATH="$K71_BIN:$PATH" K71_VIS="$vis" K71_RC=0 bash "$_kpp_init" "$d" --corpus flat "$@" >"$TMP/kpp.out" 2>&1
    return 0
  }
  # (a) PUBLIC, plain run: proposed, NOT written.
  d="$(_k71_target pp-a https://example.invalid/pub.git)"
  _kpp_run "$d" PUBLIC
  assert_absent "K1271-pp-a dry run writes no pre-push hook" "$d/.git/hooks/pre-push"
  assert_grep "K1271-pp-a dry run proposes the hook (scanner --tracked)" "exec bash" "$TMP/kpp.out"
  assert_grep "K1271-pp-a dry run names how to apply it" "pre-push guard (propose-never-apply" "$TMP/kpp.out"
  # (b) PUBLIC --wire: written, executable, blocks a committed vendor binary, passes a clean tree — through a SPACED kit path.
  d="$(_k71_target pp-b https://example.invalid/pub.git)"
  _kpp_run "$d" PUBLIC --wire --scaffold
  [ -x "$d/.git/hooks/pre-push" ] && ok "K1271-pp-b --wire writes an executable pre-push hook" || no "K1271-pp-b hook missing or not executable"
  assert_grep "K1271-pp-b typed wrote line" "vendor-leak: wrote pre-push guard" "$TMP/kpp.out"
  ( cd "$d" && git add -A >/dev/null 2>&1 && git -c user.email=t@t -c user.name=t commit -qm init >/dev/null 2>&1 )
  # Real pushes to a local bare repo: git feeds the hook the pushed refs on stdin (RDD round 1: the pushed content is scanned, not the checkout).
  _kpp_bare="$TMP/kpp-b.bare"; git init -q --bare "$_kpp_bare" 2>/dev/null; _kpp_br="$(git -C "$d" symbolic-ref --short HEAD)"
  ( cd "$d" && git push "$_kpp_bare" "HEAD:refs/heads/$_kpp_br" >"$TMP/kpp-clean.out" 2>&1 ); _kpp_rc=$?
  [ "$_kpp_rc" = 0 ] && ok "K1271-pp-b a push of a clean tree passes" || no "K1271-pp-b clean push rc=$_kpp_rc ($(tail -3 "$TMP/kpp-clean.out"))"
  assert_grep "K1271-pp-b the guard really scanned the pushed commit" "pushed file version" "$TMP/kpp-clean.out"
  ( cd "$d" && git checkout -q -b leakbr && : > Vendor.class && git add Vendor.class && git -c user.email=t@t -c user.name=t commit -qm leak && git checkout -q "$_kpp_br" ) >/dev/null 2>&1
  ( cd "$d" && git push "$_kpp_bare" "$_kpp_br" >"$TMP/kpp-ok2.out" 2>&1 ); _kpp_rc=$?
  [ "$_kpp_rc" = 0 ] && ok "K1271-pp-b pushing the clean branch while a leaking branch exists passes" || no "K1271-pp-b clean branch push rc=$_kpp_rc"
  ( cd "$d" && git push "$_kpp_bare" leakbr >"$TMP/kpp-leak.out" 2>&1 ); _kpp_rc=$?
  [ "$_kpp_rc" != 0 ] && grep -qF "Vendor.class" "$TMP/kpp-leak.out" && ok "K1271-pp-b pushing a NON-checked-out branch that carries a vendor binary is BLOCKED" || no "K1271-pp-b leak push rc=$_kpp_rc ($(tail -3 "$TMP/kpp-leak.out"))"
  [ -z "$(git -C "$_kpp_bare" rev-parse --verify -q refs/heads/leakbr)" ] && ok "K1271-pp-b the leaking ref never reached the remote" || no "K1271-pp-b leak reached the remote"
  assert_grep "K1271-pp-b a blocked push says BLOCKED (distinct from the NOT checked path)" "push BLOCKED" "$TMP/kpp-leak.out"
  # RDD round 2: a vendor binary added in one commit and DELETED in the next still reaches the public history; the whole pushed range is scanned.
  ( cd "$d" && git checkout -q -b delbr "$_kpp_br" && : > Gone.jar && git add Gone.jar && git -c user.email=t@t -c user.name=t commit -qm "add jar" \
      && git rm -q Gone.jar && git -c user.email=t@t -c user.name=t commit -qm "drop jar" && git checkout -q "$_kpp_br" ) >/dev/null 2>&1
  ( cd "$d" && git push "$_kpp_bare" delbr >"$TMP/kpp-del2.out" 2>&1 ); _kpp_rc=$?
  [ "$_kpp_rc" != 0 ] && grep -qF "Gone.jar" "$TMP/kpp-del2.out" && ok "K1271-pp-b a leak added then deleted inside the pushed range is BLOCKED" || no "K1271-pp-b add-then-delete rc=$_kpp_rc ($(tail -3 "$TMP/kpp-del2.out"))"
  # a path with TWO pushed versions: the first (flagged) one is scanned too, not only the last.
  ( cd "$d" && git checkout -q -b verbr "$_kpp_br" && : > Two.dll && git add Two.dll && git -c user.email=t@t -c user.name=t commit -qm v1 \
      && printf x > Two.dll && git -c user.email=t@t -c user.name=t commit -qam v2 && git checkout -q "$_kpp_br" ) >/dev/null 2>&1
  ( cd "$d" && git push "$_kpp_bare" verbr >"$TMP/kpp-ver.out" 2>&1 ); _kpp_rc=$?
  [ "$_kpp_rc" != 0 ] && grep -qF "Two.dll" "$TMP/kpp-ver.out" && ok "K1271-pp-b a path pushed in several versions is scanned (round 1 and 2)" || no "K1271-pp-b multi-version rc=$_kpp_rc"
  ( cd "$d" && git push "$_kpp_bare" "HEAD:refs/heads/tmpdel" >/dev/null 2>&1; git push "$_kpp_bare" :tmpdel >"$TMP/kpp-del.out" 2>&1 ); _kpp_rc=$?
  [ "$_kpp_rc" = 0 ] && ok "K1271-pp-b a ref deletion (zero sha) is skipped, not blocked" || no "K1271-pp-b deletion rc=$_kpp_rc"
  # (c) idempotent: our own up-to-date hook already present (the vendor-leak step runs on the scaffold path only) is left byte-identical.
  cp "$d/.git/hooks/pre-push" "$TMP/kpp-c.before"
  d="$(_k71_target pp-c https://example.invalid/pub.git)"; mkdir -p "$d/.git/hooks"; cp "$TMP/kpp-c.before" "$d/.git/hooks/pre-push"; chmod +x "$d/.git/hooks/pre-push"
  _kpp_run "$d" PUBLIC --wire --scaffold
  cmp -s "$TMP/kpp-c.before" "$d/.git/hooks/pre-push" && ok "K1271-pp-c re-run keeps the hook byte-identical" || no "K1271-pp-c hook changed on a re-run"
  assert_grep "K1271-pp-c typed already-wired line" "pre-push guard already wired" "$TMP/kpp.out"
  # (d) a FOREIGN hook is never overwritten: typed skip + the line to add by hand (dry run and --wire alike).
  d="$(_k71_target pp-d https://example.invalid/pub.git)"; mkdir -p "$d/.git/hooks"; printf '#!/bin/sh\necho mine\n' > "$d/.git/hooks/pre-push"
  _kpp_run "$d" PUBLIC --wire --scaffold
  assert_grep "K1271-pp-d foreign hook bytes untouched" "echo mine" "$d/.git/hooks/pre-push"
  [ "$(wc -l < "$d/.git/hooks/pre-push")" = 2 ] && ok "K1271-pp-d foreign hook not appended to" || no "K1271-pp-d foreign hook modified"
  assert_grep "K1271-pp-d typed skip" "pre-push guard skipped (foreign pre-push hook)" "$TMP/kpp.out"
  assert_grep "K1271-pp-d prints the line to add by hand" "hook-prepush-vendor-leak.sh' \"\$@\" || exit 1" "$TMP/kpp.out"
  d="$(_k71_target pp-d2 https://example.invalid/pub.git)"; mkdir -p "$d/.git/hooks"; printf '#!/bin/sh\necho mine\n' > "$d/.git/hooks/pre-push"
  _kpp_run "$d" PUBLIC
  assert_grep "K1271-pp-d2 dry run also reports the foreign hook" "foreign pre-push hook" "$TMP/kpp.out"
  # (e) PRIVATE remote -> no pre-push hook at all.
  d="$(_k71_target pp-e https://example.invalid/priv.git)"
  _kpp_run "$d" PRIVATE --wire --scaffold
  assert_absent "K1271-pp-e PRIVATE: no pre-push hook" "$d/.git/hooks/pre-push"
  # (f) our own hook with a stale kit path is refreshed by --wire (and only proposed without it).
  d="$(_k71_target pp-f https://example.invalid/pub.git)"; mkdir -p "$d/.git/hooks"
  printf '#!/usr/bin/env bash\n# research-sdd vendor-leak guard (pre-push) — old\nSCAN='"'"'/gone/scan-vendor-leak.sh'"'"'\n' > "$d/.git/hooks/pre-push"; chmod +x "$d/.git/hooks/pre-push"
  d2="$(_k71_target pp-f2 https://example.invalid/pub.git)"; mkdir -p "$d2/.git/hooks"; cp "$d/.git/hooks/pre-push" "$d2/.git/hooks/pre-push"
  _kpp_run "$d2" PUBLIC
  assert_grep "K1271-pp-f dry run leaves the stale hook alone" "/gone/scan-vendor-leak.sh" "$d2/.git/hooks/pre-push"
  _kpp_run "$d" PUBLIC --wire --scaffold
  assert_grep "K1271-pp-f --wire refreshes our own stale hook" "$_k87_k/templates/hook-prepush-vendor-leak.sh" "$d/.git/hooks/pre-push"
  # (g) core.hooksPath is honoured.
  d="$(_k71_target pp-g https://example.invalid/pub.git)"; git -C "$d" config core.hooksPath "$d/myhooks"
  _kpp_run "$d" PUBLIC --wire --scaffold
  [ -x "$d/myhooks/pre-push" ] && [ ! -e "$d/.git/hooks/pre-push" ] && ok "K1271-pp-g hook written under core.hooksPath" || no "K1271-pp-g wrong hook location"
  # (i) RDD round 1: a drift-pass failure on the scaffold path is a WARN and the vendor-leak / pre-push step still runs; exit unchanged.
  PATH="$K71_BIN:$PATH" K71_VIS=PUBLIC K71_RC=0 RSDD_TEST_DRIFT_FAIL=1 bash "$_kpp_init" "$(_k71_target pp-i2 https://example.invalid/pub.git)" --corpus flat --wire --scaffold >"$TMP/kpp-i.out" 2>&1; _kpp_rc=$?
  [ "$_kpp_rc" = 0 ] && ok "K1787-i scaffold --wire with a failing drift pass exits 0" || no "K1787-i exit $_kpp_rc"
  assert_grep "K1787-i typed WARN" "drift hook not registered:" "$TMP/kpp-i.out"
  [ -x "$TMP/k71-pp-i2/.git/hooks/pre-push" ] && ok "K1787-i the pre-push step still ran after the drift failure" || no "K1787-i pre-push hook missing (vendor-leak step skipped?)"
  # (h) a single quote in the kit path survives into the hook.
  _k87_q="$(_k87_kit "$TMP/1271 it's kit")"; d="$(_k71_target pp-h https://example.invalid/pub.git)"
  PATH="$K71_BIN:$PATH" K71_VIS=PUBLIC K71_RC=0 bash "$_k87_q/toolbelt/init.sh" "$d" --corpus flat --wire --scaffold >"$TMP/kpp.out" 2>&1
  git init -q --bare "$TMP/kpp-h.bare" 2>/dev/null
  ( cd "$d" && git add -A && git -c user.email=t@t -c user.name=t commit -qm init >/dev/null 2>&1; git push "$TMP/kpp-h.bare" HEAD:refs/heads/x >"$TMP/kpp-q.out" 2>&1 ); _kpp_rc=$?
  [ "$_kpp_rc" = 0 ] && grep -qF "pushed file version" "$TMP/kpp-q.out" && ok "K1271-pp-h a kit path with a single quote still runs the guard on a push" || no "K1271-pp-h rc=$_kpp_rc ($(head -3 "$TMP/kpp-q.out"))"
fi

# ---- kit issue #1800: the vendor-leak step also runs on the --wire repair path of an EXISTING corpus (PRIVATE -> PUBLIC) ----
if command -v git >/dev/null 2>&1 && command -v jq >/dev/null 2>&1 && [ -n "${K71_BIN:-}" ]; then
  _k00_target() {  # <name> [remote-url] — an existing corpus (INDEX.md marker) in a git repo
    local t; t="$(_k71_target "k00-$1" "${2:-}")"; : > "$t/INDEX.md"; printf '%s' "$t"
  }
  _k00_vl() { printf '%s %s %s' "$([ -e "$1/.research-sdd/vendor-leak.conf" ] && echo conf)" "$([ -e "$1/.github/workflows/vendor-leak.yml" ] && echo wf)" "$([ -e "$1/.git/hooks/pre-push" ] && echo hook)"; }
  # (a) PUBLIC: --wire on an existing corpus scaffolds the conf, writes the CI workflow and the pre-push hook.
  d="$(_k00_target a https://example.invalid/pub.git)"; : > "$TMP/k71.gh.log"
  PATH="$K71_BIN:$PATH" K71_VIS=PUBLIC K71_RC=0 K71_LOG="$TMP/k71.gh.log" bash "$_kpp_init" "$d" --wire >"$TMP/k00-a.out" 2>&1; _rc=$?
  [ "$_rc" = 0 ] && ok "K1800-a --wire on an existing PUBLIC corpus exits 0" || no "K1800-a exit $_rc"
  [ "$(_k00_vl "$d")" = "conf wf hook" ] && ok "K1800-a conf + CI workflow + pre-push hook written" || no "K1800-a wiring: [$(_k00_vl "$d")]"
  [ -x "$d/.git/hooks/pre-push" ] && ok "K1800-a pre-push hook is executable" || no "K1800-a pre-push hook not executable"
  assert_grep "K1800-a typed PUBLIC line" "vendor-leak: PUBLIC" "$TMP/k00-a.out"
  assert_grep "K1800-a typed pre-push line" "vendor-leak: wrote pre-push guard" "$TMP/k00-a.out"
  assert_grep "K1800-a reuses the bounded gh visibility probe" "repo view" "$TMP/k71.gh.log"
  assert_grep "K1800-a the corpus step still finishes (== done ==)" "== done ==" "$TMP/k00-a.out"
  # (b) PRIVATE first (typed, nothing written), then the repo goes PUBLIC and the same --wire now installs everything.
  d="$(_k00_target b https://example.invalid/priv.git)"
  PATH="$K71_BIN:$PATH" K71_VIS=PRIVATE K71_RC=0 bash "$_kpp_init" "$d" --wire >"$TMP/k00-b1.out" 2>&1
  [ "$(_k00_vl "$d")" = "  " ] && ok "K1800-b PRIVATE: nothing vendor-leak written" || no "K1800-b PRIVATE wrote: [$(_k00_vl "$d")]"
  assert_grep "K1800-b PRIVATE typed line" "vendor-leak: PRIVATE" "$TMP/k00-b1.out"
  PATH="$K71_BIN:$PATH" K71_VIS=PUBLIC K71_RC=0 bash "$_kpp_init" "$d" --wire >"$TMP/k00-b2.out" 2>&1
  [ "$(_k00_vl "$d")" = "conf wf hook" ] && ok "K1800-b PRIVATE -> PUBLIC: a later --wire installs conf + workflow + hook" || no "K1800-b after PUBLIC: [$(_k00_vl "$d")]"
  # (c) idempotent: a third run changes no byte and reports kept / already wired.
  cp "$d/.research-sdd/vendor-leak.conf" "$TMP/k00-c.conf"; cp "$d/.github/workflows/vendor-leak.yml" "$TMP/k00-c.wf"; cp "$d/.git/hooks/pre-push" "$TMP/k00-c.hook"
  PATH="$K71_BIN:$PATH" K71_VIS=PUBLIC K71_RC=0 bash "$_kpp_init" "$d" --wire >"$TMP/k00-c.out" 2>&1
  { cmp -s "$TMP/k00-c.conf" "$d/.research-sdd/vendor-leak.conf" && cmp -s "$TMP/k00-c.wf" "$d/.github/workflows/vendor-leak.yml" && cmp -s "$TMP/k00-c.hook" "$d/.git/hooks/pre-push"; } \
    && ok "K1800-c re-run leaves conf, workflow and hook byte-identical" || no "K1800-c a file changed on a re-run"
  assert_grep "K1800-c typed kept-existing line" "kept existing" "$TMP/k00-c.out"
  assert_grep "K1800-c typed already-wired hook line" "pre-push guard already wired" "$TMP/k00-c.out"
  # (d) user-modified / foreign files are never overwritten (propose instead): conf, workflow, foreign pre-push hook.
  d="$(_k00_target d https://example.invalid/pub.git)"; mkdir -p "$d/.research-sdd" "$d/.github/workflows" "$d/.git/hooks"
  printf 'prefix com.keepme\n' > "$d/.research-sdd/vendor-leak.conf"; printf 'hand-written\n' > "$d/.github/workflows/vendor-leak.yml"; printf '#!/bin/sh\necho mine\n' > "$d/.git/hooks/pre-push"
  PATH="$K71_BIN:$PATH" K71_VIS=PUBLIC K71_RC=0 bash "$_kpp_init" "$d" --wire >"$TMP/k00-d.out" 2>&1
  assert_grep "K1800-d user conf untouched" "prefix com.keepme" "$d/.research-sdd/vendor-leak.conf"
  assert_grep "K1800-d user workflow untouched" "hand-written" "$d/.github/workflows/vendor-leak.yml"
  { [ "$(wc -l < "$d/.git/hooks/pre-push")" = 2 ] && grep -qF 'echo mine' "$d/.git/hooks/pre-push"; } && ok "K1800-d foreign pre-push hook untouched" || no "K1800-d foreign hook modified"
  assert_grep "K1800-d typed foreign-hook skip with the line to add by hand" "pre-push guard skipped (foreign pre-push hook)" "$TMP/k00-d.out"
  # (e) visibility unknowable: typed DEGRADED (never a silent pass), nothing written, the wire itself still succeeds.
  d="$(_k00_target e https://example.invalid/pub.git)"
  PATH="$K71_BIN:$PATH" K71_VIS='' K71_RC=1 K71_ERR="gh: not logged in" bash "$_kpp_init" "$d" --wire >"$TMP/k00-e.out" 2>&1; _rc=$?
  [ "$_rc" = 0 ] && ok "K1800-e gh failing: --wire still exits 0" || no "K1800-e exit $_rc"
  assert_grep "K1800-e typed DEGRADED" "vendor-leak: DEGRADED" "$TMP/k00-e.out"
  [ "$(_k00_vl "$d")" = "  " ] && ok "K1800-e DEGRADED: nothing written" || no "K1800-e DEGRADED wrote: [$(_k00_vl "$d")]"
  d="$(_k00_target e2 https://example.invalid/pub.git)"
  PATH="$K71_NOGH" bash "$_kpp_init" "$d" --wire >"$TMP/k00-e2.out" 2>&1
  assert_grep "K1800-e2 gh missing: typed DEGRADED" "vendor-leak: DEGRADED gh not found" "$TMP/k00-e2.out"
  # (f) no remote: typed NO-REMOTE, gh never asked.
  d="$(_k00_target f)"; : > "$TMP/k71.gh.log"
  PATH="$K71_BIN:$PATH" K71_VIS=PUBLIC K71_RC=0 K71_LOG="$TMP/k71.gh.log" bash "$_kpp_init" "$d" --wire >"$TMP/k00-f.out" 2>&1
  assert_grep "K1800-f typed NO-REMOTE" "vendor-leak: NO-REMOTE" "$TMP/k00-f.out"
  [ ! -s "$TMP/k71.gh.log" ] && ok "K1800-f no gh call without a remote" || no "K1800-f gh was called"
  # (g) RDD: the "do this later" guidance is true for the path that printed it. On the wire path of an EXISTING corpus a plain run is
  # refused (exit 3), so the advice is "re-run with --wire" and never "a plain run scaffolds the conf"; the scaffold path keeps its wording.
  for _w in f:NO-REMOTE b1:PRIVATE; do
    _f="$TMP/k00-${_w%%:*}.out"
    assert_grep "K1800-g wire path ${_w##*:}: advice is re-run with --wire" "re-run with --wire (a plain run on an existing corpus is refused)" "$_f"
    if grep -qF 'a plain run scaffolds the conf' "$_f"; then no "K1800-g wire path ${_w##*:}: misleading 'a plain run scaffolds the conf'"; else ok "K1800-g wire path ${_w##*:}: no misleading plain-run advice"; fi
  done
  d="$TMP/k00-g-nogit"; mkdir -p "$d"; : > "$d/INDEX.md"   # existing corpus that is not a work tree at all
  PATH="$K71_BIN:$PATH" K71_VIS=PUBLIC K71_RC=0 bash "$_kpp_init" "$d" --wire >"$TMP/k00-g.out" 2>&1
  assert_grep "K1800-g wire path, not a work tree: typed NO-REMOTE" "vendor-leak: NO-REMOTE" "$TMP/k00-g.out"
  assert_grep "K1800-g wire path, not a work tree: advice is re-run with --wire" "re-run with --wire (a plain run on an existing corpus is refused)" "$TMP/k00-g.out"
  d="$(_k71_target g-scaf)"; PATH="$K71_BIN:$PATH" K71_VIS=PUBLIC K71_RC=0 bash "$_kpp_init" "$d" --corpus flat >"$TMP/k00-g2.out" 2>&1
  assert_grep "K1800-g scaffold path keeps 'a plain run scaffolds the conf'" "a plain run scaffolds the conf" "$TMP/k00-g2.out"
  # the mode is an explicit argument: a stray exported variable of the old name cannot flip the scaffold path's guidance
  d="$(_k71_target g-env)"; _RSDD_WIREONLY=1 PATH="$K71_BIN:$PATH" K71_VIS=PUBLIC K71_RC=0 bash "$_kpp_init" "$d" --corpus flat >"$TMP/k00-g3.out" 2>&1
  assert_grep "K1800-g an exported _RSDD_WIREONLY does not flip the scaffold wording" "a plain run scaffolds the conf" "$TMP/k00-g3.out"
  # (h) RDD: with NO `timeout` binary the wire-repair probe is still bounded (bash watchdog); a stalled gh is the typed "timed out"
  # DEGRADED, the repair finishes and exits 0.
  _k00_noto="$TMP/k00noto"; mkdir -p "$_k00_noto"; cp -P "$K71_NOGH"/* "$_k00_noto"/; rm -f "$_k00_noto/timeout"; cp "$K71_BIN/gh" "$_k00_noto/gh"
  d="$(_k00_target h https://example.invalid/pub.git)"; _t0=$SECONDS
  PATH="$_k00_noto" RSDD_GH_TIMEOUT=1 K71_SLEEP=8 K71_VIS=PUBLIC K71_RC=0 bash "$_kpp_init" "$d" --wire >"$TMP/k00-h.out" 2>&1; _rc=$?
  _el=$((SECONDS - _t0))
  [ "$_rc" = 0 ] && ok "K1800-h stalled gh without timeout: --wire repair exits 0" || no "K1800-h exit $_rc"
  [ "$_el" -lt 6 ] && ok "K1800-h the probe is bounded without timeout (${_el}s < 6s stall)" || no "K1800-h not bounded: ${_el}s"
  assert_grep "K1800-h typed timed-out DEGRADED" "vendor-leak: DEGRADED gh timed out after 1s" "$TMP/k00-h.out"
  assert_grep "K1800-h the repair still finished" "== done ==" "$TMP/k00-h.out"
  [ -f "$d/.claude/settings.json" ] && ok "K1800-h the settings.json repair happened" || no "K1800-h settings.json missing"
  # (i) kit issue #1834: the SUCCESS path of the no-`timeout` watchdog. gh answers PUBLIC at once -> the real visibility is used
  # (not a typed timeout), the run is fast, and the watchdog is reaped: a pid-recording `sleep` shim proves, with kill -0, that no
  # watchdog `sleep` survives the run (the bound is 8s; a leaked sleep is still alive right after the run).
  _k34_real_sleep="$(command -v sleep)"; _k34_bin="$TMP/k34bin"; mkdir -p "$_k34_bin"; cp -P "$_k00_noto"/* "$_k34_bin"/ 2>/dev/null
  rm -f "$_k34_bin/timeout" "$_k34_bin/gtimeout" "$_k34_bin/sleep"
  printf '#!/usr/bin/env bash\necho $$ >> "${K34_PIDS:?}"\nexec "%s" "$@"\n' "$_k34_real_sleep" > "$_k34_bin/sleep"; chmod +x "$_k34_bin/sleep"
  _k34_run() {  # <name> <init.sh> — PUBLIC answered at once, no timeout binary; sets _k34_rc/_k34_el, output $TMP/k34-<name>.out, pids $TMP/k34-<name>.pids
    local d; d="$(_k00_target "k34-$1" https://example.invalid/pub.git)"; : > "$TMP/k34-$1.pids"; local t0=$SECONDS
    PATH="$_k34_bin" RSDD_GH_TIMEOUT=8 K71_SLEEP=1 K34_PIDS="$TMP/k34-$1.pids" K71_VIS=PUBLIC K71_RC=0 bash "$2" "$d" --wire >"$TMP/k34-$1.out" 2>&1; _k34_rc=$?
    _k34_el=$((SECONDS - t0))
  }
  _k34_alive() {  # <pidfile> — prints the recorded pids still alive after a 2s grace for the kernel to reap them
    local p live
    for _ in 1 2 3 4; do
      live=""; while read -r p; do [ -n "$p" ] && kill -0 "$p" 2>/dev/null && live="$live $p"; done < "$1"
      [ -z "$live" ] && break; "$_k34_real_sleep" 0.5
    done
    printf '%s' "${live# }"
  }
  _k34_run i "$_kpp_init"
  [ "$_k34_rc" = 0 ] && ok "K1834-i watchdog success: --wire exits 0" || no "K1834-i exit $_k34_rc"
  assert_grep "K1834-i the real PUBLIC answer was used" "vendor-leak: PUBLIC" "$TMP/k34-i.out"
  assert_grep "K1834-i bounded by the watchdog (no timeout binary)" "bounded by a 8s watchdog" "$TMP/k34-i.out"
  if grep -qF 'timed out' "$TMP/k34-i.out"; then no "K1834-i a successful probe was reported as timed out"; else ok "K1834-i no typed timeout on the success path"; fi
  [ "$_k34_el" -lt 7 ] && ok "K1834-i the success path did not wait for the bound (${_k34_el}s < 8s)" || no "K1834-i waited ${_k34_el}s"
  [ -s "$TMP/k34-i.pids" ] && ok "K1834-i the watchdog sleep ran through the pid-recording shim" || no "K1834-i no sleep pid recorded — the shim was bypassed"
  [ -z "$(_k34_alive "$TMP/k34-i.pids")" ] && ok "K1834-i no watchdog sleep survives the run (kill -0)" || no "K1834-i leaked watchdog sleep pid(s): $(_k34_alive "$TMP/k34-i.pids")"
fi

# ---- kit issue #1804: .research-sdd/plan/ is gitignored (block resume plan, #1178) — scaffold AND --wire repair ----
_k04_cnt() { [ -f "$1" ] || { echo 0; return 0; }; grep -cxF '.research-sdd/plan/' "$1" 2>/dev/null || true; }
_k04_inits="$(_k87_kit "$TMP/1804 kit sp")/toolbelt/init.sh"
# (a) fresh scaffold: the line is present exactly once, next to the existing patterns; typed report line.
d="$TMP/k04-a"; mkdir -p "$d"
bash "$_k04_inits" "$d" --corpus flat >"$TMP/k04-a.out" 2>&1
[ "$(_k04_cnt "$d/.gitignore")" = 1 ] && ok "K1804-a fresh scaffold ignores .research-sdd/plan/ exactly once" || no "K1804-a count=$(_k04_cnt "$d/.gitignore") ($(tr '\n' '|' < "$d/.gitignore"))"
assert_grep "K1804-a typed gitignore line" "gitignore: added .research-sdd/plan/" "$TMP/k04-a.out"
# (b) scaffold into a target whose .gitignore already carries an equivalent pattern: no duplicate, typed already-ignored.
d="$TMP/k04-b"; mkdir -p "$d"; printf 'node_modules/\n/.research-sdd/plan\n' > "$d/.gitignore"
bash "$_k04_inits" "$d" --corpus flat >"$TMP/k04-b.out" 2>&1
[ "$(_k04_cnt "$d/.gitignore")" = 0 ] && grep -qxF '/.research-sdd/plan' "$d/.gitignore" && ok "K1804-b scaffold respects an equivalent pattern (no second line)" || no "K1804-b gitignore: $(tr '\n' '|' < "$d/.gitignore")"
assert_grep "K1804-b typed already-ignored line" "gitignore: .research-sdd/plan/ already ignored" "$TMP/k04-b.out"
if command -v jq >/dev/null 2>&1; then
  # (c) --wire repair on an existing corpus whose .gitignore has no trailing newline: appended on its own line, user lines intact.
  d="$TMP/k04-c"; mkdir -p "$d"; : > "$d/INDEX.md"; printf 'node_modules/\n*.log' > "$d/.gitignore"
  bash "$_k04_inits" "$d" --wire >"$TMP/k04-c.out" 2>&1; _rc=$?
  [ "$_rc" = 0 ] && ok "K1804-c --wire repair exits 0" || no "K1804-c exit $_rc"
  [ "$(_k04_cnt "$d/.gitignore")" = 1 ] && grep -qxF '*.log' "$d/.gitignore" && grep -qxF 'node_modules/' "$d/.gitignore" \
    && ok "K1804-c --wire adds the line on its own row, user lines untouched" || no "K1804-c gitignore: $(tr '\n' '|' < "$d/.gitignore")"
  assert_grep "K1804-c typed gitignore line" "gitignore: added .research-sdd/plan/" "$TMP/k04-c.out"
  # (d) idempotent: a re-run is byte-identical and reports already ignored.
  cp "$d/.gitignore" "$TMP/k04-c.before"
  bash "$_k04_inits" "$d" --wire >"$TMP/k04-d.out" 2>&1
  cmp -s "$TMP/k04-c.before" "$d/.gitignore" && ok "K1804-d re-run leaves .gitignore byte-identical" || no "K1804-d .gitignore changed on a re-run"
  assert_grep "K1804-d typed already-ignored line" "gitignore: .research-sdd/plan/ already ignored" "$TMP/k04-d.out"
  # (e) no .gitignore at all: --wire creates one with just the line.
  d="$TMP/k04-e"; mkdir -p "$d"; : > "$d/INDEX.md"
  bash "$_k04_inits" "$d" --wire >/dev/null 2>&1
  [ "$(_k04_cnt "$d/.gitignore")" = 1 ] && ok "K1804-e --wire creates .gitignore with the plan line" || no "K1804-e no .gitignore line"
  # (f) equivalent spellings are respected (no append).
  for _pat in '/.research-sdd/plan/' '.research-sdd/plan' '.research-sdd/plan/*' '.research-sdd/plan/**'; do
    d="$TMP/k04-f"; rm -rf "$d"; mkdir -p "$d"; : > "$d/INDEX.md"; printf 'a\n%s\n' "$_pat" > "$d/.gitignore"; cp "$d/.gitignore" "$TMP/k04-f.before"
    bash "$_k04_inits" "$d" --wire >/dev/null 2>&1
    cmp -s "$TMP/k04-f.before" "$d/.gitignore" && ok "K1804-f equivalent pattern '$_pat' respected (file untouched)" || no "K1804-f '$_pat': .gitignore rewritten: $(tr '\n' '|' < "$d/.gitignore")"
  done
  # (g) a dangling-symlink .gitignore is a typed DEGRADED, never written through.
  d="$TMP/k04-g"; mkdir -p "$d"; : > "$d/INDEX.md"; ln -s "$d/nowhere" "$d/.gitignore"
  bash "$_k04_inits" "$d" --wire >"$TMP/k04-g.out" 2>&1; _rc=$?
  { [ "$_rc" = 0 ] && [ ! -e "$d/nowhere" ]; } && ok "K1804-g symlinked .gitignore not written through (exit 0)" || no "K1804-g rc=$_rc or wrote through the link"
  assert_grep "K1804-g typed DEGRADED" "gitignore: DEGRADED" "$TMP/k04-g.out"
  # (h) RDD: the LAST applicable rule wins (as in git). A negation AFTER the ignore re-includes the dir: typed NEGATED, never a false
  # "already ignored", nothing appended (propose-never-apply).
  d="$TMP/k04-h"; mkdir -p "$d"; : > "$d/INDEX.md"; printf 'a\n.research-sdd/plan/\n!.research-sdd/plan/\n' > "$d/.gitignore"; cp "$d/.gitignore" "$TMP/k04-h.before"
  bash "$_k04_inits" "$d" --wire >"$TMP/k04-h.out" 2>&1; _rc=$?
  { [ "$_rc" = 0 ] && cmp -s "$TMP/k04-h.before" "$d/.gitignore"; } && ok "K1804-h a later negation: exit 0 and .gitignore untouched" || no "K1804-h rc=$_rc or file changed"
  assert_grep "K1804-h typed NEGATED naming the line" "gitignore: NEGATED line 3" "$TMP/k04-h.out"
  if grep -qF 'already ignored' "$TMP/k04-h.out"; then no "K1804-h false 'already ignored' despite the negation"; else ok "K1804-h no false 'already ignored'"; fi
  # (i) negation BEFORE the ignore: the ignore wins -> already ignored, untouched.
  d="$TMP/k04-i"; mkdir -p "$d"; : > "$d/INDEX.md"; printf '!.research-sdd/plan/\n.research-sdd/plan/\n' > "$d/.gitignore"; cp "$d/.gitignore" "$TMP/k04-i.before"
  bash "$_k04_inits" "$d" --wire >"$TMP/k04-i.out" 2>&1
  cmp -s "$TMP/k04-i.before" "$d/.gitignore" && ok "K1804-i negation before the ignore: untouched" || no "K1804-i .gitignore changed"
  assert_grep "K1804-i typed already ignored (the ignore is last)" "gitignore: .research-sdd/plan/ already ignored" "$TMP/k04-i.out"
  # (j) a negation of what lives INSIDE the parent after the ignore re-includes the plan; a negation of the parent dir itself does not.
  for _neg in '!.research-sdd/*' '!/.research-sdd/**'; do
    d="$TMP/k04-j"; rm -rf "$d"; mkdir -p "$d"; : > "$d/INDEX.md"; printf '.research-sdd/plan/\n%s\n' "$_neg" > "$d/.gitignore"
    bash "$_k04_inits" "$d" --wire >"$TMP/k04-j.out" 2>&1
    assert_grep "K1804-j '$_neg' after the ignore: typed NEGATED" "gitignore: NEGATED line 2" "$TMP/k04-j.out"
  done
  for _neg in '!.research-sdd/' '!/.research-sdd' '!.research-sdd'; do
    d="$TMP/k04-j2"; rm -rf "$d"; mkdir -p "$d"; : > "$d/INDEX.md"; printf '.research-sdd/plan/\n%s\n' "$_neg" > "$d/.gitignore"; cp "$d/.gitignore" "$TMP/k04-j2.before"
    bash "$_k04_inits" "$d" --wire >"$TMP/k04-j2.out" 2>&1
    assert_grep "K1804-j2 '$_neg' (the dir itself) leaves the plan ignored: already ignored" "gitignore: .research-sdd/plan/ already ignored" "$TMP/k04-j2.out"
    cmp -s "$TMP/k04-j2.before" "$d/.gitignore" && ok "K1804-j2 '$_neg': .gitignore untouched" || no "K1804-j2 '$_neg': .gitignore changed"
  done
fi

# --- kit issue #1845: --subject / --prefix fill the hook; the guard names EVERY live placeholder -----------------------
_U7_SUBJ='<SUBJECT>'; _U7_PFX='<prefix>'; _U7_PATH='<path to binaries/decompiled output/source code of the system under study>'
_u7_live() {  # <file> <placeholder> — live (non-comment) occurrence?
  grep -qF -- "$2" <<<"$(grep -vE '^[[:space:]]*#' "$1")"
}
# run a filled hook and `jq -e` its output: valid SessionStart JSON whose context carries the literal subject on both lines
_u7_hook_json_ok() {  # <hook> <subject>
  bash "$1" </dev/null 2>/dev/null | jq -e --arg s "$2" '.hookSpecificOutput.hookEventName == "SessionStart"
    and (.hookSpecificOutput.additionalContext | contains("RESEARCH PROTOCOL — " + $s + " (Research-SDD)") and contains("research of " + $s + ". Before"))' >/dev/null 2>&1
}
_u7_ss_wired() { [ -f "$1/.claude/settings.json" ] && grep -qF 'research-protocol.sh' "$1/.claude/settings.json"; }
# a minimal custom hook with an exact set of live placeholders: $1 file, then any of S P X (subject / prefix / path)
_u7_hook() {
  local f="$1" k; shift; mkdir -p "$(dirname "$f")"
  { echo '#!/usr/bin/env bash'; echo '# header comment mentions <SUBJECT> and <prefix> — comments never count'
    echo 'CTX="'
    for k in "$@"; do case "$k" in S) echo 'research of <SUBJECT>';; P) echo '  - <prefix>-block*.md';; X) echo '  - <path to binaries/decompiled output/source code of the system under study>';; esac; done
    echo 'adapted line'; echo '"'; } > "$f"
}
_u7_wire_target() {  # <dir> then placeholder keys — an existing corpus + a hand-made hook
  local d="$1"; shift; rm -rf "$d"; mkdir -p "$d"; : > "$d/INDEX.md"; _u7_hook "$d/.claude/hooks/research-protocol.sh" "$@"
}

if command -v jq >/dev/null 2>&1; then
  echo "-- #1845: --subject / --prefix fill, guard names every live placeholder --"
  _u7_gen() {  # <name> — a kit copy whose templates/ dir is a private copy (so a variant hook template can be dropped in)
    local k="$TMP/u7g/$1"; rm -rf "$k"; mkdir -p "$k/toolbelt/lib"
    cp "$HERE/../lib/corpus-markers.sh" "$HERE/../lib/gh-visibility.sh" "$k/toolbelt/lib/"; cp -r "$HERE/../../templates" "$k/templates"
    cp "$SUT" "$k/toolbelt/init.sh"; chmod +x "$k/toolbelt/init.sh"
  }
  # A. scaffold fills both flags; the primary-sources placeholder (no flag) stays
  d="$TMP/u7-a"; mkdir -p "$d"
  bash "$SUT" "$d" --corpus flat --subject "Acme router firmware" --prefix acme >"$TMP/u7-a.out" 2>&1; _rc=$?
  [ "$_rc" = 0 ] && ok "U7-a scaffold --subject --prefix: exit 0" || no "U7-a scaffold --subject --prefix: exit $_rc"
  _h="$d/.claude/hooks/research-protocol.sh"
  grep -qxF 'RESEARCH PROTOCOL — Acme router firmware (Research-SDD)' "$_h" && ok "U7-a heading line filled" || no "U7-a heading line not filled"
  grep -qF 'READ-ONLY research of Acme router firmware. Before' "$_h" && ok "U7-a second <SUBJECT> line filled" || no "U7-a second <SUBJECT> line not filled"
  grep -qF -- '- acme-block*.md' "$_h" && ok "U7-a <prefix> filled by --prefix" || no "U7-a <prefix> not filled"
  _u7_live "$_h" "$_U7_SUBJ" && no "U7-a <SUBJECT> still live" || ok "U7-a no live <SUBJECT> left"
  _u7_live "$_h" "$_U7_PFX" && no "U7-a <prefix> still live" || ok "U7-a no live <prefix> left"
  _u7_live "$_h" "$_U7_PATH" && ok "U7-a primary-sources placeholder stays (no flag can fill it)" || no "U7-a primary-sources placeholder vanished"
  grep -qF 'Replace <SUBJECT> and the source/tool paths' "$_h" && ok "U7-a header comment untouched" || no "U7-a header comment was rewritten"

  # B. hostile subjects: / & \ | $ ` quotes, leading dash
  for _hs in 'a/b & c\d' 'x|y $HOME `id` "q" '"'s'" '-rf \1 \n'; do
    d="$TMP/u7-b"; rm -rf "$d"; mkdir -p "$d"
    bash "$SUT" "$d" --corpus flat --subject "$_hs" >"$TMP/u7-b.out" 2>&1; _rc=$?
    [ "$_rc" = 0 ] && ok "U7-b hostile subject [$_hs]: exit 0" || no "U7-b hostile subject [$_hs]: exit $_rc"
    grep -qxF "RESEARCH PROTOCOL — $_hs (Research-SDD)" "$d/.claude/hooks/research-protocol.sh" && ok "U7-b hostile subject rendered literally [$_hs]" || no "U7-b hostile subject mangled [$_hs]"
    grep -qF "READ-ONLY research of $_hs. Before" "$d/.claude/hooks/research-protocol.sh" && ok "U7-b hostile subject literal on the 2nd line [$_hs]" || no "U7-b 2nd line mangled [$_hs]"
    # the FILLED hook must EXECUTE and emit valid hook JSON carrying the literal subject on both lines
    _u7_hook_json_ok "$d/.claude/hooks/research-protocol.sh" "$_hs" && ok "U7-b filled hook executes: valid SessionStart JSON with the literal subject [$_hs]" || no "U7-b filled hook does not emit valid JSON with the literal subject [$_hs]"
  done

  # C. invalid values: exit 2, nothing written
  for _bad in "" "   " $'two\nlines' $'tab\there' $'cr\rhere' 'has <SUBJECT> in it' 'has <prefix> in it'; do
    d="$TMP/u7-c"; rm -rf "$d"; mkdir -p "$d"
    bash "$SUT" "$d" --corpus flat --subject "$_bad" >"$TMP/u7-c.out" 2>&1; _rc=$?
    { [ "$_rc" = 2 ] && grep -qF 'usage: --subject' "$TMP/u7-c.out" && ! grep -qF 'unknown flag' "$TMP/u7-c.out"; } && ok "U7-c bad subject [$(printf '%q' "$_bad")]: typed usage error, exit 2" || no "U7-c bad subject [$(printf '%q' "$_bad")]: exit $_rc, no typed usage line (want 2 + 'usage: --subject')"
    [ -z "$(find "$d" -mindepth 1 -print -quit)" ] && ok "U7-c bad subject [$(printf '%q' "$_bad")]: nothing written" || no "U7-c bad subject wrote into the target"
  done
  d="$TMP/u7-c"; rm -rf "$d"; mkdir -p "$d"
  bash "$SUT" "$d" --corpus flat --subject >/dev/null 2>&1; _rc=$?
  [ "$_rc" = 2 ] && ok "U7-c --subject as the last arg (no value): exit 2" || no "U7-c --subject without a value: exit $_rc"
  bash "$SUT" "$d" --corpus flat --prefix $'a\nb' >/dev/null 2>&1; _rc=$?
  [ "$_rc" = 2 ] && ok "U7-c multi-line --prefix: exit 2" || no "U7-c multi-line --prefix: exit $_rc"

  # D. guard enumerates every live placeholder — single / first / middle / last / combinations (--wire on an existing corpus)
  _u7_case() {  # <label> <want: letters S P X that must WARN, or -> <ss-wired yes|no> <hook keys...>
    local lbl="$1" want="$2" ssw="$3"; shift 3
    local d="$TMP/u7-d" rc k ph
    _u7_wire_target "$d" "$@"
    bash "$SUT" "$d" --wire >"$TMP/u7-d.out" 2>"$TMP/u7-d.err"; rc=$?
    [ "$rc" = 0 ] && ok "U7-d $lbl: exit 0" || no "U7-d $lbl: exit $rc"
    for k in S P X; do
      case "$k" in S) ph="$_U7_SUBJ";; P) ph="$_U7_PFX";; X) ph="$_U7_PATH";; esac
      if [[ "$want" == *"$k"* ]]; then grep -qF "still contains the $ph placeholder" <<<"$(grep -F 'WARN:' "$TMP/u7-d.err")" && ok "U7-d $lbl: WARN names $ph" || no "U7-d $lbl: no WARN naming $ph"
      else grep -qF "$ph placeholder" <<<"$(grep -F 'WARN:' "$TMP/u7-d.err")" && no "U7-d $lbl: false WARN naming $ph" || ok "U7-d $lbl: no WARN for absent $ph"; fi
    done
    if [ "$ssw" = yes ]; then _u7_ss_wired "$d" && ok "U7-d $lbl: SessionStart registered" || no "U7-d $lbl: SessionStart NOT registered"
    else _u7_ss_wired "$d" && no "U7-d $lbl: SessionStart registered despite a live <SUBJECT>" || ok "U7-d $lbl: SessionStart skipped"; fi
  }
  _u7_case "SUBJECT only (first, single)"  S   no  S
  _u7_case "prefix only (middle, single)"  P   yes P
  _u7_case "path only (last, single)"      X   yes X
  _u7_case "SUBJECT+prefix"                SP  no  S P
  _u7_case "prefix+path"                   PX  yes P X
  _u7_case "SUBJECT+path (not adjacent)"   SX  no  S X
  _u7_case "all three"                     SPX no  S P X
  _u7_case "fully adapted (none)"          -   yes
  # the path WARN names the exact next step; the non-gating WARN states it does not block
  _u7_wire_target "$TMP/u7-d" P X; bash "$SUT" "$TMP/u7-d" --wire >/dev/null 2>"$TMP/u7-d.err"
  grep -qF 'no flag can fill it: edit the hook and list the real primary-source paths' "$TMP/u7-d.err" && ok "U7-d path WARN carries the exact next step" || no "U7-d path WARN lacks the next step"
  grep -qF 'SessionStart wiring is NOT blocked' "$TMP/u7-d.err" && ok "U7-d non-gating WARN states it does not block SessionStart" || no "U7-d non-gating WARN does not say it is non-blocking"
  # a placeholder only inside a COMMENT line never warns (the _u7_hook header already carries two)
  _u7_wire_target "$TMP/u7-d"; bash "$SUT" "$TMP/u7-d" --wire >/dev/null 2>"$TMP/u7-d.err"
  grep -qF 'placeholder' "$TMP/u7-d.err" && no "U7-d comment-only placeholders produced a WARN" || ok "U7-d comment-only placeholders: no WARN (already-adapted hook)"
  # scaffold --scaffold --wire with both flags: the fillable placeholders are gone -> SessionStart registered; the path WARN remains
  d="$TMP/u7-sw"; mkdir -p "$d"
  bash "$SUT" "$d" --corpus flat --scaffold --wire --subject "Acme" --prefix ac >"$TMP/u7-sw.out" 2>"$TMP/u7-sw.err"; _rc=$?
  [ "$_rc" = 0 ] && ok "U7-d scaffold+wire with --subject: exit 0" || no "U7-d scaffold+wire with --subject: exit $_rc"
  _u7_ss_wired "$d" && ok "U7-d scaffold+wire with --subject: SessionStart registered" || no "U7-d scaffold+wire with --subject: SessionStart not registered"
  grep -qF "$_U7_PATH placeholder" <<<"$(grep -F 'WARN:' "$TMP/u7-sw.err")" && ok "U7-d scaffold+wire: path placeholder still WARNs" || no "U7-d scaffold+wire: no WARN for the path placeholder"
  d="$TMP/u7-sw2"; mkdir -p "$d"
  bash "$SUT" "$d" --corpus flat --scaffold --wire >"$TMP/u7-sw2.out" 2>"$TMP/u7-sw2.err"
  for _ph in "$_U7_SUBJ" "$_U7_PFX" "$_U7_PATH"; do grep -qF "$_ph" <<<"$(grep -F 'WARN:' "$TMP/u7-sw2.err")" && ok "U7-d scaffold+wire without flags: WARN names $_ph" || no "U7-d scaffold+wire without flags: no WARN naming $_ph"; done

  # E. existing hook: --subject/--prefix refuse (typed, nothing written) unless --force; an absent hook is created filled
  _u7_wire_target "$TMP/u7-e" S; cp "$TMP/u7-e/.claude/hooks/research-protocol.sh" "$TMP/u7-e.before"
  bash "$SUT" "$TMP/u7-e" --wire --subject "Acme" >"$TMP/u7-e.out" 2>"$TMP/u7-e.err"; _rc=$?
  [ "$_rc" = 3 ] && ok "U7-e --wire --subject on an existing hook: refused (exit 3)" || no "U7-e existing hook: exit $_rc (want 3)"
  grep -qF 'REFUSED: --subject only fills' "$TMP/u7-e.err" && ok "U7-e typed REFUSED line" || no "U7-e no typed REFUSED line"
  cmp -s "$TMP/u7-e.before" "$TMP/u7-e/.claude/hooks/research-protocol.sh" && ok "U7-e existing hook byte-identical" || no "U7-e existing hook was modified"
  { [ ! -e "$TMP/u7-e/.claude/settings.json" ] && [ ! -e "$TMP/u7-e/.claude/hooks/retro-gate-stop.sh" ]; } && ok "U7-e refusal wrote nothing else (no settings.json, no stop hook)" || no "U7-e refusal still wrote files"
  # --prefix is also the block-prefix flag operators re-pass on re-wires: an existing hook is left byte-identical, with a typed note, exit 0
  _u7_wire_target "$TMP/u7-e5" P X; bash "$SUT" "$TMP/u7-e5" --wire >/dev/null 2>&1   # first wire: already-wired target
  cp "$TMP/u7-e5/.claude/hooks/research-protocol.sh" "$TMP/u7-e5.before"
  bash "$SUT" "$TMP/u7-e5" --wire --prefix xx >"$TMP/u7-e5.out" 2>"$TMP/u7-e5.err"; _rc=$?
  [ "$_rc" = 0 ] && ok "U7-e re-wire --prefix on an already-wired target: exit 0" || no "U7-e re-wire --prefix: exit $_rc (want 0)"
  grep -qF "note: --prefix not applied to existing $TMP/u7-e5/.claude/hooks/research-protocol.sh (fill <prefix> by hand)" "$TMP/u7-e5.out" && ok "U7-e re-wire --prefix: typed note" || no "U7-e re-wire --prefix: no typed note"
  cmp -s "$TMP/u7-e5.before" "$TMP/u7-e5/.claude/hooks/research-protocol.sh" && ok "U7-e re-wire --prefix: hook byte-identical" || no "U7-e re-wire --prefix modified the hook"
  # a last-argument flag with no value is a typed usage error (exit 2), never a bare shift crash
  d="$TMP/u7-e6"; mkdir -p "$d"
  bash "$SUT" "$d" --corpus flat --prefix >"$TMP/u7-e6.out" 2>&1; _rc=$?
  { [ "$_rc" = 2 ] && grep -qF 'usage: --prefix needs a value' "$TMP/u7-e6.out"; } && ok "U7-e --prefix as the last argument: typed usage error, exit 2" || no "U7-e --prefix last arg: exit $_rc"
  # the fill rewrites through a same-dir temp file: mode and every non-placeholder byte survive, and no temp file is left behind
  _u7_gen mode; chmod 755 "$TMP/u7g/mode/templates/hook-sessionstart.sh"
  d="$TMP/u7-e7"; rm -rf "$d"; mkdir -p "$d"
  bash "$TMP/u7g/mode/toolbelt/init.sh" "$d" --corpus flat --subject "Acme" --prefix ac >/dev/null 2>&1; _rc=$?
  [ "$(_u7_mode "$d/.claude/hooks/research-protocol.sh")" = 755 ] && ok "U7-e fill preserves the template mode (755)" || no "U7-e fill changed the mode: $(_u7_mode "$d/.claude/hooks/research-protocol.sh")"
  [ "$(diff "$TMP/u7g/mode/templates/hook-sessionstart.sh" "$d/.claude/hooks/research-protocol.sh" | grep -c '^>')" = 3 ] && ok "U7-e fill changed exactly the 3 placeholder lines (every other byte preserved)" || no "U7-e fill touched other lines"
  [ -z "$(find "$d/.claude/hooks" -name '.hook.*')" ] && ok "U7-e fill left no temp file behind" || no "U7-e fill left a temp file"

  # H. a flag-looking value is never swallowed as the subject/prefix (`--subject --wire`): typed usage error, exit 2, nothing written
  for _fl in --subject --prefix; do
    d="$TMP/u7-h"; rm -rf "$d"; mkdir -p "$d"
    bash "$SUT" "$d" --corpus flat "$_fl" --wire >"$TMP/u7-h.out" 2>&1; _rc=$?
    { [ "$_rc" = 2 ] && grep -qF "usage: $_fl value '--wire' starts with --" "$TMP/u7-h.out"; } && ok "U7-h $_fl --wire: typed usage error, exit 2" || no "U7-h $_fl --wire: exit $_rc, no typed usage line"
    [ -z "$(find "$d" -mindepth 1 -print -quit)" ] && ok "U7-h $_fl --wire: nothing written" || no "U7-h $_fl --wire: wrote into the target"
  done

  # J. an existing hook with NO corpus marker: the scaffold and scaffold+wire paths follow the same rule as wire-only
  for _jf in "" "--scaffold --wire"; do
    d="$TMP/u7-j"; rm -rf "$d"; mkdir -p "$d"; _u7_hook "$d/.claude/hooks/research-protocol.sh" S; cp "$d/.claude/hooks/research-protocol.sh" "$TMP/u7-j.before"
    # shellcheck disable=SC2086
    bash "$SUT" "$d" --corpus flat $_jf --subject Acme >"$TMP/u7-j.out" 2>&1; _rc=$?
    { [ "$_rc" = 3 ] && grep -qF 'REFUSED: --subject only fills' "$TMP/u7-j.out"; } && ok "U7-j [$_jf] --subject on an existing hook, no corpus: REFUSED (exit 3)" || no "U7-j [$_jf] --subject: exit $_rc"
    cmp -s "$TMP/u7-j.before" "$d/.claude/hooks/research-protocol.sh" && ok "U7-j [$_jf] hook byte-identical" || no "U7-j [$_jf] hook overwritten"
    { [ ! -e "$d/INDEX.md" ] && [ ! -e "$d/retros" ] && [ ! -e "$d/.claude/settings.json" ]; } && ok "U7-j [$_jf] refusal wrote nothing" || no "U7-j [$_jf] refusal still scaffolded"
    rm -rf "$d"; mkdir -p "$d"; _u7_hook "$d/.claude/hooks/research-protocol.sh" S
    # shellcheck disable=SC2086
    bash "$SUT" "$d" --corpus flat $_jf --prefix pp >"$TMP/u7-j.out" 2>&1; _rc=$?
    { [ "$_rc" = 0 ] && grep -qF 'note: --prefix not applied to existing' "$TMP/u7-j.out" && [ -e "$d/INDEX.md" ]; } && ok "U7-j [$_jf] --prefix: note, corpus scaffolded (exit 0)" || no "U7-j [$_jf] --prefix: exit $_rc"
    cmp -s "$TMP/u7-j.before" "$d/.claude/hooks/research-protocol.sh" && ok "U7-j [$_jf] --prefix leaves the hook untouched" || no "U7-j [$_jf] --prefix overwrote the hook"
  done
  d="$TMP/u7-j"; rm -rf "$d"; mkdir -p "$d"; _u7_hook "$d/.claude/hooks/research-protocol.sh" S
  bash "$SUT" "$d" --corpus flat --force --subject Acme >/dev/null 2>&1; _rc=$?
  { [ "$_rc" = 0 ] && grep -qxF 'RESEARCH PROTOCOL — Acme (Research-SDD)' "$d/.claude/hooks/research-protocol.sh"; } && ok "U7-j --force re-scaffolds the existing hook and fills it" || no "U7-j --force: exit $_rc / not filled"

  # K. a failed wire-only fill writes NOTHING (staged first): no Stop hook, settings.json intact, nothing left in TMPDIR; TERM cleans up
  d="$TMP/u7-k"; rm -rf "$d"; mkdir -p "$d/.claude" "$d/td"; : > "$d/INDEX.md"; printf '{"keep":1}\n' > "$d/.claude/settings.json"; cp "$d/.claude/settings.json" "$TMP/u7-k.settings"
  _u7_stub="$TMP/u7-stub"; mkdir -p "$_u7_stub"; printf '#!/bin/sh\nexit 1\n' > "$_u7_stub/mv"; chmod +x "$_u7_stub/mv"
  TMPDIR="$d/td" PATH="$_u7_stub:$PATH" bash "$SUT" "$d" --wire --subject Acme >"$TMP/u7-k.out" 2>&1; _rc=$?
  [ "$_rc" = 2 ] && ok "U7-k wire-only fill failure: exit 2" || no "U7-k wire-only fill failure: exit $_rc"
  { [ ! -e "$d/.claude/hooks" ] && cmp -s "$TMP/u7-k.settings" "$d/.claude/settings.json"; } && ok "U7-k wire-only fill failure: no hooks dir created, settings.json intact" || no "U7-k wire-only fill failure left a half-wired state"
  [ -z "$(find "$d/td" -mindepth 1)" ] && ok "U7-k wire-only fill failure: staging dir and temp removed" || no "U7-k staging leftovers in TMPDIR"
  # TERM mid-fill: a sed stub stalls the fill's rewrite; the trap must remove the staging dir and exit 143
  _u7_slow="$TMP/u7-slow"; mkdir -p "$_u7_slow"; printf '#!/bin/sh\ncase "$2" in "/^[[:space:]]*#/!"*) sleep 3;; esac\nexec "%s" "$@"\n' "$(command -v sed)" > "$_u7_slow/sed"; chmod +x "$_u7_slow/sed"
  d="$TMP/u7-k2"; rm -rf "$d"; mkdir -p "$d/td"; : > "$d/INDEX.md"
  TMPDIR="$d/td" PATH="$_u7_slow:$PATH" bash "$SUT" "$d" --wire --subject Acme >/dev/null 2>&1 &
  _kp=$!; sleep 1; kill -TERM "$_kp" 2>/dev/null; wait "$_kp" 2>/dev/null; _rc=$?
  [ "$_rc" = 143 ] && ok "U7-k TERM mid-fill: exit 143" || no "U7-k TERM mid-fill: exit $_rc"
  [ -z "$(find "$d/td" -mindepth 1)" ] && [ ! -e "$d/.claude" ] && ok "U7-k TERM mid-fill: no staging/temp left, nothing written" || no "U7-k TERM mid-fill left files"

  # L. kit issue #1860 follow-ups (staging TMPDIR, no-clobber install, empty stage, success cleanup, flagless keep)
  # L1. an unusable TMPDIR fails closed: typed FATAL, exit 2, nothing written
  d="$TMP/u7-l1"; rm -rf "$d"; mkdir -p "$d/.claude"; : > "$d/INDEX.md"; printf '{"keep":1}\n' > "$d/.claude/settings.json"; cp "$d/.claude/settings.json" "$TMP/u7-l1.settings"
  TMPDIR="$d/no-such-tmpdir" bash "$SUT" "$d" --wire >"$TMP/u7-l1.out" 2>&1; _rc=$?
  { [ "$_rc" = 2 ] && grep -qF 'FATAL: could not create a staging directory' "$TMP/u7-l1.out"; } && ok "U7-l1 unusable TMPDIR: typed FATAL, exit 2" || no "U7-l1 unusable TMPDIR: exit $_rc, no typed FATAL"
  { [ ! -e "$d/.claude/hooks" ] && cmp -s "$TMP/u7-l1.settings" "$d/.claude/settings.json"; } && ok "U7-l1 unusable TMPDIR: nothing written" || no "U7-l1 unusable TMPDIR left a half-wired state"
  # L2. a hook created AFTER the existence check is kept, never overwritten (the cp stub plants it at the install moment)
  _u7_race="$TMP/u7-race"; mkdir -p "$_u7_race"
  printf '#!/bin/sh\n[ "$1" = -p ] && { a1="$2"; a2="$3"; } || { a1="$1"; a2="$2"; }\ncase "$a1" in */hook) d="$(dirname "$a2")"; case "$a2" in */.claude/hooks/*) [ -e "$d/research-protocol.sh" ] || printf "HAND-ADAPTED\\n" > "$d/research-protocol.sh";; esac;; esac\nexec "%s" "$@"\n' "$(command -v cp)" > "$_u7_race/cp"; chmod +x "$_u7_race/cp"
  d="$TMP/u7-l2"; rm -rf "$d"; mkdir -p "$d"; : > "$d/INDEX.md"
  PATH="$_u7_race:$PATH" bash "$SUT" "$d" --wire >"$TMP/u7-l2.out" 2>&1; _rc=$?
  [ "$_rc" = 0 ] && ok "U7-l2 hook appearing after the check: exit 0" || no "U7-l2 race: exit $_rc"
  [ "$(cat "$d/.claude/hooks/research-protocol.sh" 2>/dev/null)" = "HAND-ADAPTED" ] && ok "U7-l2 hook appearing after the check: NOT overwritten" || no "U7-l2 race: the concurrently-created hook was overwritten"
  { grep -qF "kept: $d/.claude/hooks/research-protocol.sh" "$TMP/u7-l2.out" && ! grep -qF "created: $d/.claude/hooks/research-protocol.sh" "$TMP/u7-l2.out"; } && ok "U7-l2 race: reported kept, not created" || no "U7-l2 race: wrong created/kept report"
  [ -z "$(find "$d/.claude" -name '.hook.*')" ] && ok "U7-l2 race: no temp file left" || no "U7-l2 race left a temp file"
  # L3. the hook existed at staging time (nothing staged) and vanishes before the install: staged late, never `cp` from an empty path
  _u7_gone="$TMP/u7-gone"; mkdir -p "$_u7_gone"
  printf '#!/bin/sh\ncase "$1" in */hook-stop-retro-gate.sh) rm -f "$(dirname "$2")/research-protocol.sh";; esac\nexec "%s" "$@"\n' "$(command -v cp)" > "$_u7_gone/cp"; chmod +x "$_u7_gone/cp"
  _u7_wire_target "$TMP/u7-l3" S
  PATH="$_u7_gone:$PATH" bash "$SUT" "$TMP/u7-l3" --wire >"$TMP/u7-l3.out" 2>&1; _rc=$?
  { [ "$_rc" = 0 ] && [ -s "$TMP/u7-l3/.claude/hooks/research-protocol.sh" ] && grep -qF "created: $TMP/u7-l3/.claude/hooks/research-protocol.sh" "$TMP/u7-l3.out"; } && ok "U7-l3 hook vanishing after an exists-at-start check: re-staged and created, exit 0" || no "U7-l3 vanished hook: exit $_rc ($(grep -F 'cp:' "$TMP/u7-l3.out" | head -1))"
  # L4. the staging dir is removed on the success path BEFORE the end of the run (a jq stub logs TMPDIR at every call; the last one must be empty)
  _u7_tl="$TMP/u7-tl"; mkdir -p "$_u7_tl"
  printf '#!/bin/sh\nfind "$TMPDIR" -mindepth 1 > "$TMPDIR/../u7-tl.last" 2>/dev/null\nexec "%s" "$@"\n' "$(command -v jq)" > "$_u7_tl/jq"; chmod +x "$_u7_tl/jq"
  d="$TMP/u7-l4"; rm -rf "$d"; mkdir -p "$d/td"; : > "$d/INDEX.md"; rm -f "$d/u7-tl.last"
  TMPDIR="$d/td" PATH="$_u7_tl:$PATH" bash "$SUT" "$d" --wire >/dev/null 2>&1; _rc=$?
  { [ "$_rc" = 0 ] && [ -f "$d/u7-tl.last" ] && [ ! -s "$d/u7-tl.last" ]; } && ok "U7-l4 success path: staging dir already gone when the settings merge runs" || no "U7-l4 staging dir still present after the install (rc $_rc): $(head -2 "$d/u7-tl.last" 2>/dev/null | tr '\n' ' ')"
  # L6. a flagless scaffold over an existing hook (no corpus marker) keeps the hook, byte for byte
  d="$TMP/u7-l6"; rm -rf "$d"; mkdir -p "$d"; _u7_hook "$d/.claude/hooks/research-protocol.sh" S; cp "$d/.claude/hooks/research-protocol.sh" "$TMP/u7-l6.before"
  bash "$SUT" "$d" --corpus flat >"$TMP/u7-l6.out" 2>&1; _rc=$?
  { [ "$_rc" = 0 ] && [ -e "$d/INDEX.md" ]; } && ok "U7-l6 flagless scaffold over an existing hook: scaffold completes" || no "U7-l6 flagless scaffold: exit $_rc"
  cmp -s "$TMP/u7-l6.before" "$d/.claude/hooks/research-protocol.sh" && ok "U7-l6 flagless scaffold: existing hook byte-identical" || no "U7-l6 flagless scaffold OVERWROTE the existing hook"
  grep -qF "kept: $d/.claude/hooks/research-protocol.sh" "$TMP/u7-l6.out" && ok "U7-l6 flagless scaffold: typed 'kept:' line" || no "U7-l6 flagless scaffold: no kept: line"

  # I. failure paths of the fill: a failing mv (stubbed) is a typed FATAL with no temp file and no half-filled hook
  _u7_stub="$TMP/u7-stub"; mkdir -p "$_u7_stub"; printf '#!/bin/sh\nexit 1\n' > "$_u7_stub/mv"; chmod +x "$_u7_stub/mv"
  d="$TMP/u7-i"; rm -rf "$d"; mkdir -p "$d"
  PATH="$_u7_stub:$PATH" bash "$SUT" "$d" --corpus flat --subject Acme >"$TMP/u7-i.out" 2>&1; _rc=$?
  { [ "$_rc" != 0 ] && grep -qF 'FATAL: could not install the filled hook' "$TMP/u7-i.out"; } && ok "U7-i scaffold, mv fails: typed FATAL, non-zero (exit $_rc)" || no "U7-i scaffold, mv fails: exit $_rc, no typed FATAL"
  { [ ! -e "$d/.claude" ] && [ -z "$(find "$d" -name '.hook.*')" ]; } && ok "U7-i scaffold, mv fails: rolled back, no temp file" || no "U7-i scaffold, mv fails: left files behind"
  d="$TMP/u7-i2"; rm -rf "$d"; mkdir -p "$d"; : > "$d/INDEX.md"
  PATH="$_u7_stub:$PATH" bash "$SUT" "$d" --wire --subject Acme >"$TMP/u7-i2.out" 2>&1; _rc=$?
  { [ "$_rc" = 2 ] && grep -qF 'FATAL: could not install the filled hook' "$TMP/u7-i2.out"; } && ok "U7-i wire-only, mv fails: typed FATAL, exit 2" || no "U7-i wire-only, mv fails: exit $_rc"
  { [ ! -e "$d/.claude/hooks/research-protocol.sh" ] && [ -z "$(find "$d/.claude" -name '.hook.*' 2>/dev/null)" ]; } && ok "U7-i wire-only, mv fails: no hook, no temp file" || no "U7-i wire-only, mv fails: hook or temp file left"
  # one flag fillable and one not (template without <prefix>): nothing is half-filled
  _u7_gen nopfx; printf '%s\n' '#!/usr/bin/env bash' 'echo "research of <SUBJECT>"' > "$TMP/u7g/nopfx/templates/hook-sessionstart.sh"
  d="$TMP/u7-i3"; rm -rf "$d"; mkdir -p "$d"; : > "$d/INDEX.md"
  bash "$TMP/u7g/nopfx/toolbelt/init.sh" "$d" --wire --subject Acme --prefix pp >"$TMP/u7-i3.out" 2>&1; _rc=$?
  { [ "$_rc" = 2 ] && grep -qF 'carries no live <prefix> placeholder' "$TMP/u7-i3.out"; } && ok "U7-i template lacking <prefix>: typed FATAL, exit 2" || no "U7-i template lacking <prefix>: exit $_rc"
  { [ ! -e "$d/.claude/hooks/research-protocol.sh" ] && [ -z "$(find "$d/.claude" -name '.hook.*' 2>/dev/null)" ]; } && ok "U7-i template lacking <prefix>: no half-filled hook, no temp file" || no "U7-i template lacking <prefix>: partial hook or temp left"
  # an ADAPTED existing hook is refused the same way (never an overwrite)
  _u7_wire_target "$TMP/u7-e2"; cp "$TMP/u7-e2/.claude/hooks/research-protocol.sh" "$TMP/u7-e2.before"
  bash "$SUT" "$TMP/u7-e2" --wire --subject "Acme" >/dev/null 2>&1; _rc=$?
  { [ "$_rc" = 3 ] && cmp -s "$TMP/u7-e2.before" "$TMP/u7-e2/.claude/hooks/research-protocol.sh"; } && ok "U7-e adapted hook + --subject: refused, bytes intact" || no "U7-e adapted hook: exit $_rc or bytes changed"
  # --force follows the script's --force semantics: re-scaffold, and the fresh hook is filled
  bash "$SUT" "$TMP/u7-e" --corpus flat --wire --force --subject "Acme" --prefix ac >"$TMP/u7-e3.out" 2>&1; _rc=$?
  [ "$_rc" = 0 ] && ok "U7-e --force --subject: exit 0" || no "U7-e --force --subject: exit $_rc"
  grep -qxF 'RESEARCH PROTOCOL — Acme (Research-SDD)' "$TMP/u7-e/.claude/hooks/research-protocol.sh" && ok "U7-e --force: hook re-created filled" || no "U7-e --force: hook not filled"
  # an absent hook on the wire-only path: created and filled, SessionStart registered
  d="$TMP/u7-e4"; mkdir -p "$d"; : > "$d/INDEX.md"
  bash "$SUT" "$d" --wire --subject "Acme" --prefix ac >/dev/null 2>"$TMP/u7-e4.err"; _rc=$?
  { [ "$_rc" = 0 ] && grep -qxF 'RESEARCH PROTOCOL — Acme (Research-SDD)' "$d/.claude/hooks/research-protocol.sh"; } && ok "U7-e wire-only creating the hook: filled" || no "U7-e wire-only creating the hook: exit $_rc / not filled"
  _u7_ss_wired "$d" && ok "U7-e wire-only creating a filled hook: SessionStart registered" || no "U7-e SessionStart not registered after a filled create"

  # F. template-generation variants: placeholders on other lines / in another order; no line-number coupling
  _u7_gen old
  { for _i in 1 2 3 4 5 6 7; do echo "# padding line $_i"; done
    echo "# SessionStart hook — Research-SDD protocol for <SUBJECT>."
    echo "CTX='"; echo '  - <path to binaries/decompiled output/source code of the system under study>'
    echo 'first <prefix>-block*.md then <SUBJECT>'; echo 'again <SUBJECT> end'; echo "'"; } > "$TMP/u7g/old/templates/hook-sessionstart.sh"
  d="$TMP/u7-f"; rm -rf "$d"; mkdir -p "$d"
  bash "$TMP/u7g/old/toolbelt/init.sh" "$d" --corpus flat --subject "S&1" --prefix pp --scaffold --wire >"$TMP/u7-f.out" 2>"$TMP/u7-f.err"; _rc=$?
  _h="$d/.claude/hooks/research-protocol.sh"
  [ "$_rc" = 0 ] && ok "U7-f other template generation: exit 0" || no "U7-f other template generation: exit $_rc"
  { grep -qxF 'first pp-block*.md then S&1' "$_h" && grep -qxF 'again S&1 end' "$_h"; } && ok "U7-f placeholders filled wherever they sit (order/lines differ)" || no "U7-f other-generation fill wrong"
  grep -qF '# SessionStart hook — Research-SDD protocol for <SUBJECT>.' "$_h" && ok "U7-f comment line untouched" || no "U7-f comment line rewritten"
  grep -qF "$_U7_PATH placeholder" <<<"$(grep -F 'WARN:' "$TMP/u7-f.err")" && ok "U7-f other generation: path placeholder WARNs" || no "U7-f other generation: no path WARN"
  # a template with NO live <SUBJECT> and --subject given: typed failure, never a silent no-op
  _u7_gen nosubj; printf '%s\n' '#!/usr/bin/env bash' 'echo adapted' > "$TMP/u7g/nosubj/templates/hook-sessionstart.sh"
  d="$TMP/u7-f2"; rm -rf "$d"; mkdir -p "$d"
  bash "$TMP/u7g/nosubj/toolbelt/init.sh" "$d" --corpus flat --subject "Acme" >"$TMP/u7-f2.out" 2>&1; _rc=$?
  { [ "$_rc" != 0 ] && grep -qF 'carries no live <SUBJECT> placeholder' "$TMP/u7-f2.out"; } && ok "U7-f template without <SUBJECT> + --subject: typed FATAL, non-zero" || no "U7-f template without <SUBJECT>: exit $_rc, silent no-op"
  [ ! -e "$d/.claude" ] && ok "U7-f typed FATAL rolled the scaffold back" || no "U7-f scaffold left behind after the FATAL"
  # G. jq ABSENT (print-only fallback): the other live placeholders are still named; --subject on an absent hook says NOT applied
  _u7_pnojq="$(_u7_nojq_path)"
  if PATH="$_u7_pnojq" command -v jq >/dev/null 2>&1; then
    echo "  SKIP  U7-g: jq still reachable on the private tool PATH"
  else
    _u7_wire_target "$TMP/u7-g" P X
    PATH="$_u7_pnojq" bash "$SUT" "$TMP/u7-g" --wire >"$TMP/u7-g.out" 2>"$TMP/u7-g.err"; _rc=$?
    [ "$_rc" = 0 ] && ok "U7-g jq-absent: exit 0" || no "U7-g jq-absent: exit $_rc"
    for _ph in "$_U7_PFX" "$_U7_PATH"; do grep -qF "still contains the $_ph placeholder" <<<"$(grep -F 'WARN:' "$TMP/u7-g.err")" && ok "U7-g jq-absent: WARN names $_ph" || no "U7-g jq-absent: no WARN naming $_ph"; done
    d="$TMP/u7-g2"; mkdir -p "$d"; : > "$d/INDEX.md"
    PATH="$_u7_pnojq" bash "$SUT" "$d" --wire --subject Acme >"$TMP/u7-g2.out" 2>"$TMP/u7-g2.err"; _rc=$?
    grep -qF -- '--subject/--prefix NOT applied' "$TMP/u7-g2.err" && ok "U7-g jq-absent + --subject on an absent hook: typed NOT applied" || no "U7-g jq-absent: --subject silently dropped"
    [ ! -e "$d/.claude" ] && ok "U7-g jq-absent: nothing written" || no "U7-g jq-absent wrote files"
  fi
  # the shared list is declared exactly once in the SUT
  [ "$(grep -c "^_RSDD_HOOK_PLACEHOLDERS=" "$SUT")" = 1 ] && ok "U7 shared placeholder list declared exactly once" || no "U7 placeholder list not declared exactly once"
fi

# NEGATIVE CONTROL — prove the corpus-present guard has TEETH.
if [ "${1:-}" = "--prove-teeth" ]; then
  echo "-- teeth proof: neuter the corpus-present guard, expect the data-loss fixture to CLOBBER --"
  mkdir -p "$TMP/mk/toolbelt/lib"; ln -sfn "$HERE/../../templates" "$TMP/mk/templates"
  # kit issue #1108 round 2 (RDD finding): corpus_present() in research-sdd-init.sh is now a
  # one-line wrapper delegating to corpus_has_marker() in lib/corpus-markers.sh — mutating the
  # WRAPPER only proves the refuse tests depend on corpus_present()'s return value (already true
  # before the refactor); it says nothing about whether research-sdd-init.sh actually WIRES to
  # the shared lib. Mutate the LIB instead and run research-sdd-init.sh UNMODIFIED (straight
  # copy, no awk transform) against it — this proves both the guard's load-bearing-ness AND the
  # real delegation chain (wrapper → lib), the thing this refactor actually changed.
  mutant="$TMP/mk/toolbelt/init.sh"
  cp "$SUT" "$mutant"; chmod +x "$mutant"
  if ! grep -qE '^      return 0$' "$HERE/../lib/corpus-markers.sh"; then
    no "teeth: could not build mutant (RESEARCH-STATE branch 'return 0' anchor not found in lib)"
  else
    sed '0,/^      return 0$/{s/^      return 0$/      return 1  # MUTANT: guard neutered/}' \
      "$HERE/../lib/corpus-markers.sh" > "$TMP/mk/toolbelt/lib/corpus-markers.sh"
    if ! grep -qF 'MUTANT: guard neutered' "$TMP/mk/toolbelt/lib/corpus-markers.sh"; then
      no "teeth: could not build mutant (guard line not found)"
    else
      d="$TMP/teeth"; mkdir -p "$d"; printf 'REAL HAND-CURATED GAPS\n' > "$d/RESEARCH-STATE.md"
      bash "$mutant" "$d" --corpus flat >/dev/null 2>&1; mg=$?
      if [ "$mg" = 0 ] && ! grep -qF 'REAL HAND-CURATED GAPS' "$d/RESEARCH-STATE.md"; then
        ok "teeth: mutant clobbers curated state (exit 0, gone) → refuse tests have teeth (real lib wiring)"
      else
        no "teeth: mutant exit $mg / data present — refuse tests do NOT depend on the guard (THEATER)"
      fi
    fi
  fi

  # Mutation 2: neuter tools-README seeding — prove tools-scaffold assertions have teeth
  echo "-- teeth proof: omit tools-README cpf, expect README to be absent --"
  mkdir -p "$TMP/tt/toolbelt/lib"; cp "$HERE/../lib/corpus-markers.sh" "$TMP/tt/toolbelt/lib/"; cp "$HERE/../lib/gh-visibility.sh" "$TMP/tt/toolbelt/lib/"; ln -sfn "$HERE/../../templates" "$TMP/tt/templates"
  tt_mutant="$TMP/tt/toolbelt/init.sh"
  awk '/cpf.*tools-README\.template\.md/ { next } { print }' "$SUT" > "$tt_mutant"
  if ! grep -qE 'cpf.*tools-README' "$SUT" || grep -qE 'cpf.*tools-README' "$tt_mutant"; then
    no "teeth: could not build tools-scaffold mutant (cpf line not found or not removed)"
  else
    dt="$TMP/tth"; mkdir -p "$dt"
    bash "$tt_mutant" "$dt" --corpus flat >/dev/null 2>&1
    if [ ! -f "$dt/tools/README.md" ]; then
      ok "teeth: mutant skipped tools/README.md → tools-scaffold tests have teeth"
    else
      no "teeth: mutant still produced tools/README.md — tools-scaffold tests are THEATER"
    fi
  fi

  # Mutation M1: strip (PROMPT-LOOP §b) from step-1 → §b) absent in stdout
  echo "-- teeth proof M1: strip (PROMPT-LOOP §b) from step-1 echo → §b) absent --"
  mkdir -p "$TMP/m1/toolbelt/lib"; cp "$HERE/../lib/corpus-markers.sh" "$TMP/m1/toolbelt/lib/"; cp "$HERE/../lib/gh-visibility.sh" "$TMP/m1/toolbelt/lib/"; ln -sfn "$HERE/../../templates" "$TMP/m1/templates"
  m1_mutant="$TMP/m1/toolbelt/init.sh"
  awk '/\(PROMPT-LOOP §b\)/ { sub(/\(PROMPT-LOOP §b\)/, ""); } { print }' "$SUT" > "$m1_mutant"
  if grep -qF '(PROMPT-LOOP §b)' "$m1_mutant"; then
    no "teeth M1: could not build mutant ((PROMPT-LOOP §b) still present after strip)"
  else
    dm1="$TMP/m1t"; mkdir -p "$dm1"
    bash "$m1_mutant" "$dm1" --corpus flat > "$TMP/m1.out" 2>/dev/null
    if ! grep -qF "§b)" "$TMP/m1.out" 2>/dev/null; then
      ok "teeth M1: §b) absent after strip — step-1 cross-ref assertion has teeth"
    else
      no "teeth M1: §b) still present in mutant output — THEATER"
    fi
  fi

  # Mutation M2: always-print step-5 (remove prefix guard) → no-prefix ABSENT assertion flips red
  echo "-- teeth proof M2: remove prefix-if guard → step-5 appears in no-prefix run --"
  mkdir -p "$TMP/m2/toolbelt/lib"; cp "$HERE/../lib/corpus-markers.sh" "$TMP/m2/toolbelt/lib/"; cp "$HERE/../lib/gh-visibility.sh" "$TMP/m2/toolbelt/lib/"; ln -sfn "$HERE/../../templates" "$TMP/m2/templates"
  m2_mutant="$TMP/m2/toolbelt/init.sh"
  awk '/if \[ -n "\$prefix" \]/ { print "if true; then  # MUTANT: always print step 5"; next } { print }' "$SUT" > "$m2_mutant"
  if ! grep -q 'MUTANT: always print step 5' "$m2_mutant"; then
    no "teeth M2: could not build mutant (prefix-if line not found)"
  else
    dm2="$TMP/m2t"; mkdir -p "$dm2"
    bash "$m2_mutant" "$dm2" --corpus flat > "$TMP/m2.out" 2>/dev/null
    if grep -qF "5. Block files use the prefix:" "$TMP/m2.out" 2>/dev/null; then
      ok "teeth M2: step-5 present in no-prefix mutant run — absent assertion has teeth"
    else
      no "teeth M2: step-5 NOT present in mutant run — absent assertion is THEATER"
    fi
  fi

  # Mutation M3: remove gitignored split line → gitignored/--force absent from already-git output
  echo "-- teeth proof M3: remove gitignored line → gitignored/--force absent --"
  mkdir -p "$TMP/m3/toolbelt/lib"; cp "$HERE/../lib/corpus-markers.sh" "$TMP/m3/toolbelt/lib/"; cp "$HERE/../lib/gh-visibility.sh" "$TMP/m3/toolbelt/lib/"; ln -sfn "$HERE/../../templates" "$TMP/m3/templates"
  m3_mutant="$TMP/m3/toolbelt/init.sh"
  awk '/\.claude\/ hook is gitignored/ { next } { print }' "$SUT" > "$m3_mutant"
  if grep -qF '.claude/ hook is gitignored' "$m3_mutant"; then
    no "teeth M3: could not build mutant (gitignored line not removed)"
  else
    if ! command -v git >/dev/null 2>&1; then
      echo "  SKIP  teeth M3: git not on PATH"
    else
      dm3="$TMP/m3t"; mkdir -p "$dm3"; git -C "$dm3" init -q 2>/dev/null
      bash "$m3_mutant" "$dm3" --corpus flat > "$TMP/m3.out" 2>/dev/null
      if ! grep -qF "gitignored" "$TMP/m3.out" 2>/dev/null && ! grep -qF "git add --force" "$TMP/m3.out" 2>/dev/null; then
        ok "teeth M3: gitignored/--force absent in mutant output — already-git assertions have teeth"
      else
        no "teeth M3: gitignored or --force still present in mutant output — THEATER"
      fi
    fi
  fi

  # Mutation M4: delete NEXT echo line → research-sdd-status.sh absent from stdout
  echo "-- teeth proof M4: delete NEXT echo → research-sdd-status.sh absent --"
  mkdir -p "$TMP/m4/toolbelt/lib"; cp "$HERE/../lib/corpus-markers.sh" "$TMP/m4/toolbelt/lib/"; cp "$HERE/../lib/gh-visibility.sh" "$TMP/m4/toolbelt/lib/"; ln -sfn "$HERE/../../templates" "$TMP/m4/templates"
  m4_mutant="$TMP/m4/toolbelt/init.sh"
  awk '/NEXT: run.*research-sdd-status\.sh/ { next } { print }' "$SUT" > "$m4_mutant"
  if grep -qF 'NEXT: run' "$m4_mutant"; then
    no "teeth M4: could not build mutant (NEXT echo line not removed)"
  else
    dm4="$TMP/m4t"; mkdir -p "$dm4"
    bash "$m4_mutant" "$dm4" --corpus flat > "$TMP/m4.out" 2>/dev/null
    if ! grep -qF "research-sdd-status.sh" "$TMP/m4.out" 2>/dev/null; then
      ok "teeth M4: research-sdd-status.sh absent in mutant output — next-step assertion has teeth"
    else
      no "teeth M4: research-sdd-status.sh still present in mutant output — THEATER"
    fi
  fi

  # Mutation M5: delete CONFIRM group header → CONFIRM these are done absent from stdout
  echo "-- teeth proof M5: delete CONFIRM group header → CONFIRM these are done absent --"
  mkdir -p "$TMP/m5/toolbelt/lib"; cp "$HERE/../lib/corpus-markers.sh" "$TMP/m5/toolbelt/lib/"; cp "$HERE/../lib/gh-visibility.sh" "$TMP/m5/toolbelt/lib/"; ln -sfn "$HERE/../../templates" "$TMP/m5/templates"
  m5_mutant="$TMP/m5/toolbelt/init.sh"
  awk '/CONFIRM these are done/ { next } { print }' "$SUT" > "$m5_mutant"
  if grep -qF 'CONFIRM these are done' "$m5_mutant"; then
    no "teeth M5: could not build mutant (CONFIRM header line not removed)"
  else
    dm5="$TMP/m5t"; mkdir -p "$dm5"
    bash "$m5_mutant" "$dm5" --corpus flat > "$TMP/m5.out" 2>/dev/null
    if ! grep -qF "CONFIRM these are done" "$TMP/m5.out" 2>/dev/null; then
      ok "teeth M5: CONFIRM header absent in mutant output — CONFIRM assertion has teeth"
    else
      no "teeth M5: CONFIRM header still present in mutant output — THEATER"
    fi
  fi

  # Mutation M6: delete THEN group header → THEN do next (post-scaffold) absent from stdout
  echo "-- teeth proof M6: delete THEN group header → THEN do next (post-scaffold) absent --"
  mkdir -p "$TMP/m6/toolbelt/lib"; cp "$HERE/../lib/corpus-markers.sh" "$TMP/m6/toolbelt/lib/"; cp "$HERE/../lib/gh-visibility.sh" "$TMP/m6/toolbelt/lib/"; ln -sfn "$HERE/../../templates" "$TMP/m6/templates"
  m6_mutant="$TMP/m6/toolbelt/init.sh"
  awk '/THEN do next \(post-scaffold\)/ { next } { print }' "$SUT" > "$m6_mutant"
  if grep -qF 'THEN do next (post-scaffold)' "$m6_mutant"; then
    no "teeth M6: could not build mutant (THEN header line not removed)"
  else
    dm6="$TMP/m6t"; mkdir -p "$dm6"
    bash "$m6_mutant" "$dm6" --corpus flat > "$TMP/m6.out" 2>/dev/null
    if ! grep -qF "THEN do next (post-scaffold)" "$TMP/m6.out" 2>/dev/null; then
      ok "teeth M6: THEN header absent in mutant output — THEN assertion has teeth"
    else
      no "teeth M6: THEN header still present in mutant output — THEATER"
    fi
  fi

  # Mutation M7: move CONFIRM marker down after item-2 (forward-safe reorder: destination AFTER source)
  # → CONFIRM appears AFTER item-1 in output, breaking CONFIRM<item1 while keeping both markers present.
  # This isolates ORDER, not presence — proving the ordering assertion has teeth.
  echo "-- teeth proof M7: move CONFIRM after item-2 → CONFIRM>item1 in output, ordering assertion has teeth --"
  mkdir -p "$TMP/m7/toolbelt/lib"; cp "$HERE/../lib/corpus-markers.sh" "$TMP/m7/toolbelt/lib/"; cp "$HERE/../lib/gh-visibility.sh" "$TMP/m7/toolbelt/lib/"; ln -sfn "$HERE/../../templates" "$TMP/m7/templates"
  m7_mutant="$TMP/m7/toolbelt/init.sh"
  awk '/CONFIRM these are done/ { cf=$0; next } /2\. CLASSIFY the artifact/ { print; if (cf!="") { print cf; cf="" } next } { print }' "$SUT" > "$m7_mutant"
  # Build-check: CONFIRM must be PRESENT and AFTER item-2 in the mutant file (not a silent delete)
  if ! grep -qF 'CONFIRM these are done' "$m7_mutant"; then
    no "teeth M7: could not build reorder mutant (CONFIRM these are done absent — degraded to delete)"
  else
    m7_cf_line=$(grep -nF "CONFIRM these are done"  "$m7_mutant" | head -1 | cut -d: -f1)
    m7_i2_line=$(grep -nF "2. CLASSIFY the artifact" "$m7_mutant" | head -1 | cut -d: -f1)
    if [ -n "$m7_cf_line" ] && [ -n "$m7_i2_line" ] && [ "$m7_cf_line" -gt "$m7_i2_line" ]; then
      ok "teeth M7: mutant has CONFIRM after item-2 in script (CONFIRM=$m7_cf_line item2=$m7_i2_line) — not a delete"
      dm7="$TMP/m7t"; mkdir -p "$dm7"
      bash "$m7_mutant" "$dm7" --corpus flat > "$TMP/m7.out" 2>/dev/null
      m7_out_cf=$(grep -nF "CONFIRM these are done"     "$TMP/m7.out" | head -1 | cut -d: -f1)
      m7_out_i1=$(grep -nF "1. REGISTER the target row" "$TMP/m7.out" | head -1 | cut -d: -f1)
      if [ -n "$m7_out_cf" ] && [ -n "$m7_out_i1" ] && [ "$m7_out_cf" -gt "$m7_out_i1" ]; then
        ok "teeth M7: CONFIRM now after item-1 in mutant output — ordering assertion has teeth"
      else
        no "teeth M7: ordering not broken in mutant output (CONFIRM=$m7_out_cf item1=$m7_out_i1) — THEATER"
      fi
    else
      no "teeth M7: could not verify reorder — CONFIRM not after item-2 (CONFIRM=$m7_cf_line item2=$m7_i2_line)"
    fi
  fi

  # MW1: skip the atomic mv in --wire path → settings.json absent → (a-wire) RED
  echo "-- teeth proof MW1: skip jq mv in --wire path → settings.json absent, wire test has teeth --"
  if ! command -v jq >/dev/null 2>&1; then
    echo "  SKIP  teeth MW1: jq not on PATH"
  else
    mkdir -p "$TMP/mw1/toolbelt/lib"; cp "$HERE/../lib/corpus-markers.sh" "$TMP/mw1/toolbelt/lib/"; cp "$HERE/../lib/gh-visibility.sh" "$TMP/mw1/toolbelt/lib/"; ln -sfn "$HERE/../../templates" "$TMP/mw1/templates"
    mw1="$TMP/mw1/toolbelt/init.sh"
    awk '/_rsdd_install_settings "\$_tmp_settings" "\$_settings"/ { next } { print }' "$SUT" > "$mw1"
    if grep -q '_rsdd_install_settings "\$_tmp_settings"' "$mw1"; then
      no "teeth MW1: could not build mutant (mv line still present)"
    else
      dmw1="$TMP/mw1t"; mkdir -p "$dmw1"
      # #1691: the mutant skips the install step that removes its mktemp file; keep that file inside $TMP (trap-cleaned), not the caller TMPDIR.
      TMPDIR="$TMP" bash "$mw1" "$dmw1" --corpus flat --wire --scaffold >/dev/null 2>/dev/null
      if [ ! -f "$dmw1/.claude/settings.json" ]; then
        ok "teeth MW1: mutant → settings.json absent → wire test has teeth"
      else
        no "teeth MW1: mutant still created settings.json — wire test is THEATER"
      fi
    fi
  fi

  # MW2: always-wire guard removed → settings.json written without --wire → (a-default) absent assertion RED
  echo "-- teeth proof MW2: remove --wire guard → settings.json written without --wire --"
  if ! command -v jq >/dev/null 2>&1; then
    echo "  SKIP  teeth MW2: jq not on PATH"
  else
    mkdir -p "$TMP/mw2/toolbelt/lib"; cp "$HERE/../lib/corpus-markers.sh" "$TMP/mw2/toolbelt/lib/"; cp "$HERE/../lib/gh-visibility.sh" "$TMP/mw2/toolbelt/lib/"; ln -sfn "$HERE/../../templates" "$TMP/mw2/templates"
    mw2="$TMP/mw2/toolbelt/init.sh"
    # The bottom "if [ "$wire" = 1 ]; then" propose-never-apply guard now shares its FULL line
    # text with TWO other guards: the WIRE-ONLY-EXISTING-CORPUS repair guard (longer, "&& force"
    # — round 1) AND the kit issue #1047 round 2 no-marker refusal-computation guard (identical
    # full line text). A bare full-line anchor would mutate ALL matching occurrences, including
    # the round-2 guard — which then unconditionally refuses (exit 5) before the scaffold ever
    # reaches the bottom block, so settings.json never gets created and the mutant looks like it
    # DIDN'T regress (false theater verdict). Disambiguate on the NEXT line instead: only the
    # bottom guard is immediately followed by the §7 anti-silent-zero jq-probe comment.
    awk '
      /^if \[ "\$wire" = 1 \]; then$/ { pending=$0; next }
      pending != "" {
